var e={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`},MAPA:{nome:`MAPA`,cor:`#B91C1C`},UFMT:{nome:`UFMT`,cor:`#6D28D9`},UFBA:{nome:`UFBA`,cor:`#0369A1`},UFPE:{nome:`UFPE`,cor:`#A16207`},UFPR:{nome:`UFPR`,cor:`#15803D`},UFRGS:{nome:`UFRGS`,cor:`#9333EA`},UFRPE:{nome:`UFRPE`,cor:`#C2410C`}},t={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pos:{nome:`Pós-Graduação`,cor:`#D97706`}},n={anatomia_reprodutiva_masculina:{nome:`Anatomia Reprodutiva Masculina`,eixo:`pre`},espermatogenese:{nome:`Espermatogênese`,eixo:`pre`},endocrinologia_reprodutiva_masculina:{nome:`Endocrinologia Reprodutiva Masculina`,eixo:`pre`},semen:{nome:`Sêmen`,eixo:`prod`},inseminacao_artificial:{nome:`Inseminação Artificial`,eixo:`prod`},biotecnologias_reprodutivas:{nome:`Biotecnologias Reprodutivas`,eixo:`prod`},patologia_reprodutiva_masculina:{nome:`Patologia Reprodutiva Masculina`,eixo:`clin`},infertilidade_masculina:{nome:`Infertilidade Masculina`,eixo:`clin`},criopreservacao:{nome:`Criopreservação`,eixo:`prod`},andrologia_bovina:{nome:`Andrologia Bovina`,eixo:`clin`},andrologia_equina:{nome:`Andrologia Equina`,eixo:`clin`},andrologia_canina:{nome:`Andrologia Canina`,eixo:`clin`},andrologia_suina:{nome:`Andrologia Suína`,eixo:`clin`},andrologia_ovina_caprina:{nome:`Andrologia Ovina e Caprina`,eixo:`clin`},legislacao_andrologia:{nome:`Legislação em Andrologia`,eixo:`leg`}},r=[{id:`andro-001`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Testículos`,dificuldade:`medio`,enunciado:`Sobre a anatomia do testículo bovino, assinale a alternativa correta:`,alternativas:[`O testículo bovino apresenta orientação vertical, com o epidídimo posicionado cranialmente.`,`O testículo bovino apresenta orientação horizontal, com o epidídimo posicionado caudalmente.`,`A túnica albugínea do testículo é composta por tecido adiposo denso.`,`O mediastino do testículo é ausente em bovinos.`,`O testículo bovino é intra-abdominal em todas as idades.`],resposta_correta:`B`,explicacao:`Em bovinos, os testículos apresentam orientação horizontal (pendulares), com o epidídimo posicionado na face caudal. A túnica albugínea é de tecido conjuntivo fibroso (não adiposo). O mediastino testicular está presente. Os testículos são escrotais após o nascimento.`},{id:`andro-002`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Epidídimo`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre o epidídimo.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O epidídimo é dividido em três porções (cabeça, corpo e cauda), sendo que a cauda do epidídimo é o principal local de armazenamento dos espermatozoides maduros, e sua lesão pode resultar em obstrução do ducto deferente e infertilidade.`,explicacao:`O epidídimo possui cabeça (caput), corpo (corpus) e cauda (cauda). A cauda armazena os espermatozoides maduros até a ejaculação. Lesões obstrutivas da cauda do epidídimo impedem a passagem dos espermatozoides, causando azoospermia obstrutiva e infertilidade.`},{id:`andro-003`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Pênis`,dificuldade:`facil`,enunciado:`Quanto à classificação morfológica do pênis em diferentes espécies domésticas, assinale a alternativa correta:`,alternativas:[`O pênis do bovino é do tipo fibroelástico, apresentando flexura sigmoide.`,`O pênis do equino é do tipo fibroelástico, sem flexura sigmoide.`,`O pênis do cão é do tipo osso peniano (baculum), sem corpo cavernoso.`,`O pênis do suino é do tipo musculocavernoso, sem flexura sigmoide.`,`O pênis ovino é do tipo musculocavernoso, com flexura sigmoide.`],resposta_correta:`A`,explicacao:`O pênis bovino é fibroelástico com flexura sigmoide (S-shaped). O equino é musculocavernoso (sem flexura sigmoide). O canino possui osso peniano (baculum) E corpo cavernoso. O suíno é fibroelástico com flexura sigmoide. O ovino é fibroelástico com flexura sigmoide.`},{id:`andro-004`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Médico Veterinário IAGRO 2023`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Próstata`,dificuldade:`medio`,enunciado:`Sobre a glândula prostata em animais domésticos, é correto afirmar:`,alternativas:[`A próstata canina é a maior entre as espécies domésticas e é susceptível à hiperplasia prostática benigna.`,`A próstata bovina é vestigial e não apresenta função secretória.`,`A próstata equina é ausente, sendo substituída pelas vesículas seminais.`,`A próstata suína é a menor entre os domésticos.`,`A próstata ovina secreta apenas urina.`],resposta_correta:`A`,explicacao:`A próstata canina é bem desenvolvida, a maior dentre os domésticos, e é muito suscetível à hiperplasia prostática benigna (HPB) em cães idosos não castrados. A próstata está presente em todas as espécies domésticas e tem função secretória importante.`},{id:`andro-005`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Vesículas seminais`,dificuldade:`medio`,enunciado:`As vesículas seminais são glândulas acessórias do sistema reprodutor masculino. Assinale a alternativa que descreve corretamente a presença/ausência dessas glândulas nas espécies domésticas:`,alternativas:[`Estão presentes em bovinos, equinos e suínos, mas ausentes em cães.`,`Estão presentes em todas as espécies domésticas, inclusive cães.`,`Estão presentes apenas em equinos e suínos.`,`Estão ausentes em bovinos e presentes em cães.`,`Estão presentes apenas em suínos.`],resposta_correta:`A`,explicacao:`As vesículas seminais estão presentes em bovinos, equinos, suínos, ovinos e caprinos, mas são AUSENTES em cães e gatos. Em cães, as glândulas prostática e bulbouretral são as principais glândulas acessórias.`},{id:`andro-006`,banca:`CRMV`,ano:2021,prova:`CRMV-SP — Prova de Suficiência 2021`,tipo:`crmv`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Glândulas bulbouretrais`,dificuldade:`facil`,enunciado:`As glândulas bulbouretrais (glândulas de Cowper) estão localizadas:`,alternativas:[`Na região do bulbo do pênis, dorsal à uretra pélvica.`,`No interior do testículo, junto ao mediastino.`,`Na cabeça do epidídimo.`,`Na vesícula seminal.`,`No interior da próstata.`],resposta_correta:`A`,explicacao:`As glândulas bulbouretrais (de Cowper) são pares e estão localizadas na região do bulbo do uretra, dorsalmente à uretra pélvica. Produzem secreção mucoide que lubrifica a uretra antes da ejaculação.`},{id:`andro-007`,banca:`UFMG`,ano:2020,prova:`UFMG — Professor Assistente Reprodução Animal 2020`,tipo:`pos`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Ducto deferente`,dificuldade:`medio`,enunciado:`Sobre o ducto deferente (vaso deferente) em mamíferos domésticos, assinale a alternativa correta:`,alternativas:[`O ducto deferente conecta a cauda do epidídimo à uretra prostática, passando pelo canal inguinal.`,`O ducto deferente se origina na cabeça do epidídimo e desemboca na bexiga urinária.`,`O ducto deferente é exclusivo de equinos e está ausente nas demais espécies.`,`O ducto deferente é um ducto exclusivamente secretório, sem função de transporte.`,`O ducto deferente conecta o testículo diretamente à vesícula seminal.`],resposta_correta:`A`,explicacao:`O ducto deferente conecta a cauda do epidídimo à uretra prostática, passando pelo canal inguinal e formando a ampola antes de desembocar na uretra. Transporta espermatozoides do epidídimo até a ejaculação.`},{id:`andro-008`,banca:`UNESP`,ano:2022,prova:`UNESP — Médico Veterinário GESP 2022`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Escroto`,dificuldade:`facil`,enunciado:`A função principal do escroto nos mamíferos domésticos é:`,alternativas:[`Manter os testículos em temperatura 2-6°C abaixo da temperatura corporal central.`,`Produzir testosterona.`,`Armazenar espermatozoides maduros.`,`Secretar líquido seminal.`,`Filtrar o sangue arterial que chega ao testículo.`],resposta_correta:`A`,explicacao:`O escroto funciona como um termorregulador, mantendo os testículos 2-6°C abaixo da temperatura corporal central, essencial para a espermatogênese normal. A temperatura escrotal é regulada pelo músculo cremaster e pelo plexo pampiniforme.`},{id:`andro-009`,banca:`USP`,ano:2023,prova:`USP — Doutorado em Reprodução Animal 2023`,tipo:`pos`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Plexo pampiniforme`,dificuldade:`dificil`,enunciado:`O plexo pampiniforme é uma estrutura vascular importante no sistema reprodutor masculino. Sobre sua localização e função, assinale a alternativa correta:`,alternativas:[`Localiza-se no cordão espermático e funciona como um sistema de troca contracorrente, resfriando o sangue arterial antes de entrar no testículo.`,`Localiza-se no interior do testículo e produz testosterona.`,`Localiza-se na próstata e secreta líquido prostático.`,`Localiza-se no epidídimo e promove a maturação dos espermatozoides.`,`Localiza-se no escroto e controla a contração do músculo cremaster.`],resposta_correta:`A`,explicacao:`O plexo pampiniforme é um conjunto de veias que envolvem a artéria testicular no cordão espermático, funcionando como um sistema de troca contracorrente que resfria o sangue arterial antes de entrar no testículo, contribuindo para a termorregulação testicular.`},{id:`andro-010`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Médico Veterinário CEV-RJ 2021`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Túnica albugínea`,dificuldade:`facil`,enunciado:`A túnica albugínea do testículo é constituída por:`,alternativas:[`Tecido conjuntivo denso, rico em fibras colágenas, que envolve o testículo.`,`Tecido adiposo que preenche o espaço entre os túbulos seminíferos.`,`Epítlio colunar estratificado que reveste os túbulos seminíferos.`,`Tecido muscular liso que contrai durante a ejaculação.`,`Endotélio vascular que reveste os seios venosos do testículo.`],resposta_correta:`A`,explicacao:`A túnica albugínea é uma cápsula fibrosa de tecido conjuntivo denso, rica em fibras colágenas, que envolve o testículo. Na região dorsal forma o mediastino testicular, de onde partem septos que dividem o testículo em lóbulos.`},{id:`andro-011`,banca:`MAPA`,ano:2020,prova:`MAPA — Fiscal Federal Agropecuário 2020`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Células de Leydig`,dificuldade:`medio`,enunciado:`As células de Leydig (células intersticiais) estão localizadas:`,alternativas:[`No interstício entre os túbulos seminíferos do testículo.`,`Dentro dos túbulos seminíferos, junto às células de Sertoli.`,`Na cabeça do epidídimo.`,`Na próstata.`,`No interior do ducto deferente.`],resposta_correta:`A`,explicacao:`As células de Leydig estão localizadas no interstício (espaço entre os túbulos seminíferos) do testículo. São responsáveis pela produção de testosterona sob estímulo do LH hipofisário.`},{id:`andro-012`,banca:`UFMT`,ano:2022,prova:`UFMT — Médico Veterinário CONSECT 2022`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Células de Sertoli`,dificuldade:`dificil`,enunciado:`Julgue o item sobre as células de Sertoli.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`As células de Sertoli são responsáveis pela formação da barreira hematotesticular, sustentação e nutrição dos espermatozoides em desenvolvimento, fagocitose de corpos residuais, secreção de líquido testicular, inibina e ABP (proteína ligadora de andrógenos).`,explicacao:`As células de Sertoli são células somáticas dos túbulos seminíferos que formam junções oclusivas (barreira hematotesticular), sustentam e nutrem as células germinativas, fagocitam corpos residuais da espermiogenese, secretam inibina, ABP e líquido testicular.`},{id:`andro-013`,banca:`UFBA`,ano:2023,prova:`UFBA — Professor Assistente Medicina Veterinária 2023`,tipo:`pos`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Uretra masculina`,dificuldade:`facil`,enunciado:`A uretra do macho doméstico é dividida em:`,alternativas:[`Uretra pré-prostática, prostática, membranosa e peniana (esponjosa).`,`Uretra testicular, epididimária e peniana.`,`Uretra interna e externa apenas.`,`Uretra prostática e peniana apenas.`,`Uretra abdominal e pélvica apenas.`],resposta_correta:`A`,explicacao:`A uretra masculina é dividida em quatro porções: pré-prostática (intramural), prostática (atravessa a próstata), membranosa (entre a próstata e o bulbo do pênis) e peniana ou esponjosa (no interior do corpo esponjoso do pênis).`},{id:`andro-014`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Testículos — descida testicular`,dificuldade:`medio`,enunciado:`Sobre a descida testicular (orquidopexia) em animais domésticos, assinale a alternativa correta:`,alternativas:[`Em bovinos, os testículos descem ao escroto antes do nascimento, enquanto em cães a descida ocorre entre 2 e 6 semanas de vida.`,`Em equinos, os testículos permanecem intra-abdominais até a puberdade.`,`Em suínos, os testículos nunca descem ao escroto.`,`A criptorquidia é uma condição normal em bovinos adultos.`,`Em cães, os testículos devem estar no escroto apenas após 12 meses de idade.`],resposta_correta:`A`,explicacao:`Em bovinos, a descida testicular ocorre durante a vida fetal (antes do nascimento). Em cães, a descida ocorre entre 2 e 6 semanas após o nascimento. Em equinos, a descida ocorre antes do nascimento. A criptorquidia (testículo retido) é uma anomalia em qualquer espécie.`},{id:`andro-015`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Músculo cremaster`,dificuldade:`medio`,enunciado:`O músculo cremaster (cremaster externo) tem como função principal:`,alternativas:[`Elevar e retraír o testículo em direção ao canal inguinal em resposta ao frio ou ao estímulo do nervo genitofemoral.`,`Produzir testosterona em resposta ao LH.`,`Secretar líquido seminal.`,`Comprimir os túbulos seminíferos durante a ejaculação.`,`Envolver e proteger o plexo pampiniforme.`],resposta_correta:`A`,explicacao:`O músculo cremaster é um músculo esquelético que eleva e retraí o testículo em direção ao canal inguinal (reflexo cremastérico), em resposta ao frio, toque ou estímulo do nervo genitofemoral. É parte do mecanismo de termorregulação testicular.`},{id:`andro-016`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBAMA 2022`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Flexura sigmoide`,dificuldade:`facil`,enunciado:`A flexura sigmoide do pênis está presente nas seguintes espécies:`,alternativas:[`Bovinos, suínos, ovinos e caprinos.`,`Apenas em equinos.`,`Apenas em cães e gatos.`,`Apenas em equinos e cães.`,`Em todas as espécies domésticas.`],resposta_correta:`A`,explicacao:`A flexura sigmoide (flexura S) está presente em espécies com pênis fibroelástico: bovinos, suínos, ovinos e caprinos. Equinos e cães possuem pênis musculocavernoso e ossificado, respectivamente, sem flexura sigmoide.`},{id:`andro-017`,banca:`UFPE`,ano:2021,prova:`UFPE — Médico Veterinário CESPE 2021`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Túbulos seminíferos`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre os túbulos seminíferos.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`Os túbulos seminíferos contêm as células de Sertoli e as células germinativas em diferentes estágios de maturação, organizadas em camadas concêntricas desde a membrana basal (espermatogônias) até o lúmen (espermatozoides maduros). As células de Leydig não se encontram dentro dos túbulos, mas sim no interstício.`,explicacao:`Os túbulos seminíferos são revestidos pelo epitélio seminífero, que contém células de Sertoli e células germinativas (espermatogônias → espermatócitos → espermátides → espermatozoides). As células de Leydig ficam no interstício, fora dos túbulos.`},{id:`andro-018`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário Prefeitura 2020`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Nervo pudendo`,dificuldade:`medio`,enunciado:`O nervo pudendo inerva estruturas do sistema reprodutor masculino. Assinale a alternativa correta:`,alternativas:[`Inerva os músculos do períneo, o bulbo do pênis e os esfíncteres uretrais.`,`Inerva exclusivamente o testículo e o epidídimo.`,`É responsável pela inervação parassimpática da próstata.`,`Inerva apenas o escroto.`,`É exclusivamente sensitivo, sem componente motor.`],resposta_correta:`A`,explicacao:`O nervo pudendo (sacro, S2-S4) é o principal nervo do períneo. Inerva os músculos do períneo (bulboesponjoso, isquiocavernoso), o bulbo do pênis, o esfíncter uretral externo e a pele do períneo. Possui componentes motor e sensitivo.`},{id:`andro-019`,banca:`UFPR`,ano:2022,prova:`UFPR — Médico Veterinário 2022`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Corpo cavernoso`,dificuldade:`medio`,enunciado:`Sobre a anatomia do pênis em relação ao corpo cavernoso, assinale a alternativa correta:`,alternativas:[`O corpo cavernoso do pênis é preenchido por tecido erétil que se congestiona com sangue durante a ereção.`,`O corpo cavernoso está presente apenas em cães e gatos.`,`O corpo cavernoso é composto por tecido ósseo em todas as espécies.`,`O corpo cavernoso produz testosterona.`,`O corpo cavernoso está ausente em equinos.`],resposta_correta:`A`,explicacao:`O corpo cavernoso do pênis é composto por tecido erétil (seios venosos) que se congestiona com sangue arterial durante a ereção, causando tumescência do pênis. Está presente em todas as espécies domésticas. O osso peniano (baculum) é uma estrutura adicional presente em cães e gatos.`},{id:`andro-020`,banca:`UFRGS`,ano:2023,prova:`UFRGS — Professor Reprodução Animal 2023`,tipo:`pos`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Artéria testicular`,dificuldade:`dificil`,enunciado:`A artéria testicular origina-se da aorta abdominal e apresenta um trajeto tortuoso no cordão espermático. A importância desse trajeto tortuoso está relacionada a:`,alternativas:[`Permitir a troca de calor contracorrente com as veias do plexo pampiniforme, resfriando o sangue arterial antes de entrar no testículo.`,`Aumentar a pressão sanguínea dentro do testículo para forçar a espermatogênese.`,`Facilitar a produção de testosterona pelas células de Leydig.`,`Permitir o armazenamento de espermatozoides no lúmen da artéria.`,`Reduzir o fluxo sanguíneo para evitar edema testicular.`],resposta_correta:`A`,explicacao:`A artéria testicular apresenta trajeto tortuoso no cordão espermático, onde é envolvida pelas veias do plexo pampiniforme. Esse arranjo permite a troca de calor contracorrente, resfriando o sangue arterial antes de entrar no testículo, mantendo a temperatura 2-6°C abaixo da corporal.`},{id:`andro-021`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Médico Veterinário 2021`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Bolsa prepucial`,dificuldade:`facil`,enunciado:`A bolsa prepucial é uma estrutura presente em:`,alternativas:[`Bovinos e equinos, sendo o prepúcio uma dobra de pele que recobre a porção terminal do pênis flácido.`,`Apenas em cães e gatos.`,`Apenas em suínos.`,`Em todas as espécies domésticas de forma idêntica.`,`Apenas em felinos.`],resposta_correta:`A`,explicacao:`A bolsa prepucial (saco prepucial) é uma dobra de pele que recobre a porção terminal do pênis flácido em bovinos, equinos, suínos, ovinos e caprinos. Em cães, o prepúcio também recobre o pênis, mas com morfologia diferente.`},{id:`andro-022`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Mediastino testicular`,dificuldade:`medio`,enunciado:`O mediastino testicular (corpo de Highmore) é:`,alternativas:[`Uma extensão da túnica albugínea no centro do testículo, de onde partem septos que dividem o órgão em lóbulos.`,`Uma glândula acessória do sistema reprodutor masculino.`,`Um músculo liso que contrai durante a ejaculação.`,`Uma estrutura exclusiva do epidídimo.`,`Um vaso linfático que drena o testículo.`],resposta_correta:`A`,explicacao:`O mediastino testicular (corpo de Highmore) é uma extensão da túnica albugínea que penetra no centro do testículo pela face dorsal. A partir dele partem septos conjuntivos que dividem o testículo em lóbulos, cada qual contendo 1-3 túbulos seminíferos.`},{id:`andro-023`,banca:`CESPE`,ano:2021,prova:`CESPE — Professor Universitário 2021`,tipo:`pos`,topico:`anatomia_reprodutiva_masculina`,subtopico:`Inervação autonômica`,dificuldade:`dificil`,enunciado:`Sobre a inervação autonômica do sistema reprodutor masculino, assinale a alternativa correta:`,alternativas:[`A ereção é mediada pelo parassimpático (nervos erigentes), enquanto a ejaculação é mediada pelo simpático (nervos hipogástricos).`,`Tanto a ereção quanto a ejaculação são mediadas exclusivamente pelo simpático.`,`A ereção é mediada pelo simpático e a ejaculação pelo parassimpático.`,`A inervação autonômica não participa do reflexo erétil.`,`O nervo vago é o principal responsável pela ereção peniana.`],resposta_correta:`A`,explicacao:`A ereção é um reflexo parassimpático mediado pelos nervos erigentes (S2-S4), que causam vasodilatação dos corpos cavernosos. A ejaculação é mediada pelo simpático (nervos hipogástricos, T12-L2), que provoca contração dos ductos genitais e emissão seminal.`},{id:`andro-024`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Tipos de espermatogônias`,dificuldade:`dificil`,enunciado:`Sobre os tipos de espermatogônias em mamíferos, assinale a alternativa correta:`,alternativas:[`As espermatogônias do tipo A escuras (Ad) são consideradas células-tronco que se autorrenovam, enquanto as espermatogônias A pálidas (Ap) se dividem por mitose para produzir espermatogônias do tipo B.`,`As espermatogônias do tipo B se dividem diretamente em espermatozoides sem passar por meiose.`,`Existem apenas dois tipos de espermatogônias em todos os mamíferos: A e B.`,`As espermatogônias do tipo A escuras produzem testosterona.`,`As espermatogônias são células diplóides que sofrem apenas mitose.`],resposta_correta:`A`,explicacao:`As espermatogônias Ad (escuras) são células-tronco que se autorrenovam. As Ap (pálidas) se dividem por mitose originando espermatogônias tipo B, que por sua vez se dividem e dão origem aos espermatócitos primários, iniciando a meiose.`},{id:`andro-025`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário IBAMA 2022`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Meiose`,dificuldade:`medio`,enunciado:`Julgue o item a seguir sobre a meiose na espermatogênese.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`Na meiose I, o espermatócito primário (2n) dá origem a dois espermatócitos secundários (n), cada qual sofrendo meiose II para formar duas espermátides, resultando em quatro espermátides haploides a partir de cada espermatócito primário.`,explicacao:`A meiose é reducional (I) e equacional (II). O espermatócito primário (2n=4c DNA) sofre meiose I → 2 espermatócitos secundários (n=2c). Cada um sofre meiose II → 2 espermátides (n=1c). Total: 4 espermátides haploides por espermatócito primário.`},{id:`andro-026`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário Prefeitura 2021`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Espermiogênese`,dificuldade:`medio`,enunciado:`A espermiogênese é o processo de transformação de espermátides em espermatozoides maduros. Assinale a alternativa que descreve corretamente as etapas da espermiogênese:`,alternativas:[`Golgi → Acrossomo → Capacitação → Maturação citoplasmática.`,`Golgi → Acrossomo → Condensação nuclear → Maturação citoplasmática → Liberação do espermatozoide.`,`Mitose → Meiose → Diferenciação → Ejaculação.`,`Espermatogônias → Espermatócitos → Espermátides → Liberação.`,`Espermatogônias → Espermatócitos → Espermiogênese → Espermatogênese.`],resposta_correta:`B`,explicacao:`A espermiogênese ocorre em etapas: 1) Fase Golgi (formação dos grânulos acrossomais), 2) Acrossomo (cap acrossômico cobre o núcleo), 3) Condensação nuclear (compactação do DNA), 4) Maturação citoplasmática (eliminação do citoplasma residual), resultando no espermatozoide maduro.`},{id:`andro-027`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Ciclo do epitélio seminífero`,dificuldade:`dificil`,enunciado:`Sobre o ciclo do epitélio seminífero em mamíferos, assinale a alternativa correta:`,alternativas:[`O ciclo do epitélio seminífero é definido como a sequência de eventos que ocorre entre duas aparições do mesmo estágio de desenvolvimento em um dado ponto do túbulo seminífero.`,`O ciclo do epitélio seminífero é idêntico em todas as espécies domésticas.`,`Em bovinos, o ciclo dura aproximadamente 16 dias.`,`O ciclo do epitélio seminífero é descontínuo, com períodos de repose entre as divisões celulares.`,`O ciclo é regulado exclusivamente por FSH, sem participação de LH.`],resposta_correta:`A`,explicacao:`O ciclo do epitélio seminífero é a sequência ordenada de eventos celulares entre duas aparições do mesmo estágio em um ponto do túbulo. A duração varia por espécie: ~8,6 dias em bovinos, ~10 dias em equinos, ~13,5 dias em cães, ~8,8 dias em suínos. É contínuo e regulado por FSH e LH.`},{id:`andro-028`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`espermatogenese`,subtopico:`Regulação hormonal da espermatogênese`,dificuldade:`medio`,enunciado:`Sobre a regulação hormonal da espermatogênese, assinale a alternativa correta:`,alternativas:[`O FSH atua nas células de Sertoli estimulando a produção de ABP e inibina, enquanto o LH estimula as células de Leydig a produzirem testosterona.`,`O FSH atua diretamente nas espermatogônias, sem mediação das células de Sertoli.`,`A testosterona não é necessária para a espermatogênese.`,`O LH atua nas células de Sertoli para produzir espermatozoides.`,`A inibina estimula a secreção de FSH pela hipófise.`],resposta_correta:`A`,explicacao:`O FSH atua nos receptores das células de Sertoli, estimulando a produção de ABP (proteína ligadora de andrógenos), inibina e fatores tróficos necessários à espermatogênese. O LH atua nas células de Leydig estimulando a esteroidogênese (produção de testosterona).`},{id:`andro-029`,banca:`CRMV`,ano:2020,prova:`CRMV-PR — Prova de Suficiência 2020`,tipo:`crmv`,topico:`espermatogenese`,subtopico:`Espermatogônias tipo B`,dificuldade:`facil`,enunciado:`As espermatogônias do tipo B são:`,alternativas:[`Células que se dividem por mitose originando espermatócitos primários, iniciando a meiose.`,`Células haploides que se transformam diretamente em espermatozoides.`,`Células somáticas de sustentação presentes no epitélio seminífero.`,`Células produtoras de testosterona.`,`Células que formam a barreira hematotesticular.`],resposta_correta:`A`,explicacao:`As espermatogônias tipo B são células germinativas diplóides que se dividem por mitose originando espermatócitos primários, que então entram na meiose I. São o último estágio mitótico antes da entrada na meiose.`},{id:`andro-030`,banca:`UFMG`,ano:2022,prova:`UFMG — Professor Assistente 2022`,tipo:`pos`,topico:`espermatogenese`,subtopico:`Acrossomo`,dificuldade:`medio`,enunciado:`O acrossomo do espermatozoide é derivado:`,alternativas:[`Do complexo de Golgi da espermátide durante a espermiogênese.`,`Da mitocôndria da espermatogônia.`,`Do núcleo da célula de Sertoli.`,`Da membrana basal do túbulo seminífero.`,`Da túnica albugínea do testículo.`],resposta_correta:`A`,explicacao:`O acrossomo é formado a partir do complexo de Golgi da espermátide durante a fase Golgi da espermiogênese. Contém enzimas hidrolíticas (hialuronidase, acrosina) necessárias para a penetração da zona pelúcida do ovócito durante a fecundação.`},{id:`andro-031`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso Veterinário GESP 2021`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Duração da espermatogênese`,dificuldade:`medio`,enunciado:`A duração total da espermatogênese (de espermatogônia a espermatozoide livre) em bovinos é de aproximadamente:`,alternativas:[`61 dias.`,`14 dias.`,`35 dias.`,`90 dias.`,`120 dias.`],resposta_correta:`A`,explicacao:`A duração total da espermatogênese em bovinos é de aproximadamente 61 dias. Em equinos é ~57 dias, em cães ~62 dias, em suínos ~34 dias e em ovinos ~49 dias. O tempo varia de acordo com o ciclo do epitélio seminífero multiplicado pelo número de ciclos.`},{id:`andro-032`,banca:`USP`,ano:2022,prova:`USP — Mestrado em Reprodução Animal 2022`,tipo:`pos`,topico:`espermatogenese`,subtopico:`Espermátides`,dificuldade:`facil`,enunciado:`As espermátides são células:`,alternativas:[`Haploides (n) resultantes da meiose II, que sofrem espermiogênese para se transformarem em espermatozoides.`,`Diplóides (2n) que se dividem por mitose.`,`Poliplóides que se fundem para formar espermatozoides.`,`Células somáticas do túbulo seminífero.`,`Células que produzem hormônios andrógenos.`],resposta_correta:`A`,explicacao:`As espermátides são células haploides (n) resultantes da meiose II do espermatócito secundário. São células não-motivas que sofrem espermiogênese (transformação morfológica) para se tornarem espermatozoides maduros.`},{id:`andro-033`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Médico Veterinário 2023`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Espermatozoide — estrutura`,dificuldade:`dificil`,enunciado:`Julgue o item sobre a estrutura do espermatozoide.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O espermatozoide é dividido em cabeça (contendo o núcleo e o acrossomo), peça intermediária (contendo mitocôndrias arranjadas em espiral ao redor dos filamentos axonemais) e cauda (flagelo responsável pela motilidade).`,explicacao:`O espermatozoide possui: cabeça (núcleo condensado + acrossomo), peça intermediária (centríolo proximal + mitocôndrias em espiral para fornecimento de ATP), peça principal e peça terminal (flagelo com axonema 9+2).`},{id:`andro-034`,banca:`MAPA`,ano:2021,prova:`MAPA — Fiscal Federal Agropecuário 2021`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Corpos residuais`,dificuldade:`medio`,enunciado:`Os corpos residuais (corpos citoplasmáticos) na espermatogênese são:`,alternativas:[`Fragmentos citoplasmáticos eliminados pelas espermátides durante a espermiogênese, que são fagocitados pelas células de Sertoli.`,`Restos de espermatogônias degeneradas que nunca completaram a mitose.`,`Inclusões lipídicas nas células de Leydig.`,`Produtos de secreção das glândulas bulbouretrais.`,`Resíduos da degradação da membrana basal dos túbulos seminíferos.`],resposta_correta:`A`,explicacao:`Durante a espermiogênese, a espermátide elimina grande parte de seu citoplasma (corpo residual), que é fagocitado pelas células de Sertoli. Esse processo é essencial para a formação do espermatozoide aerodinâmico e para a manutenção da homeostase do epitélio seminífero.`},{id:`andro-035`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso Veterinário 2021`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Barreira hematotesticular`,dificuldade:`medio`,enunciado:`A barreira hematotesticular é formada por:`,alternativas:[`Junções oclusivas entre células de Sertoli adjacentes, que dividem o epitélio seminífero em compartimentos basal e adluminal.`,`A túnica albugínea e o mediastino testicular.`,`O endotélio dos capilares testiculares.`,`A cápsula fibrosa do epidídimo.`,`As células de Leydig que envolvem os túbulos seminíferos.`],resposta_correta:`A`,explicacao:`A barreira hematotesticular é formada por junções oclusivas (tight junctions) entre células de Sertoli adjacentes. Ela divide o epitélio seminífero em compartimento basal (espermatogônias) e adluminal (espermatócitos, espermátides), protegendo as células germinativas haploides do sistema imune.`},{id:`andro-036`,banca:`UFBA`,ano:2020,prova:`UFBA — Professor Assistente 2020`,tipo:`pos`,topico:`espermatogenese`,subtopico:`Espermatozoide acrossomo`,dificuldade:`dificil`,enunciado:`O acrossomo do espermatozoide contém as seguintes enzimas:`,alternativas:[`Hialuronidase, acrosina e neuraminidase, necessárias para a penetração das camadas do ovócito.`,`Amilase, lipase e tripsina, necessárias para a digestão do alimento.`,`Creatina quinase e ATPase, necessárias para a motilidade.`,`Testosterona e di-hidrotestosterona.`,`Colagenase e elastase, responsáveis pela liquefação do sêmen.`],resposta_correta:`A`,explicacao:`O acrossomo contém enzimas hidrolíticas: hialuronidase (degrada ácido hialurônico da matriz do cumulus oophorus), acrosina (protease que degrada glicoproteínas da zona pelúcida) e neuraminidase. São essenciais para a reação acrossômica e penetração do ovócito.`},{id:`andro-037`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso Médico Veterinário 2022`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Espermatócitos primários`,dificuldade:`facil`,enunciado:`Os espermatócitos primários são células:`,alternativas:[`Diplóides que estão em processo de meiose I, sendo as maiores células do epitélio seminífero.`,`Haploides que completaram a meiose II.`,`Diplóides que ainda não iniciaram a meiose.`,`Células somáticas de sustentação.`,`Células que produzem andrógenos.`],resposta_correta:`A`,explicacao:`Os espermatócitos primários são diplóides (2n) e estão em processo de meiose I (prófase I é longa). São as maiores células do epitélio seminífero. Ao final da meiose I, originam dois espermatócitos secundários (n).`},{id:`andro-038`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Liberação de espermatozoides`,dificuldade:`medio`,enunciado:`A liberação de espermatozoides maduros do epitélio seminífero para o lúmen do túbulo é chamada de:`,alternativas:[`Espermiação.`,`Espermiogênese.`,`Espermatogênese.`,`Capacitação.`,`Ejaculação.`],resposta_correta:`A`,explicacao:`A espermiação é o processo final da espermatogênese, no qual os espermatozoides maduros são liberados do epitélio seminífero (das células de Sertoli) para o lúmen do túbulo seminífero. Não confundir com ejaculação (que é a expulsão do sêmen pela uretra).`},{id:`andro-039`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Doutorado em Reprodução 2022`,tipo:`pos`,topico:`espermatogenese`,subtopico:`Diapaspermatozoide`,dificuldade:`dificil`,enunciado:`Em relação à ultraestrutura do flagelo do espermatozoide, o arranjo dos microtúbulos é:`,alternativas:[`9 pares de microtúbulos periféricos + 2 microtúbulos centrais (arranjo 9+2).`,`9 microtúbulos centrais + 2 pares periféricos (arranjo 2+9).`,`12 pares de microtúbulos dispostos em círculo.`,`6 pares periféricos + 1 central (arranjo 6+1).`,`Apenas microtúbulos centrais sem arranjo definido.`],resposta_correta:`A`,explicacao:`O flagelo do espermatozoide possui o axonema com arranjo 9+2: 9 dupletos de microtúbulos periféricos (cada um com braços de dineína) e 2 microtúbulos singletos centrais. Esse padrão é conservado na maioria dos espermatozoides de mamíferos.`},{id:`andro-040`,banca:`UFRPE`,ano:2020,prova:`UFRPE — Concurso Veterinário 2020`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Epitélio seminífero`,dificuldade:`facil`,enunciado:`O epitélio seminífero é composto por:`,alternativas:[`Células germinativas em diferentes estágios de maturação e células de Sertoli.`,`Apenas espermatozoides maduros e células de Leydig.`,`Células de Sertoli e células de Leydig apenas.`,`Apenas espermatogônias e espermatócitos.`,`Células musculares lisas e células germinativas.`],resposta_correta:`A`,explicacao:`O epitélio seminífero é um epitélio complexo composto por células germinativas em diferentes estágios de desenvolvimento (espermatogônias, espermatócitos, espermátides, espermatozoides) intercaladas com células somáticas de Sertoli.`},{id:`andro-041`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário Prefeitura 2023`,tipo:`concurso`,topico:`espermatogenese`,subtopico:`Espermatogênese — definição`,dificuldade:`facil`,enunciado:`A espermatogênese é definida como:`,alternativas:[`O processo completo de formação dos espermatozoides, desde as espermatogônias até a liberação dos espermatozoides maduros no lúmen dos túbulos seminíferos.`,`Apenas a transformação de espermátides em espermatozoides.`,`O processo de divisão mitótica das espermatogônias.`,`A maturação final dos espermatozoides no epidídimo.`,`A capacitação dos espermatozoides no trato reprodutivo feminino.`],resposta_correta:`A`,explicacao:`A espermatogênese é o processo completo de formação dos espermatozoides, englobando: multiplicação mitótica (espermatogônias → espermatócitos), meiose (espermatócitos → espermátides) e espermiogênese (espermátides → espermatozoides).`},{id:`andro-042`,banca:`UFPE`,ano:2022,prova:`UFPE — Professor Assistente 2022`,tipo:`pos`,topico:`espermatogenese`,subtopico:`Espermatogênese — espécies`,dificuldade:`medio`,enunciado:`Assinale a alternativa correta sobre a produção espermática diária (espermatogênese) em diferentes espécies:`,alternativas:[`Bovinos produzem aproximadamente 5-8 bilhões de espermatozoides por dia, enquanto cães produzem cerca de 300-600 milhões.`,`Equinos produzem menos espermatozoides que cães.`,`Suínos produzem a mesma quantidade de espermatozoides que bovinos.`,`Ovinos produzem mais espermatozoides que bovinos.`,`A produção espermática é idêntica em todas as espécies de porte similar.`],resposta_correta:`A`,explicacao:`A produção espermática diária varia por espécie e está relacionada à massa testicular: bovinos ~5-8 bilhões/dia, equinos ~7-8 bilhões, suínos ~15-30 bilhões, ovinos ~2-3 bilhões, cães ~300-600 milhões. A produção é proporcional à massa do tecido testicular.`},{id:`andro-043`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Eixo HPG masculino`,dificuldade:`medio`,enunciado:`Sobre o eixo hipotálamo-hipófise-gônada (HPG) no macho, assinale a alternativa correta:`,alternativas:[`O GnRH hipotalâmico estimula a liberação de FSH e LH pela hipófise anterior, que atuam respectivamente nas células de Sertoli e de Leydig.`,`O GnRH é produzido pela hipófise posterior.`,`O FSH atua nas células de Leydig para produzir testosterona.`,`O LH atua nas células de Sertoli para produzir inibina.`,`A testosterona exerce feedback positivo sobre o GnRH.`],resposta_correta:`A`,explicacao:`O GnRH (hipotálamo) é liberado de forma pulsátil na eminência mediana → estimula gonadotrofos da hipófise anterior → liberação de FSH (age em células de Sertoli) e LH (age em células de Leydig). A testosterona e a inibina exercem feedback NEGATIVO.`},{id:`andro-044`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Testosterona`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre a testosterona.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A testosterona é produzida principalmente pelas células de Leydig sob estímulo do LH. Nos tecidos-alvo, pode ser convertida em di-hidrotestosterona (DHT) pela enzima 5-alfa-redutase, que possui maior afinidade pelos receptores andrógenos que a própria testosterona.`,explicacao:`A testosterona é o principal andrógeno, produzida pelas células de Leydig sob estímulo do LH. A DHT (5α-dihidrotestosterona) é formada pela 5α-redutase em tecidos-alvo (próstata, pele, genitália externa) e é 2-3x mais potente que a testosterona.`},{id:`andro-045`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`FSH masculino`,dificuldade:`medio`,enunciado:`A FSH no macho atua principalmente:`,alternativas:[`Nas células de Sertoli, estimulando a produção de ABP, inibina e fatores de suporte à espermatogênese.`,`Nas células de Leydig, estimulando a produção de testosterona.`,`Diretamente nos espermatozoides, aumentando sua motilidade.`,`Na próstata, estimulando a secreção de líquido prostático.`,`No hipotálamo, inibindo a liberação de GnRH.`],resposta_correta:`A`,explicacao:`A FSH atua nos receptores das células de Sertoli, estimulando a produção de ABP (proteína ligadora de andrógenos), inibina, activina e fatores tróficos que sustentam a espermatogênese. A ABP mantém altas concentrações de testosterona intratesticular.`},{id:`andro-046`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Inibina B`,dificuldade:`medio`,enunciado:`A inibina B no macho é produzida por:`,alternativas:[`Células de Sertoli, exercendo feedback negativo seletivo sobre a secreção de FSH.`,`Células de Leydig, exercendo feedback sobre a secreção de LH.`,`Células de Sertoli, exercendo feedback positivo sobre a secreção de FSH.`,`Hipotálamo, inibindo a liberação de GnRH.`,`Glândula pituitária posterior.`],resposta_correta:`A`,explicacao:`A inibina B é produzida pelas células de Sertoli sob estímulo de FSH. Exerce feedback negativo seletivo sobre a secreção de FSH pelos gonadotrofos hipofisários, sem afetar significativamente a secreção de LH.`},{id:`andro-047`,banca:`AVAMEC`,ano:2021,prova:`AVAMEC — Prova de Título em Reprodução Animal 2021`,tipo:`pos`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Hormônio antimulleriano`,dificuldade:`dificil`,enunciado:`O hormônio antimulleriano (AMH/MIS) no macho:`,alternativas:[`É produzido pelas células de Sertoli durante o desenvolvimento embrionário e é responsável pela regressão do ducto de Müller.`,`É produzido pelas células de Leydig e estimula a produção de testosterona.`,`É produzido pela hipófise e atua no testículo fetal.`,`Estimula o desenvolvimento do ducto de Wolff.`,`É produzido apenas após a puberdade.`],resposta_correta:`A`,explicacao:`O AMH (hormônio antimulleriano) é produzido pelas células de Sertoli a partir da 8ª semana de gestação em fetos masculinos. Provoca a regressão dos ductos de Müller (que dariam origem ao útero e tubas). É um marcador de função de Sertoli e pode ser usado para diagnóstico de criptorquidia.`},{id:`andro-048`,banca:`CRMV`,ano:2022,prova:`CRMV-MG — Prova de Suficiência 2022`,tipo:`crmv`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`DHT`,dificuldade:`medio`,enunciado:`A di-hidrotestosterona (DHT) é formada pela conversão de testosterona pela enzima:`,alternativas:[`5-alfa-redutase, em tecidos como próstata, pele e genitália externa.`,`Aromatase, em tecidos adiposos.`,`17-beta-hidroxiesteróide desidrogenase, no testículo.`,`3-beta-hidroxiesteróide desidrogenase, nas adrenais.`,`Colesterol desmolase, nas mitocôndrias.`],resposta_correta:`A`,explicacao:`A 5-alfa-redutase converte testosterona em DHT nos tecidos-alvo (próstata, pele, genitália externa, folículos pilosos). A DHT é mais potente que a testosterona (maior afinidade pelo receptor de andrógenos) e é essencial para a diferenciação da genitália externa masculina.`},{id:`andro-049`,banca:`UFMG`,ano:2023,prova:`UFMG — Professor Assistente 2023`,tipo:`pos`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`LH e esteroidogênese`,dificuldade:`medio`,enunciado:`Sobre a ação do LH nas células de Leydig, assinale a alternativa correta:`,alternativas:[`O LH liga-se a receptores nas células de Leydig e ativa a via AMPc/PKA, estimulando a conversão de colesterol em pregnenolona (primeiro passo da esteroidogênese).`,`O LH liga-se a receptores nas células de Sertoli para produzir testosterona.`,`O LH atua diretamente nas espermatogônias para promover mitose.`,`O LH inibe a produção de testosterona pelas células de Leydig.`,`O LH não é necessário para a esteroidogênese testicular.`],resposta_correta:`A`,explicacao:`O LH liga-se ao receptor LH/CG (LHCGR) nas células de Leydig → ativa adenilato ciclase → AMPc → PKA → fosforilação da StAR → transporte de colesterol para mitocôndria → conversão em pregnenolona pela enzima desmolase (CYP11A1).`},{id:`andro-050`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Pulsatilidade de GnRH`,dificuldade:`dificil`,enunciado:`Sobre a secreção pulsátil de GnRH no macho, assinale a alternativa correta:`,alternativas:[`A pulsatilidade de GnRH é essencial para a manutenção da secreção de LH; frequências altas de pulsos favorecem LH, enquanto baixas frequências favorecem FSH.`,`A liberação de GnRH é contínua e constante, sem padrão pulsátil.`,`A pulsatilidade de GnRH é exclusiva da fêmea e não ocorre no macho.`,`A administração contínua de GnRH estimula a liberação de LH de forma sustentada.`,`A frequência dos pulsos de GnRH não influencia a proporção LH/FSH liberada.`],resposta_correta:`A`,explicacao:`A secreção de GnRH é pulsátil (pulsos a cada 1-4 horas). Pulses de alta frequência favorecem LH; baixa frequência favorece FSH. A administração contínua de GnRH (agonistas) inicialmente estimula, depois suprime a secreção de LH/FSH por dessensibilização/downregulation dos receptores.`},{id:`andro-051`,banca:`USP`,ano:2021,prova:`USP — Doutorado em Reprodução 2021`,tipo:`pos`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Testosterona — formas`,dificuldade:`dificil`,enunciado:`No sangue, a testosterona circula em três formas:`,alternativas:[`Livre (~2%), ligada à albumina (~40%) e ligada à SHBG (~58%).`,`Livre (~50%), ligada à globulina (~25%) e ligada à albumina (~25%).`,`Apenas na forma livre, pois é uma molécula hidrofóbica.`,`Ligada exclusivamente à SHBG.`,`Ligada exclusivamente à albumina.`],resposta_correta:`A`,explicacao:`A testosterona circula: ~2% livre (biologicamente ativa), ~40% ligada fracamente à albumina (biodisponível), ~58% ligada fortemente à SHBG (sex hormone-binding globulin, não biodisponível). A fração livre + albumina = biodisponível (~42%).`},{id:`andro-052`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Médico Veterinário 2022`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Aromatase`,dificuldade:`medio`,enunciado:`A enzima aromatase (CYP19A1) no macho converte:`,alternativas:[`Testosterona em estradiol e androstenediona em estrona, presente em tecidos como cérebro, osso e tecido adiposo.`,`Testosterona em di-hidrotestosterona na próstata.`,`Colesterol em pregnenolona nas mitocôndrias.`,`Pregnenolona em progesterona no testículo.`,`Estradiol em testosterona no hipotálamo.`],resposta_correta:`A`,explicacao:`A aromatase converte andrógenos em estrogênios: testosterona → estradiol e androstenediona → estrona. No macho, está presente no cérebro, osso, tecido adiposo e células de Sertoli. Os estrogênios masculinos são importantes para a homeostase óssea e feedback hipotalâmico.`},{id:`andro-053`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Federal Agropecuário 2023`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`ABP`,dificuldade:`medio`,enunciado:`A ABP (Androgen-Binding Protein) é produzida pelas células de Sertoli sob estímulo de FSH. Sua função principal é:`,alternativas:[`Manter altas concentrações de testosterona no lúmen dos túbulos seminíferos e no epidídimo, essenciais para a espermatogênese.`,`Transportar testosterona no sangue para os tecidos periféricos.`,`Converter testosterona em DHT nos túbulos seminíferos.`,`Inibir a produção de LH pela hipófise.`,`Estimular a produção de espermatozoides pelo epidídimo.`],resposta_correta:`A`,explicacao:`A ABP é produzida pelas células de Sertoli sob estímulo de FSH e andrógenos. Liga-se à testosterona no lúmen dos túbulos seminíferos e é transportada com o fluido testicular para o epidídimo, mantendo concentrações locais de andrógenos 50-100x superiores às plasmáticas.`},{id:`andro-054`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso Veterinário 2020`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Esteroidogênese testicular`,dificuldade:`dificil`,enunciado:`Na esteroidogênese testicular, a conversão de colesterol em pregnenolona ocorre:`,alternativas:[`Na membrana mitocondrial interna, catalisada pela enzima desmolase (CYP11A1), sob regulação da proteína StAR.`,`No retículo endoplasmático, catalisada pela 5-alfa-redutase.`,`No complexo de Golgi, catalisada pela aromatase.`,`No citoplasma, sem necessidade de organelas.`,`Na membrana plasmática, catalisada pela adenilato ciclase.`],resposta_correta:`A`,explicacao:`O colesterol é transportado da membrana mitocondrial externa para a interna pela proteína StAR. Na membrana interna, a enzima CYP11A1 (desmolase/cholesterol side-chain cleavage) converte colesterol em pregnenolona, primeiro passo da esteroidogênese.`},{id:`andro-055`,banca:`UFBA`,ano:2022,prova:`UFBA — Médico Veterinário 2022`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Testosterona puberdade`,dificuldade:`facil`,enunciado:`A puberdade no macho é caracterizada por:`,alternativas:[`Aumento da secreção de GnRH, LH e testosterona, levando ao início da espermatogênese e ao desenvolvimento de caracteres sexuais secundários.`,`Diminuição da produção de testosterona.`,`Redução da secreção de LH e aumento de FSH.`,`Cessação da espermatogênese.`,`Aumento exclusivo de estradiol.`],resposta_correta:`A`,explicacao:`A puberdade é desencadeada pelo aumento da pulsatilidade de GnRH → aumento de LH e FSH → aumento da esteroidogênese (testosterona) e início/manutenção da espermatogênese completa. Desenvolvimento de caracteres sexuais secundários (musculatura, crina, comportamento sexual).`},{id:`andro-056`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Feedback negativo andrógenos`,dificuldade:`medio`,enunciado:`A testosterona exerce feedback negativo sobre:`,alternativas:[`A secreção de GnRH hipotalâmico e de LH hipofisário.`,`Apenas sobre a secreção de FSH, sem efeito sobre LH.`,`A produção de espermatozoides no epidídimo.`,`A secreção de testosterona pelas células de Leydig, de forma autócrina.`,`A produção de inibina pelas células de Sertoli.`],resposta_correta:`A`,explicacao:`A testosterona exerce feedback negativo em dois níveis: no hipotálamo (inibe a pulsatilidade de GnRH) e na hipófise (reduz a sensibilidade dos gonadotrofos ao GnRH, diminuindo a secreção de LH). Altas doses de testosterona suprimem LH e, consequentemente, a espermatogênese.`},{id:`andro-057`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`StAR protein`,dificuldade:`dificil`,enunciado:`A proteína StAR (Steroidogenic Acute Regulatory protein) é essencial para a esteroidogênese porque:`,alternativas:[`Transporta colesterol da membrana mitocondrial externa para a interna, sendo o passo limitante da esteroidogênese.`,`Catalisa a conversão de testosterona em DHT.`,`Liga-se ao LH nas células de Leydig.`,`Produz inibina nas células de Sertoli.`,`Converte estradiol em testosterona.`],resposta_correta:`A`,explicacao:`A proteína StAR transporta colesterol através do espaço intermembranar mitocondrial (da membrana externa para a interna). Esse é o passo limitante (rate-limiting) da esteroidogênese. É regulada por LH/AMPc/PKA nas células de Leydig.`},{id:`andro-058`,banca:`UFPE`,ano:2023,prova:`UFPE — Concurso Veterinário 2023`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`GnRH análogos`,dificuldade:`medio`,enunciado:`O uso de análogos de GnRH (agonistas como buserelina) em doses farmacológicas contínuas no macho resulta em:`,alternativas:[`Supressão da secreção de LH e testosterona por dessensibilização/downregulation dos receptores de GnRH.`,`Estimulação sustentada da secreção de LH e aumento contínuo de testosterona.`,`Apenas aumento de FSH, sem efeito sobre LH.`,`Nenhum efeito sobre o eixo HPG.`,`Estimulação da espermatogênese.`],resposta_correta:`A`,explicacao:`A administração contínua de agonistas de GnRH (buserelina, deslorelina) causa dessensibilização inicial (flare) seguida de downregulation dos receptores de GnRH nos gonadotrofos, resultando em supressão de LH/FSH e castração química. Usado em criptorquidia e hiperplasia prostática em cães.`},{id:`andro-059`,banca:`UFRGS`,ano:2021,prova:`UFRGS — Professor Assistente 2021`,tipo:`pos`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Inibina vs activina`,dificuldade:`medio`,enunciado:`Sobre inibina e activina no macho, assinale a alternativa correta:`,alternativas:[`Inibina B (produzida por células de Sertoli) inibe a secreção de FSH; activina (produzida por células de Sertoli) estimula a secreção de FSH.`,`Inibina estimula a secreção de LH.`,`Activina inibe a secreção de FSH.`,`Inibina e activina têm a mesma ação sobre a hipófise.`,`Ambas são produzidas pelas células de Leydig.`],resposta_correta:`A`,explicacao:`Inibina B (produzida por células de Sertoli sob estímulo de FSH) exerce feedback negativo seletivo sobre FSH hipofisário. Activina (também de Sertoli) estimula a secreção de FSH. Follistatina (produzida localmente) antagoniza a activina.`},{id:`andro-060`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`endocrinologia_reprodutiva_masculina`,subtopico:`Proteína ligadora de retinol`,dificuldade:`dificil`,enunciado:`A proteína ligadora de retinol (RBP) produzida pelas células de Sertoli é importante para:`,alternativas:[`Transportar retinol (vitamina A) essencial para a diferenciação das células germinativas e espermiogênese.`,`Converter testosterona em estradiol.`,`Inibir a produção de FSH.`,`Estimular a produção de LH.`,`Transportar colesterol para as mitocôndrias das células de Leydig.`],resposta_correta:`A`,explicacao:`A RBP (retinol-binding protein) é produzida pelas células de Sertoli e transporta retinol (vitamina A) para as células germinativas. O retinol (via ácido retinoico) é essencial para a diferenciação das espermatogônias e início da espermiogênese. Deficiência de vitamina A causa infertilidade.`},{id:`andro-061`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`semen`,subtopico:`Composição do sêmen`,dificuldade:`facil`,enunciado:`O sêmen é composto por:`,alternativas:[`Espermatozoides e plasma seminal (contribuições das glândulas acessórias).`,`Apenas espermatozoides e água.`,`Espermatozoides e secreção prostática apenas.`,`Espermatozoides, urina e líquido cefalorraquidiano.`,`Apenas plasma seminal, sem espermatozoides.`],resposta_correta:`A`,explicacao:`O sêmen é composto por espermatozoides (5-15% do volume) e plasma seminal (85-95%), que é a mistura de secreções das glândulas acessórias: epidídimo, ducto deferente, vesículas seminais, próstata e glândulas bulbouretrais.`},{id:`andro-062`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`semen`,subtopico:`Avaliação do sêmen`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre a avaliação seminal.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A avaliação do sêmen inclui: volume, cor, turbidez, pH, motilidade espermática (total e progressiva), concentração, morfologia espermática (anormalidades primárias e secundárias), vitalidade (teste de exclusão com corante) e concentração de espermatozoides por dose inseminante.`,explicacao:`A avaliação seminal abrange parâmetros macroscópicos (volume, cor, pH, turbidez) e microscópicos (motilidade, concentração, morfologia, vitalidade). Os valores variam por espécie. É essencial para andrologia clínica e para controle de qualidade em centrais de inseminação.`},{id:`andro-063`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`semen`,subtopico:`Motilidade espermática`,dificuldade:`medio`,enunciado:`A classificação da motilidade espermática em escore de 0 a 5 é utilizada para:`,alternativas:[`Avaliar a porcentagem e qualidade de espermatozoides com movimento progressivo, sendo 0 = sem movimento e 5 = movimento rápido progressivo.`,`Classificar a morfologia dos espermatozoides.`,`Determinar a concentração espermática.`,`Avaliar o volume do ejaculado.`,`Medir o pH do sêmen.`],resposta_correta:`A`,explicacao:`A escala de 0-5 avalia motilidade progressiva: 0 = sem movimento, 1 = movimento não progressivo, 2 = movimento lento progressivo, 3 = movimento moderado progressivo, 4 = movimento rápido progressivo, 5 = movimento muito rápido progressivo. Usada em andrologia clínica.`},{id:`andro-064`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`semen`,subtopico:`Concentração espermática`,dificuldade:`medio`,enunciado:`Para determinar a concentração espermática, pode-se utilizar:`,alternativas:[`Câmara de Neubauer (hemocitômetro), fotocolorímetro (espectrofotômetro) ou contagem automatizada (CASA).`,`Apenas exame macroscópico do sêmen.`,`pHmetro e termômetro.`,`Ultrassonografia escrotal.`,`Dosagem hormonal no sangue.`],resposta_correta:`A`,explicacao:`A concentração espermática pode ser determinada por: câmara de Neubauer (contagem manual em diluição conhecida), fotocolorímetro/espectrofotômetro (turbidez correlacionada com concentração) e sistemas CASA (Computer-Assisted Sperm Analysis) que contam automaticamente.`},{id:`andro-065`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`semen`,subtopico:`Morfologia espermática`,dificuldade:`dificil`,enunciado:`As anormalidades espermáticas primárias são aquelas:`,alternativas:[`Originadas durante a espermatogênese (defeitos de cabeça, acrossomo e peça intermediária de origem testicular).`,`Originadas durante o trânsito pelo epidídimo.`,`Originadas durante a ejaculação.`,`Originadas durante o armazenamento in vitro.`,`Originadas pela contaminação bacteriana do sêmen.`],resposta_correta:`A`,explicacao:`Anormalidades primárias ocorrem durante a espermatogênese e incluem defeitos de cabeça (macro/microcefalia, cabeça em tesoura, dupla cabeça), acrossomo (acrossomo ausente, defeituoso) e peça intermediária (dobrada, enrolada). Anormalidades secundárias ocorrem após a formação (epidídimo, ejaculação, in vitro).`},{id:`andro-066`,banca:`CRMV`,ano:2021,prova:`CRMV-RS — Prova de Suficiência 2021`,tipo:`crmv`,topico:`semen`,subtopico:`Vitalidade espermática`,dificuldade:`facil`,enunciado:`O teste de vitalidade espermática com eosina-nigrosina baseia-se no princípio de que:`,alternativas:[`Espermatozoides vivos (membrana íntegra) excluem o corante e aparecem brancos, enquanto mortos (membrana lesada) absorvem o corante e aparecem rosados/vermelhos.`,`Espermatozoides vivos absorvem a nigrosina e aparecem pretos.`,`Espermatozoides mortos excluem ambos os corantes.`,`A eosina cora apenas anormalidades morfológicas.`,`A nigrosina cora o acrossomo dos espermatozoides.`],resposta_correta:`A`,explicacao:`O teste de eosina-nigrosina avalia a integridade da membrana plasmática. Espermatozoides vivos (membrana íntegra) excluem a eosina → cabeça branca. Mortos (membrana lesada) absorvem eosina → cabeça rosada/vermelha. A nigrosina é o fundo contraste.`},{id:`andro-067`,banca:`UFMG`,ano:2022,prova:`UFMG — Professor Assistente 2022`,tipo:`pos`,topico:`semen`,subtopico:`Plasma seminal`,dificuldade:`medio`,enunciado:`O plasma seminal bovino contém alta concentração de:`,alternativas:[`Frutose (principal substrato energético dos espermatozoides), produzida pelas vesículas seminais.`,`Glucose, produzida pela próstata.`,`Lactose, produzida pelas glândulas bulbouretrais.`,`Sacarose, produzida pelo epidídimo.`,`Galactose, produzida pelo ducto deferente.`],resposta_correta:`A`,explicacao:`O plasma seminal contém frutose como principal substrato energético para os espermatozoides. A frutose é produzida pelas vesículas seminais sob estímulo androgênico. Outros componentes: citrato (próstata), ergotioneina (próstata), proteínas coagulantes e enzimas.`},{id:`andro-068`,banca:`UNESP`,ano:2023,prova:`UNESP — Concurso Veterinário GESP 2023`,tipo:`concurso`,topico:`semen`,subtopico:`Volume seminal`,dificuldade:`facil`,enunciado:`O volume médio do ejaculado em diferentes espécies varia. Assinale a alternativa correta:`,alternativas:[`Equinos produzem os maiores volumes de ejaculado (50-150 mL), enquanto cães produzem volumes menores (2-30 mL).`,`Bovinos produzem volumes maiores que equinos.`,`Suínos produzem volumes menores que cães.`,`Ovinos produzem volumes maiores que bovinos.`,`O volume é idêntico em todas as espécies.`],resposta_correta:`A`,explicacao:`Volumes ejaculados médios: equinos 50-150 mL, suínos 150-300 mL, bovinos 4-8 mL, ovinos 0,8-2 mL, cães 2-30 mL, gatos 0,01-0,15 mL. Os volumes dependem das glândulas acessórias e da técnica de coleta.`},{id:`andro-069`,banca:`USP`,ano:2020,prova:`USP — Doutorado em Reprodução 2020`,tipo:`pos`,topico:`semen`,subtopico:`CASA`,dificuldade:`dificil`,enunciado:`O sistema CASA (Computer-Assisted Sperm Analysis) permite avaliar:`,alternativas:[`Motilidade total e progressiva, velocidade (VCL, VSL, VAP), amplitude lateral da cabeça (ALH), frequência de batimento da cauda (BCF) e morfologia espermática.`,`Apenas a concentração espermática.`,`O volume e a cor do sêmen.`,`Apenas a vitalidade espermática.`,`O pH do plasma seminal.`],resposta_correta:`A`,explicacao:`O CASA analisa por vídeo-computador: VCL (velocidade curvilinear), VSL (velocidade retilínea), VAP (velocidade média da trajetória), ALH (amplitude lateral da cabeça), BCF (frequência de batimento da cauda), motilidade total/progressiva e morfologia (com módulo específico).`},{id:`andro-070`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Médico Veterinário 2021`,tipo:`concurso`,topico:`semen`,subtopico:`pH seminal`,dificuldade:`medio`,enunciado:`O pH do sêmen bovino normal é:`,alternativas:[`Levemente alcalino, em torno de 6,4 a 6,8.`,`Fortemente ácido, em torno de 3,0 a 4,0.`,`Neutro, em torno de 7,0 a 7,4.`,`Fortemente alcalino, em torno de 8,5 a 9,0.`,`Variável, sem faixa de referência.`],resposta_correta:`A`,explicacao:`O pH do sêmen bovino é levemente alcalino (6,4-6,8). Em equinos é ~7,2-7,5; em cães ~6,2-6,8; em suínos ~7,0-7,8. O pH é determinado pela contribuição relativa das glândulas acessórias (vesículas seminais elevam o pH, próstata reduz).`},{id:`andro-071`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Federal Agropecuário 2022`,tipo:`concurso`,topico:`semen`,subtopico:`Liquefação seminal`,dificuldade:`medio`,enunciado:`A liquefação do sêmen após a ejaculação é um processo que:`,alternativas:[`Ocorre naturalmente em suínos e equinos, nos quais o sêmen coagula e depois liquefaz por ação enzimática.`,`É exclusivo de cães e gatos.`,`Não ocorre em nenhuma espécie doméstica.`,`Ocorre apenas em bovinos.`,`É causada pela adição de diluente ao sêmen.`],resposta_correta:`A`,explicacao:`Em suínos e equinos, o sêmen forma um coágulo após a ejaculação (contribuição das vesículas seminais/bulbouretrais), que liquefaz em minutos a horas por ação de enzimas proteolíticas. O coágulo seminal canino também liquefaz. Em bovinos, o sêmen é líquido desde a ejaculação.`},{id:`andro-072`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso Veterinário 2023`,tipo:`concurso`,topico:`semen`,subtopico:`Hipoosmolaridade`,dificuldade:`dificil`,enunciado:`O teste de hipoosmolaridade (HOST) avalia:`,alternativas:[`A integridade funcional da membrana plasmática do espermatozoide, pela capacidade de swelling (inchaço) da cauda em solução hipotônica.`,`A vitalidade espermática por exclusão de corante.`,`A motilidade progressiva dos espermatozoides.`,`A morfologia acrossômica.`,`A concentração espermática.`],resposta_correta:`A`,explicacao:`O HOST (Hypo-Osmotic Swelling Test) avalia a integridade funcional da membrana plasmática. Em solução hipotônica (50-150 mOsm/L), espermatozoides com membrana funcional absorvem água → cauda se curva/swelling. Caudas curvadas = membrana funcional.`},{id:`andro-073`,banca:`UFBA`,ano:2021,prova:`UFBA — Médico Veterinário 2021`,tipo:`concurso`,topico:`semen`,subtopico:`Citologia seminal`,dificuldade:`medio`,enunciado:`Na citologia seminal, a presença excessiva de células redondas (>1.000/µL) pode indicar:`,alternativas:[`Inflamação do trato reprodutivo (orquite, epididimite, prostatite) com infiltrado de leucócitos.`,`Concentração muito alta de espermatozoides.`,`Excesso de frutose no plasma seminal.`,`Contaminação urinária.`,`Efeito normal da ejaculação.`],resposta_correta:`A`,explicacao:`Células redondas no sêmen incluem leucócitos (indicam inflamação/infecção), células epiteliais e espermátides imaturas. >1.000 leucócitos/µL (leucocitospermia) sugere infecção/inflamação do trato reprodutivo (orquite, epididimite, prostatite, vesiculite).`},{id:`andro-074`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`semen`,subtopico:`Frutose seminal`,dificuldade:`facil`,enunciado:`A frutose no plasma seminal é produzida principalmente por:`,alternativas:[`Vesículas seminais, sob estímulo da testosterona.`,`Próstata.`,`Glândulas bulbouretrais.`,`Epidídimo.`,`Testículo.`],resposta_correta:`A`,explicacao:`A frutose é produzida pelas vesículas seminais sob estímulo androgênico (testosterona). É o principal substrato energético dos espermatozoides no sêmen. Sua ausência pode indicar deficiência androgênica ou obstrução dos ductos ejaculatórios.`},{id:`andro-075`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`semen`,subtopico:`Reação acrossômica`,dificuldade:`dificil`,enunciado:`Julgue o item sobre a reação acrossômica.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A reação acrossômica é a fusão da membrana acrossomal externa com a membrana plasmática do espermatozoide, liberando enzimas acrossomais (hialuronidase, acrosina). É indispensável para a penetração da zona pelúcida e ocorre normalmente no trato reprodutivo feminino durante a capacitação.`,explicacao:`A reação acrossômica é exocitose regulada: membrana acrossomal externa funde com membrana plasmática → liberação de enzimas (acrosina, hialuronidase) → exposição de conteúdo acrossomal. Ocorre após a capacitação e contato com a zona pelúcida. Prematura = perda de fertilidade.`},{id:`andro-076`,banca:`UFRPE`,ano:2022,prova:`UFRPE — Concurso Veterinário 2022`,tipo:`concurso`,topico:`semen`,subtopico:`Capacitação espermática`,dificuldade:`medio`,enunciado:`A capacitação espermática é um processo que ocorre:`,alternativas:[`No trato reprodutivo feminino, removendo colesterol e glicoproteínas da membrana plasmática, tornando o espermatozoide competente para a reação acrossômica.`,`No epidídimo, durante a maturação dos espermatozoides.`,`Durante a ejaculação.`,`Nos túbulos seminíferos durante a espermiogênese.`,`In vitro, durante o congelamento do sêmen.`],resposta_correta:`A`,explicacao:`A capacitação ocorre no trato reprodutivo feminino (útero/tuba) e envolve: remoção de colesterol (albumina, HDL), alterações na membrana plasmática, hiperpolarização, aumento de cálcio intracelular e ativação de PKA → hiperativação motilidade → competência para reação acrossômica.`},{id:`andro-077`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`semen`,subtopico:`Citrato seminal`,dificuldade:`facil`,enunciado:`O citrato no plasma seminal é produzido principalmente pela:`,alternativas:[`Próstata.`,`Vesículas seminais.`,`Glândulas bulbouretrais.`,`Epidídimo.`,`Testículo.`],resposta_correta:`A`,explicacao:`O citrato (ácido cítrico) é produzido pela próstata sob estímulo androgênico. É um componente importante do plasma seminal, atuando como tampão e quelante de cálcio. A frutose é produzida pelas vesículas seminais.`},{id:`andro-078`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`semen`,subtopico:`Hiperativação espermática`,dificuldade:`medio`,enunciado:`A hiperativação espermática (hyperactivation) é caracterizada por:`,alternativas:[`Movimento assimétrico vigoroso, com amplitude aumentada e trajetória em forma de oito (hiperprogressivo), mediado por influxo de cálcio.`,`Movimento retilíneo lento e progressivo.`,`Ausência total de movimento flagelar.`,`Movimento circular sem progressão.`,`Movimento progressivo rápido em linha reta.`],resposta_correta:`A`,explicacao:`A hiperativação é um padrão de motilidade vigoroso, assimétrico, com batimentos amplos e trajetória em oito. É mediada por influxo de Ca²⁺ e ativação de canais CatSper. É necessária para penetração da zona pelúcida e ocorre após a capacitação.`},{id:`andro-079`,banca:`UFPR`,ano:2023,prova:`UFPR — Médico Veterinário 2023`,tipo:`concurso`,topico:`semen`,subtopico:`Cor do sêmen`,dificuldade:`facil`,enunciado:`A cor esverdeada do sêmen em bovinos pode indicar:`,alternativas:[`Contaminação com urina ou infecção do trato reprodutivo (piospermia).`,`Concentração muito alta de espermatozoides.`,`Excesso de frutose.`,`Normalidade em bovinos adultos.`,`Contaminação com fezes.`],resposta_correta:`A`,explicacao:`Sêmen normal bovino é branco leitoso a cremoso. Cor esverdeada sugere piospermia (presença de pus/piócitos) ou contaminação urinária (urina). Cor amarelada pode indicar hemosspermia (sangue) ou urina. Cor marrom indica sangue antigo.`},{id:`andro-080`,banca:`UFRGS`,ano:2020,prova:`UFRGS — Doutorado em Reprodução 2020`,tipo:`pos`,topico:`semen`,subtopico:`Ergotioneina seminal`,dificuldade:`dificil`,enunciado:`A ergotioneina é um componente do plasma seminal bovino produzido pela:`,alternativas:[`Próstata, atuando como antioxidante que protege os espermatozoides do estresse oxidativo.`,`Vesículas seminais, como substrato energético.`,`Epidídimo, como fator de maturação.`,`Glândulas bulbouretrais, como lubrificante.`,`Testículo, como hormônio.`],resposta_correta:`A`,explicacao:`A ergotioneina (tiohistidina) é produzida pela próstata e confere ao plasma seminal bovino a cor característica (leitosa). É um potente antioxidante que protege os espermatozoides contra danos oxidativos do peróxido de hidrogênio e radicais livres.`},{id:`andro-081`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso Médico Veterinário 2022`,tipo:`concurso`,topico:`semen`,subtopico:`Dose inseminante`,dificuldade:`medio`,enunciado:`A dose inseminante para inseminação artificial em bovinos com sêmen convencional contém, em média:`,alternativas:[`10-20 milhões de espermatozoides por dose.`,`500 milhões a 1 bilhão de espermatozoides por dose.`,`100.000 espermatozoides por dose.`,`10 bilhões de espermatozoides por dose.`,`Apenas 1.000 espermatozoides por dose.`],resposta_correta:`A`,explicacao:`A dose inseminante convencional para bovinos contém 10-20 milhões de espermatozoides em 0,25-0,5 mL de diluente. Para sêmen sexado, a dose é menor (2-4 milhões). A tecnologia de sexagem e doses reduzidas é viável por depósito uterino profundo.`},{id:`andro-082`,banca:`CESPE`,ano:2021,prova:`CESPE — Professor Universitário 2021`,tipo:`pos`,topico:`semen`,subtopico:`Efeito de diluição`,dificuldade:`medio`,enunciado:`O efeito de diluição (dilution effect) sobre o sêmen refere-se a:`,alternativas:[`Redução da concentração de fatores do plasma seminal e espermatozoides, podendo causar danos à membrana plasmática quando a diluição é excessiva.`,`Melhora progressiva da motilidade com o aumento da diluição.`,`Aumento da fertilidade com diluições elevadas.`,`Nenhum efeito sobre a viabilidade espermática.`,`Apenas mudança de cor do sêmen.`],resposta_correta:`A`,explicacao:`O efeito de diluição causa: redução de fatores protetores do plasma seminal (colesterol, antioxidantes), aumento da susceptibilidade ao choque térmico, dano osmótico e estresse oxidativo. Diluições muito altas reduzem a fertilidade e a longevidade espermática in vitro.`},{id:`andro-083`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Coleta de sêmen — vagina artificial`,dificuldade:`medio`,enunciado:`A vagina artificial para coleta de sêmen em bovinos é composta basicamente por:`,alternativas:[`Um tubo externo rígido, um revestimento interno de silicone ou látex, e água morna no espaço intermédio para simular a temperatura e pressão vaginais.`,`Um tubo de vidro conectado a uma bomba de vácuo.`,`Um cateter uretral descartável.`,`Uma sonda de ultrassom com coletor acoplado.`,`Uma cuba de Petri estéril.`],resposta_correta:`A`,explicacao:`A vagina artificial bovina consiste em: tubo externo rígido (plástico/metal), revestimento interno (silicone/látex), espaço intermédio com água morna (38-42°C) para simular temperatura vaginal, e pressão adequada (40-50 cmH₂O). A ejaculação ocorre por monta do macho sobre a fêmea ou fantasma.`},{id:`andro-084`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Processamento do sêmen`,dificuldade:`dificil`,enunciado:`Julgue o item sobre o processamento do sêmen para IA.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O processamento do sêmen para inseminação artificial inclui: avaliação da qualidade seminal, diluição em diluente apropriado (à base de leite ou Tris), resfriamento gradual até 5°C ou congelamento em palhetas com vapor de nitrogênio líquido (-196°C).`,explicacao:`O processamento segue etapas: avaliação (motilidade, morfologia, concentração), diluição (diluente à base de leite desnatado ou Tris-gema-ácido cítrico com antibióticos), resfriamento gradual (1°C/min até 5°C) e congelamento em palhetas (0,25 ou 0,5 mL) sobre vapor de N₂ líquido.`},{id:`andro-085`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Diluentes para sêmen`,dificuldade:`medio`,enunciado:`Os diluentes para sêmen bovino têm como função:`,alternativas:[`Proteger os espermatozoides contra choque térmico, fornecer substrato energético, manter pH e osmolaridade adequados e conter antibióticos.`,`Apenas aumentar o volume do ejaculado.`,`Destruir bactérias sem proteger os espermatozoides.`,`Acelerar a reação acrossômica.`,`Fixar os espermatozoides para análise microscópica.`],resposta_correta:`A`,explicacao:`Os diluentes contêm: tampão (Tris, citrato) para pH, gema de ovo ou leite (proteção contra choque térmico), glicerol (crioprotetor para congelamento), substrato (glicose/lactose), antibióticos (penicilina, estreptomicina) e água destilada. Osmolaridade ~300-350 mOsm/L.`},{id:`andro-086`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Inseminação em bovinos`,dificuldade:`facil`,enunciado:`A inseminação artificial em bovinos é realizada depositando o sêmen:`,alternativas:[`No corpo do útero (inseminação intrauterina) ou na junção corpo-corno uterino, usando pipeta transcervical.`,`Na vagina.`,`No ovário.`,`Na tuba uterina.`,`No ovário, por via laparoscópica.`],resposta_correta:`A`,explicacao:`Em bovinos, a IA é tipicamente realizada por via transcervical, depositando o sêmen no corpo do útero ou junção corpo-corno. A técnica de depósito uterino profundo (DUI) permite doses menores. A inseminação tubária é usada em programas de TEPE.`},{id:`andro-087`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Prova de Título em Reprodução Animal 2020`,tipo:`pos`,topico:`inseminacao_artificial`,subtopico:`Congelamento de sêmen`,dificuldade:`dificil`,enunciado:`O processo de congelamento de sêmen bovino envolve:`,alternativas:[`Resfriamento gradual até 5°C, equilíbrio com glicerol, envasamento em palhetas e congelamento em vapor de nitrogênio líquido (-100 a -120°C) antes do armazenamento em N₂ líquido (-196°C).`,`Congelamento direto do sêmen fresco a -196°C.`,`Apenas resfriamento até 5°C sem glicerol.`,`Liofilização do sêmen.`,`Preservação em temperatura ambiente.`],resposta_correta:`A`,explicacao:`O protocolo padrão: resfriamento gradual (0,5-1°C/min) até 5°C → equilíbrio com glicerol (4-7%) por 4h → envasamento em palhetas 0,25/0,5 mL → congelamento em vapor de N₂ (-100 a -120°C, -15 a -25°C/min) → transferência para N₂ líquido (-196°C).`},{id:`andro-088`,banca:`CRMV`,ano:2023,prova:`CRMV-SP — Prova de Suficiência 2023`,tipo:`crmv`,topico:`inseminacao_artificial`,subtopico:`Palhetas de sêmen`,dificuldade:`facil`,enunciado:`As palhetas (French straws) para armazenamento de sêmen congelado são feitas de:`,alternativas:[`Policloreto de vinila (PVC) ou polipropileno, com capacidade de 0,25 mL (mini palheta) ou 0,5 mL (palheta convencional).`,`Vidro borossilicato, com capacidade de 10 mL.`,`Aço inoxidável, com capacidade de 5 mL.`,`Borracha de látex, com capacidade de 1 mL.`,`Polietileno, com capacidade de 20 mL.`],resposta_correta:`A`,explicacao:`As palhetas francesas são de PVC ou polipropileno, com volumes de 0,25 mL (mini) e 0,5 mL (convencional). Possuem um plug de algodão/PVA em uma extremidade e são seladas por ultrassom ou pó de PVA. Permitem congelamento e descongelamento rápidos.`},{id:`andro-089`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso Professor 2021`,tipo:`pos`,topico:`inseminacao_artificial`,subtopico:`Descongelamento de sêmen`,dificuldade:`medio`,enunciado:`O descongelamento de palhetas de sêmen bovino congelado é recomendado:`,alternativas:[`Em banho-maria a 35-37°C por 30 segundos (palheta 0,5 mL) ou 20 segundos (palheta 0,25 mL).`,`Em água fervente a 100°C por 10 segundos.`,`Em temperatura ambiente por 30 minutos.`,`Em banho-maria a 70°C por 5 segundos.`,`A temperaturas abaixo de 0°C.`],resposta_correta:`A`,explicacao:`O descongelamento deve ser rápido para evitar recristalização: 35-37°C por 30s (0,5 mL) ou 20s (0,25 mL). Temperaturas muito altas ou tempos longos causam dano espermático. O descongelamento lento é prejudicial por permitir recristalização do gelo intracelular.`},{id:`andro-090`,banca:`UNESP`,ano:2022,prova:`UNESP — Concurso Veterinário GESP 2022`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Timing da inseminação`,dificuldade:`medio`,enunciado:`O melhor momento para inseminar vacas em relação ao cio é:`,alternativas:[`No final do estro (12 horas após o início do cio), próximo à ovulação, para que os espermatozoides estejam capacitados no local da fertilização.`,`No início do estro (primeiras 2 horas).`,`24 horas após o fim do estro.`,`No diestro, quando o corpo lúteo está formado.`,`Não há relação entre o timing e a fertilidade.`],resposta_correta:`A`,explicacao:`A inseminação no final do estro (fim do cio, ~12h após detecção) maximiza a fertilidade: espermatozoides têm tempo para capacitação (6-8h) e chegam à ampola tubária antes da ovulação (~12-18h após o fim do estro). Regra AM/PM: vacas detectadas AM → inseminar PM; PM → inseminar AM.`},{id:`andro-091`,banca:`USP`,ano:2023,prova:`USP — Mestrado em Reprodução 2023`,tipo:`pos`,topico:`inseminacao_artificial`,subtopico:`Inseminação em equinos`,dificuldade:`dificil`,enunciado:`A inseminação artificial em éguas com sêmen refrigerado transportado tem como principal desafio:`,alternativas:[`Manter a viabilidade espermática durante o transporte (24-48h a 5°C), pois o sêmen equino é mais sensível ao resfriamento que o bovino.`,`A impossibilidade de coletar sêmen de garanhões.`,`A ausência de diluentes adequados para sêmen equino.`,`A impossibilidade de realizar IA em éguas.`,`A necessidade de anestesia geral para inseminar.`],resposta_correta:`A`,explicacao:`O sêmen equino é mais sensível ao resfriamento que o bovino, perdendo viabilidade mais rapidamente a 5°C. Diluentes com leite desnatado ou INRA 96 são usados. O transporte deve ser rápido (24-48h) e a inseminação imediata após chegada.`},{id:`andro-092`,banca:`UFRRJ`,ano:2020,prova:`UFRRJ — Médico Veterinário 2020`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Inseminação em suínos`,dificuldade:`medio`,enunciado:`A inseminação artificial em suínos é realizada:`,alternativas:[`Com cateter intracervical, depositando o sêmen no cérvix, com doses de 2-3 bilhões de espermatozoides em 80-100 mL.`,`Por via laparoscópica, depositando o sêmen na tuba.`,`Com cateter intrauterino, depositando 1 milhão de espermatozoides.`,`Por deposição vaginal apenas.`,`Apenas com sêmen congelado.`],resposta_correta:`A`,explicacao:`A IA em suínos usa cateter intracervical (a cérvix suína é espiralada). Dose: 2-3 bilhões de espermatozoides em 80-100 mL de diluente. Sêmen suíno é mais sensível ao congelamento; IA é feita predominantemente com sêmen líquido refrigerado (3-5 dias a 15-20°C).`},{id:`andro-093`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Federal Agropecuário 2023`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Inseminação em cães`,dificuldade:`medio`,enunciado:`A inseminação artificial em cadelas pode ser realizada por:`,alternativas:[`Via intravaginal (com sêmen fresco) ou transcervical (endoscopia/rêde), sendo o sêmen fresco o de melhor resultado em cadelas.`,`Apenas por via intrauterina cirúrgica.`,`Apenas com sêmen congelado, por via intravaginal.`,`Por deposição retal.`,`Não é possível realizar IA em cadelas.`],resposta_correta:`A`,explicacao:`IA em cadelas: intravaginal (sêmen fresco ou refrigerado, taxa de prenhez ~75-85%), transcervical por endoscopia/rêde (sêmen congelado, ~50-70%) ou cirúrgica intrauterina (sêmen congelado, ~70-80%). Sêmen fresco tem melhor resultado que congelado em cães.`},{id:`andro-094`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso Veterinário 2022`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Glicerol como crioprotetor`,dificuldade:`medio`,enunciado:`O glicerol é utilizado como crioprotetor no diluente de congelamento de sêmen bovino. Sua concentração recomendada é:`,alternativas:[`4-7% (v/v).`,`20-30% (v/v).`,`0,1-0,5% (v/v).`,`15-20% (v/v).`,`50% (v/v).`],resposta_correta:`A`,explicacao:`O glicerol é o crioprotetor permeável mais usado para sêmen bovino, na concentração de 4-7% (v/v). Penetra na célula, substitui água intracelular e previne formação de cristos de gelo intracelulares. Em altas concentrações é tóxico (tempo de exposição é importante).`},{id:`andro-095`,banca:`UFBA`,ano:2023,prova:`UFBA — Concurso Veterinário 2023`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Detecção de cio`,dificuldade:`facil`,enunciado:`A detecção de cio (estro) em bovinos é fundamental para o sucesso da IA. Os sinais de cio incluem:`,alternativas:[`Monta, imobilidade quando montada, muco translúcido, inquietação, vulva edemaciada, redução de apetite.`,`Apenas inquietação e redução de apetite.`,`Apenas muco espesso e amarelado.`,`Apenas aumento de produção de leite.`,`Apenas perda de peso.`],resposta_correta:`A`,explicacao:`Sinais de cio: imobilidade quando montada (sinal mais confiável), monta sobre outras vacas, muco cervical translúcido (fio de cristal), inquietação, redução de apetite, queda de produção de leite, vulva edemaciada, ruborização da mucosa vulvar. Duração média: 12-18h.`},{id:`andro-096`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Depósito uterino profundo`,dificuldade:`medio`,enunciado:`O depósito uterino profundo (DUI) em bovinos permite:`,alternativas:[`Reduzir a dose inseminante para 2-4 milhões de espermatozoides, depositando o sêmen no terço distal do corpo do útero.`,`Aumentar a dose inseminante para 100 milhões.`,`Inseminar pela via vaginal sem instrumentos.`,`Realizar IA em vacas prenhas.`,`Substituir completamente a IA convencional.`],resposta_correta:`A`,explicacao:`O DUI (Deep Uterine Insemination) deposita o sêmen na junção corpo-corno uterino, reduzindo a distância que os espermatozoides percorrem. Permite doses reduzidas (2-4 milhões), especialmente útil com sêmen sexado, que tem menor número de espermatozoides por dose.`},{id:`andro-097`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Sexagem seminal`,dificuldade:`dificil`,enunciado:`A sexagem de sêmen bovino por citometria de fluxo baseia-se na diferença de conteúdo de DNA entre espermatozoides X e Y:`,alternativas:[`Espermatozoides X contêm ~3,8% mais DNA que Y (maior conteúdo de DNA do cromossomo X), permitindo separação por citometria de fluxo após coloração com Hoechst 33342.`,`Espermatozoides Y são maiores que os X.`,`Espermatozoides X flutuam em solução salina, enquanto Y afundam.`,`Espermatozoides Y são mais rápidos que X.`,`Não existe método para separar espermatozoides X e Y.`],resposta_correta:`A`,explicacao:`A sexagem por citometria de fluxo (Hoechst 33342 + laser UV): o cromossomo X contém ~3,8% mais DNA que o Y → espermatozoides X emitem mais fluorescência → separados eletronicamente. Precisão ~90%. Limitação: menor número de espermatozoides por dose (2-4 milhões).`},{id:`andro-098`,banca:`UFPR`,ano:2021,prova:`UFPR — Médico Veterinário 2021`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Inseminação em ovinos`,dificuldade:`medio`,enunciado:`A inseminação artificial em ovinos é mais frequentemente realizada:`,alternativas:[`Por via cervical com sêmen refrigerado ou por via laparoscópica intrauterina com sêmen congelado.`,`Apenas por via vaginal.`,`Apenas por via cirúrgica ovariana.`,`Não é possível realizar IA em ovinos.`,`Apenas com sêmen fresco.`],resposta_correta:`A`,explicacao:`IA em ovinos: cervical (sêmen refrigerado, taxa de prenhez ~30-50%) ou laparoscópica intrauterina (sêmen congelado, ~50-70%). A cérvix ovina é tortuosa, dificultando o passagem do cateter cervical. A laparoscopia permite deposição direta no útero.`},{id:`andro-099`,banca:`UFRGS`,ano:2023,prova:`UFRGS — Professor Reprodução 2023`,tipo:`pos`,topico:`inseminacao_artificial`,subtopico:`Resfriamento de sêmen`,dificuldade:`dificil`,enunciado:`A taxa de resfriamento recomendada para sêmen bovino antes do armazenamento a 5°C é:`,alternativas:[`0,5-1°C por minuto, para evitar choque térmico aos espermatozoides.`,`10°C por minuto.`,`Resfriamento instantâneo de 37°C para 5°C.`,`Aquecimento gradual de 5°C para 37°C.`,`Resfriamento apenas após o congelamento.`],resposta_correta:`A`,explicacao:`O resfriamento deve ser gradual (0,5-1°C/min) de 37°C até 5°C para evitar choque térmico. O choque térmico é causado por mudanças bruscas de temperatura que alteram a fluidez da membrana lipídica, causando danos irreversíveis à membrana plasmática espermática.`},{id:`andro-100`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso Veterinário 2021`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Antibióticos no diluente`,dificuldade:`facil`,enunciado:`Os antibióticos adicionados ao diluente de sêmen têm como objetivo:`,alternativas:[`Prevenir a contaminação bacteriana do sêmen durante a coleta, processamento e armazenamento.`,`Melhorar a motilidade dos espermatozoides.`,`Aumentar a concentração espermática.`,`Substituir a gema de ovo no diluente.`,`Acelerar o congelamento do sêmen.`],resposta_correta:`A`,explicacao:`Antibióticos (gentamicina, lincomicina, espectinomicina, penicilina, estreptomicina) são adicionados ao diluente para prevenir contaminação bacteriana que pode reduzir a viabilidade espermática e causar infecções uterinas na fêmea inseminada.`},{id:`andro-101`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário IBAMA 2023`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Maca artificial`,dificuldade:`facil`,enunciado:`A maca artificial (manequim/fantasma) para coleta de sêmen em equinos é utilizada:`,alternativas:[`Como suporte para a égua ou manequim que recebe a monta do garanhão durante a coleta com vagina artificial.`,`Para contenção química do garanhão.`,`Para resfriamento do sêmen após a coleta.`,`Para avaliação da morfologia espermática.`,`Para inseminação da égua.`],resposta_correta:`A`,explicacao:`A maca artificial (manequim) é uma estrutura coberta com lona/manta que simula o dorso de uma égua. O garanhão monta a maca, e a vagina artificial é posicionada para coletar o ejaculado. A égua em cio (ou outro estímulo) é posicionada à frente para incitar a monta.`},{id:`andro-102`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Massagem retal para coleta`,dificuldade:`medio`,enunciado:`A coleta de sêmen por eletroejaculação em pequenos ruminantes e suínos é realizada com:`,alternativas:[`Sonda retal com eletrodos que estimulam os nervos plexo hipogástrico e nervos erigentes, induzindo emissão e ejaculação.`,`Vagina artificial adaptada.`,`Cateter uretral.`,`Massagem manual do epidídimo.`,`Aspiração testicular por agulha.`],resposta_correta:`A`,explicacao:`A eletroejaculação utiliza sonda retal com eletrodos que aplicam estímulos elétricos intermitentes no reto, estimulando os nervos simpáticos (emissão) e parassimpáticos (ereção). Usada em pequenos ruminantes, suínos e animais selvagens quando a monta natural ou vagina artificial não é possível.`},{id:`andro-103`,banca:`UFPE`,ano:2020,prova:`UFPE — Concurso Veterinário 2020`,tipo:`concurso`,topico:`inseminacao_artificial`,subtopico:`Diluente Tris`,dificuldade:`medio`,enunciado:`O diluente à base de Tris (tris-hidroximetil-aminometano) para sêmen bovino contém:`,alternativas:[`Tris (tampão), ácido cítrico, glicose/lactose, gema de ovo (20%) e glicerol (5-7%).`,`Apenas água destilada e sal.`,`Soro fisiológico e antibióticos.`,`Leite integral e formol.`,`Álcool etílico e glicerina.`],resposta_correta:`A`,explicacao:`O diluente Tris contém: Tris (tampão, mantém pH ~6,8-7,0), ácido cítrico (osmorregulador), glicose/lactose (substrato energético), gema de ovo 20% (proteção de membrana pelo colesterol) e glicerol 5-7% (crioprotetor). É o diluente mais usado para congelamento de sêmen bovino.`},{id:`andro-104`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`ICSI`,dificuldade:`dificil`,enunciado:`A injeção intracitoplasmática de espermatozoide (ICSI) consiste em:`,alternativas:[`Injetar um único espermatozoide diretamente no citoplasma do ovócito, contornando a necessidade de penetração da zona pelúcida e reação acrossômica.`,`Injetar múltiplos espermatozoides no útero.`,`Injetar espermatozoides na tuba uterina.`,`Injetar hormônios no ovário para estimular a ovulação.`,`Injetar sêmen diluído no epidídimo.`],resposta_correta:`A`,explicacao:`A ICSI é uma técnica de fertilização in vitro onde um único espermatozoide (imobilizado) é microinjetado diretamente no citoplasma do ovócito maduro (MII). Usada em humanos, equinos e bovinos. Contorna problemas como oligozoospermia grave, astenozoospermia e falha de fecundação.`},{id:`andro-105`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Fertilização in vitro`,dificuldade:`medio`,enunciado:`Julgue o item sobre a fertilização in vitro (FIV) em bovinos.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A FIV em bovinos envolve: aspiração folicular ovum pick-up (OPU) de doadoras, maturação in vitro (MIV) dos ovócitos, fecundação in vitro com sêmen capacitado, cultivo embrionário por 7 dias e transferência de embriões para receptoras.`,explicacao:`A FIV bovina (OPU-FIV): 1) Aspiração folicular guiada por ultrassom (OPU), 2) Maturação in vitro (22-24h em TCM-199 + hormônios), 3) Fecundação com espermatozoides capacitados (heparina + ionóforo de cálcio), 4) Cultivo in vitro (7 dias), 5) Transferência para receptoras.`},{id:`andro-106`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Capacitação in vitro`,dificuldade:`medio`,enunciado:`A capacitação in vitro de espermatozoides bovinos para FIV é realizada utilizando:`,alternativas:[`Heparina (capacitante natural) e ionóforo de cálcio (A23187) para induzir a reação acrossômica.`,`Apenas solução salina.`,`Formol a 10%.`,`Glicerol puro.`,`Antibióticos de amplo espectro.`],resposta_correta:`A`,explicacao:`A capacitação in vitro usa heparina (glicosaminoglicana que se liga a espermatozoides e ativa vias de cálcio/AMPc) como capacitante natural. Ionóforo de cálcio (A23187) ou penicilamina/hipotaurina/epinefrina (PHE) induzem a reação acrossômica para FIV.`},{id:`andro-107`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Microinjeção`,dificuldade:`medio`,enunciado:`A microinjeção de DNA (transgenia) em embriões consiste em:`,alternativas:[`Injetar o transgene no pronúcleo masculino do zigoto, buscando integração no genoma do animal.`,`Injetar DNA em espermatozoides maduros.`,`Injetar hormônios no ovário.`,`Injetar anticorpos no útero.`,`Injetar RNA mensageiro na corrente sanguínea.`],resposta_correta:`A`,explicacao:`A microinjeção pronuclear (em zigotos) ou citoplasmática é usada para produzir animais transgênicos. O DNA exógeno é injetado no pronúcleo masculino do zigoto (maior e mais acessível), buscando integração aleatória no genoma. Taxa de sucesso é baixa (~1-5%).`},{id:`andro-108`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Prova de Título em Reprodução Animal 2023`,tipo:`pos`,topico:`biotecnologias_reprodutivas`,subtopico:`Sexagem embrionária`,dificuldade:`medio`,enunciado:`A sexagem de embriões bovinos pode ser realizada por:`,alternativas:[`PCR do gene SRY, citogenética (cariótipo) ou FISH com sondas para cromossomos X e Y.`,`Apenas por ultrassonografia.`,`Apenas por avaliação macroscópica do embrião.`,`Apenas por dosagem hormonal do soro materno.`,`Não é possível sexar embriões in vitro.`],resposta_correta:`A`,explicacao:`Métodos de sexagem embrionária: PCR do gene SRY (cromossomo Y, mais usado), FISH (hibridização in situ fluorescente com sondas X/Y), citogenética (cariótipo, menos usado por ser demorado). Biópsia de 5-10 células do trofoectoderma permite sexagem com >95% de precisão.`},{id:`andro-109`,banca:`CRMV`,ano:2020,prova:`CRMV-MG — Prova de Suficiência 2020`,tipo:`crmv`,topico:`biotecnologias_reprodutivas`,subtopico:`Interação espermatozoide-ovócito`,dificuldade:`dificil`,enunciado:`A proteína ZP3 da zona pelúcida é:`,alternativas:[`O principal receptor para espermatozoides na zona pelúcida, mediando a reação acrossômica ao se ligar a receptores da membrana espermática.`,`Uma enzima do acrossomo que degrada a zona pelúcida.`,`Um hormônio produzido pelo corpo lúteo.`,`Uma proteína do plasma seminal.`,`Uma enzima produzida pela próstata.`],resposta_correta:`A`,explicacao:`A ZP3 é uma glicoproteína da zona pelúcida que atua como receptor primário para espermatozoides (espécie-específica). A ligação ZP3-receptor espermático induz a reação acrossômica. Em bovinos, ZP4 também participa do reconhecimento. A ZP2 é receptor secundário pós-acrossômico.`},{id:`andro-110`,banca:`UFMG`,ano:2023,prova:`UFMG — Doutorado Reprodução 2023`,tipo:`pos`,topico:`biotecnologias_reprodutivas`,subtopico:`Produção in vitro de embriões`,dificuldade:`dificil`,enunciado:`Na produção in vitro de embriões (PIV) bovinos, o sistema de cultivo com células cumulus ou camadas de granulosa tem como objetivo:`,alternativas:[`Fornecer suporte metabólico (coco-cultivo) e fatores de crescimento que melhoram o desenvolvimento embrionário in vitro.`,`Substituir a necessidade de fecundação.`,`Inibir a maturação dos ovócitos.`,`Remover o acrossomo dos espermatozoides.`,`Acelerar a luteólise.`],resposta_correta:`A`,explicacao:`O coco-cultivo com células de cumulus/granulosa fornece fatores de crescimento, citocinas e suporte metabólico que mimetizam o ambiente tubário, melhorando a taxa de blastocisto e qualidade embrionária. Outros sistemas: SOF (Synthetic Oviductal Fluid), KSOM.`},{id:`andro-111`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Andrologia e biotecnologia`,dificuldade:`facil`,enunciado:`A andrologia veterinária se relaciona com as biotecnologias reprodutivas principalmente na:`,alternativas:[`Avaliação e processamento de sêmen para IA, FIV, ICSI e criopreservação.`,`Apenas na avaliação de fêmeas doadoras.`,`Apenas na produção de hormônios.`,`Apenas na ultrassonografia ovariana.`,`Apenas na coleta de ovócitos.`],resposta_correta:`A`,explicacao:`A andrologia fornece a base para: avaliação seminal (andrologia clínica), processamento de sêmen (diluição, congelamento), inseminação artificial, FIV (capacitação in vitro), ICSI (seleção de espermatozoide único), sexagem seminal e diagnóstico de infertilidade masculina.`},{id:`andro-112`,banca:`USP`,ano:2022,prova:`USP — Mestrado Reprodução 2022`,tipo:`pos`,topico:`biotecnologias_reprodutivas`,subtopico:`Espermatozoide para ICSI`,dificuldade:`dificil`,enunciado:`Para a realização de ICSI em equinos, o espermatozoide selecionado é:`,alternativas:[`Imobilizado por fricção da cauda com a micropipeta antes da injeção, para evitar danos ao ovócito.`,`Selecionado apenas pelo tamanho da cabeça.`,`Submetido à reação acrossômica antes da injeção.`,`Centrifugado a alta velocidade.`,`Submetido à eletroestimulação.`],resposta_correta:`A`,explicacao:`Na ICSI, o espermatozoide é imobilizado por fricção/cauda com a micropipeta de injeção antes de ser aspirado e injetado no ovócito. A imobilização evita movimentos flagelares que poderiam danhar o ovócito. A cauda é frequentemente cortada ou danificada durante a imobilização.`},{id:`andro-113`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso Veterinário 2023`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Preservação de material genético`,dificuldade:`medio`,enunciado:`A conservação de sêmen em nitrogênio líquido (-196°C) permite:`,alternativas:[`Armazenamento indefinido de sêmen, mantendo a viabilidade espermática por décadas, sem deterioração significativa.`,`Armazenamento por no máximo 1 ano.`,`Apenas armazenamento de sêmen fresco.`,`Aumento progressivo da motilidade com o tempo.`,`Destruição imediata dos espermatozoides.`],resposta_correta:`A`,explicacao:`A -196°C, toda atividade metabólica cessa (estado vítreo). Sêmen bovino congelado corretamente mantém fertilidade por décadas (casos documentados >30 anos). A qualidade depende do processamento pré-congelamento, não do tempo de armazenamento.`},{id:`andro-114`,banca:`MAPA`,ano:2020,prova:`MAPA — Fiscal Federal Agropecuário 2020`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Sêmen sexado`,dificuldade:`medio`,enunciado:`O sêmen sexado bovino tem como principal limitação:`,alternativas:[`Menor número de espermatozoides por dose (2-4 milhões) e maior susceptibilidade ao congelamento, resultando em taxas de prenhez ~10-15% menores que sêmen convencional.`,`Maior número de espermatozoides por dose.`,`Maior fertilidade que sêmen convencional.`,`Impossibilidade de ser congelado.`,`Apenas pode ser usado em novilhas.`],resposta_correta:`A`,explicacao:`O sêmen sexado tem limitações: menor concentração por dose (~2-4 milhões vs 10-20 milhões convencional), dano ao DNA pelo corante/laser/citometria, maior susceptibilidade ao congelamento/descongelamento e taxa de prenhez ~10-15% menor que o convencional.`},{id:`andro-115`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso Veterinário 2021`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Estrutura do acrossomo`,dificuldade:`facil`,enunciado:`A reação acrossômica é indispensável para a fertilização porque:`,alternativas:[`Libera enzimas (hialuronidase, acrosina) que permitem a penetração da corona radiata e da zona pelúcida do ovócito.`,`Aumenta a velocidade do espermatozoide.`,`Produz ATP para o flagelo.`,`Condensa o DNA espermático.`,`Remove o citoplasma residual da espermátide.`],resposta_correta:`A`,explicacao:`A reação acrossômica libera enzimas hidrolíticas: hialuronidase (degrada ácido hialurônico da corona radiata) e acrosina (protease que degrada glicoproteínas da zona pelúcida). Sem a reação acrossômica, o espermatozoide não penetra a zona pelúcida e não há fecundação.`},{id:`andro-116`,banca:`UFBA`,ano:2020,prova:`UFBA — Concurso Veterinário 2020`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Co-cultivo embrionário`,dificuldade:`medio`,enunciado:`O co-cultivo de embriões bovinos com células do epitélio tubário (oviduto) tem como vantagem:`,alternativas:[`Produção de fatores tróficos (citocinas, glicoproteínas) que suportam o desenvolvimento embrionário, mimetizando o ambiente in vivo.`,`Substituir completamente a necessidade de receptoras.`,`Acelerar a maturação de ovócitos imaturos.`,`Inibir a fecundação por mais de um espermatozoide.`,`Produzir hormônios para a doadora.`],resposta_correta:`A`,explicacao:`O co-cultivo com células epiteliais tubárias (ou granulosa/cumulus) produz fatores como glicoproteínas, citocinas, fatores de crescimento e antioxidantes que mimetizam o ambiente tubário, melhorando o desenvolvimento embrionário e a taxa de blastocisto in vitro.`},{id:`andro-117`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`FIV bovina`,dificuldade:`medio`,enunciado:`Na fertilização in vitro bovina, a concentração de espermatozoides utilizada é:`,alternativas:[`1-2 milhões/mL de espermatozoides capacitados, muito inferior à concentração do ejaculado natural.`,`100 milhões/mL.`,`10 bilhões/mL.`,`Apenas 1 espermatozoide/mL.`,`500 milhões/mL.`],resposta_correta:`A`,explicacao:`Na FIV bovina, utiliza-se 1-2 milhões de espermatozoides/mL capacitados (com heparina + ionóforo de cálcio ou PHE). A concentração é bem menor que no ejaculado (bilhões/mL) e na IA (10-20 milhões/dose) porque a fecundação ocorre in vitro com acesso direto aos ovócitos.`},{id:`andro-118`,banca:`CESPE`,ano:2021,prova:`CESPE — Professor Universitário 2021`,tipo:`pos`,topico:`biotecnologias_reprodutivas`,subtopico:`Evolução das biotecnologias`,dificuldade:`dificil`,enunciado:`A evolução das biotecnologias reprodutivas em andrologia inclui:`,alternativas:[`IA convencional → IA com sêmen sexado → FIV → ICSI → edição genômica (CRISPR) de embriões.`,`Apenas a IA convencional.`,`FIV antes da IA.`,`ICSI como primeira técnica desenvolvida.`,`Edição genômica antes da IA.`],resposta_correta:`A`,explicacao:`A evolução cronológica: IA (1780s animais, 1950s bovinos) → FIV (1980s) → ICSI (1990s) → sexagem seminal (1990s) → clonagem (1996 Dolly) → marcadores moleculares (SNP chips) → CRISPR/Cas9 (2010s). Cada avanço ampliou as possibilidades de melhoramento genético.`},{id:`andro-119`,banca:`UFRGS`,ano:2020,prova:`UFRGS — Doutorado em Reprodução 2020`,tipo:`pos`,topico:`biotecnologias_reprodutivas`,subtopico:`Reação acrossômica induzida`,dificuldade:`dificil`,enunciado:`A indução da reação acrossômica in vitro para FIV pode ser realizada por:`,alternativas:[`Ionóforo de cálcio (A23187), progesterona ou estradiol, que aumentam a concentração intracelular de Ca²⁺ e ativam a exocitose acrossomal.`,`Apenas por resfriamento do sêmen.`,`Por adição de antibióticos ao meio.`,`Por centrifugação a alta rotação.`,`Por congelamento e descongelamento repetidos.`],resposta_correta:`A`,explicacao:`Agentes que induzem reação acrossômica in vitro: ionóforo de cálcio A23187 (aumenta Ca²⁺ intracelular), progesterona (ativa canais CatSper), estradiol, lisofosfatidilcolina. O aumento de Ca²⁺ intracelular ativa calmodulina/PKA → exocitose acrossomal.`},{id:`andro-120`,banca:`UFRPE`,ano:2023,prova:`UFRPE — Concurso Veterinário 2023`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Biópsia embrionária`,dificuldade:`medio`,enunciado:`A biópsia de embriões bovinos para diagnóstico genético pré-implantacional é realizada:`,alternativas:[`Removendo 5-10 células do trofoectoderma no estágio de blastocisto (D7), sem comprometer o desenvolvimento embrionário.`,`Removendo todas as células do embrião.`,`Apenas em embriões de 2 células.`,`Por aspiração do fluido uterino.`,`Não é possível biopsiar embriões bovinos.`],resposta_correta:`A`,explicacao:`A biópsia trofoblástica é realizada no estágio de blastocisto expandido (D7), removendo 5-10 células do trofoectoderma (futura placenta). O embrião mantém o potencial de desenvolvimento. As células biopsiadas são usadas para sexagem (PCR-SRY), genotipagem (SNP) ou diagnóstico de defeitos genéticos.`},{id:`andro-121`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário IBAMA 2020`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Ovócito MII`,dificuldade:`medio`,enunciado:`O ovócito maduro (MII) utilizado em FIV e ICSI é:`,alternativas:[`Um ovócito em metáfase II, que completou a meiose I e está parado na meiose II até a fecundação.`,`Um ovócito em prófase I.`,`Um ovócito que completou ambas as divisões meióticas.`,`Um ovócito imaturo em diploteno.`,`Um ovócito degenerado.`],resposta_correta:`A`,explicacao:`O ovócito MII (metáfase II) completou a meiose I (expulsou o 1º corpúsculo polar) e está parado na metáfase II. A meiose II é retomada apenas após a fecundação (penetração espermática → aumento de Ca²⁺ → ativação do ovócito → expulsão do 2º corpúsculo polar).`},{id:`andro-122`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Poliespermia`,dificuldade:`medio`,enunciado:`A poliespermia (penetração de mais de um espermatozoide) na fertilização é evitada por:`,alternativas:[`Reação cortical (exocitose de grânulos corticais que alteram a zona pelúcida e a membrana plasmática do ovócito).`,`Aumento da motilidade dos espermatozoides.`,`Redução da concentração espermática.`,`Remoção da zona pelúcida.`,`Ação do acrossomo.`],resposta_correta:`A`,explicacao:`A reação cortical (exocitose dos grânulos corticais do ovócito) provoca: 1) Modificação da zona pelúcida (zona reaction → endurecimento), 2) Modificação da membrana plasmática do ovócito. Esses mecanismos bloqueiam a polisspermia (block to polyspermy).`},{id:`andro-123`,banca:`UFPE`,ano:2022,prova:`UFPE — Concurso Veterinário 2022`,tipo:`concurso`,topico:`biotecnologias_reprodutivas`,subtopico:`Metabolismo espermático`,dificuldade:`dificil`,enunciado:`O metabolismo energético dos espermatozoides de mamíferos ocorre por:`,alternativas:[`Glicólise (no citoplasma) e fosforilação oxidativa (nas mitocôndrias da peça intermediária), sendo a frutose o principal substrato.`,`Apenas glicólise, sem participação mitocondrial.`,`Beta-oxidação de ácidos graxos como via exclusiva.`,`Fotossíntese.`,`Fermentação alcoólica.`],resposta_correta:`A`,explicacao:`Espermatozoides utilizam: glicólise (citoplasma, produz ATP anaerobicamente) e fosforilação oxidativa (mitocôndrias da peça intermediária, via aeróbica mais eficiente). Substratos: frutose (plasma seminal), glicose, lactato. A contribuição relativa varia por espécie.`},{id:`andro-124`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Orquite`,dificuldade:`medio`,enunciado:`A orquite (inflamação do testículo) em bovinos pode ser causada por:`,alternativas:[`Brucella abortus, que causa orquite e epididimite, sendo uma zoonose de notificação obrigatória.`,`Apenas por traumas escrotais.`,`Apenas por defeitos genéticos.`,`Apenas por deficiência nutricional.`,`Não ocorre em bovinos.`],resposta_correta:`A`,explicacao:`Brucella abortus é causa importante de orquite/epididimite em bovinos (e bubalinos). Outras causas: Trueperella pyogenes, Histophilus somni, Leptospira, trauma, torção testicular. A brucelose é zoonose e doença de notificação compulsória.`},{id:`andro-125`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Epididimite`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre epididimite.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A epididimite em ovinos é frequentemente causada por Brucella ovis, resultando em inflamação crônica, obstrução do ducto epididimário, azoospermia obstrutiva e infertilidade. O diagnóstico é confirmado por sorologia (IDEXX), citologia seminal e cultura.`,explicacao:`Brucella ovis é a principal causa de epididimite infecciosa em ovinos. Causa epididimite crônica granulomatosa → obstrução → azoospermia obstrutiva. Diagnóstico: sorologia (fixação de complemento, ELISA), cultura seminal, citologia. Ovelhas são portadoras assintomáticas.`},{id:`andro-126`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Prostatite`,dificuldade:`medio`,enunciado:`A prostatite bacteriana em cães é diagnosticada por:`,alternativas:[`Ultrassonografia prostática (aumento, alteração ecogênica), citologia do líquido prostático (piócitos, bactérias), cultura e antibiograma.`,`Apenas exame de sangue.`,`Apenas radiografia abdominal.`,`Apenas palpação retal.`,`Apenas dosagem hormonal.`],resposta_correta:`A`,explicacao:`Diagnóstico de prostatite canina: ultrassom (aumento prostático, heterogeneidade, abscessos), citologia prostática (piócitos, bactérias), cultura/antibiograma (E. coli, Staphylococcus, Proteus, Pseudomonas), hemograma (leucocitose, neutrofilia), radiografia/TC.`},{id:`andro-127`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Balanopostite`,dificuldade:`facil`,enunciado:`A balanopostite é a inflamação do:`,alternativas:[`Glande do pênis (balanite) e do prepúcio (postite), comum em equinos e bovinos.`,`Testículo e epidídimo.`,`Próstata e vesículas seminais.`,`Escroto e túnica albugínea.`,`Uretra e bexiga.`],resposta_correta:`A`,explicacao:`A balanopostite é a inflamação simultânea da glande (balanite) e do prepúcio (postite). Causas: infecção (bacteriana, fúngica), trauma, corpo estranho, tumor. Em equinos, associada a coito, higiene inadequada. Em bovinos, pode ser causada por Ureaplasma, Mycoplasma.`},{id:`andro-128`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`patologia_reprodutiva_masculina`,subtopico:`Tumor testicular`,dificuldade:`medio`,enunciado:`Os tumores testiculares mais comuns em cães são:`,alternativas:[`Tumor de células de Sertoli, seminoma e tumor de células de Leydig (intersticial), com predominância em cães idosos criptorquidos.`,`Apenas seminomas.`,`Apenas tumores de células de Sertoli.`,`Linfomas testiculares.`,`Carcinoma de células escamosas.`],resposta_correta:`A`,explicacao:`Os três tumores testiculares mais comuns em cães: seminoma, tumor de células de Sertoli e tumor de células de Leydig (intersticial). Cães criptorquidos têm 10-13x mais risco. O tumor de Sertoli pode causar feminilização (síndrome paraneoplásica por produção de estrógeno).`},{id:`andro-129`,banca:`CRMV`,ano:2021,prova:`CRMV-RS — Prova de Suficiência 2021`,tipo:`crmv`,topico:`patologia_reprodutiva_masculina`,subtopico:`Torção testicular`,dificuldade:`medio`,enunciado:`A torção do cordão espermático (torção testicular) é uma emergência andrológica caracterizada por:`,alternativas:[`Rotação do testículo sobre seu eixo, obstruindo vasos sanguíneos, causando isquemia aguda, dor intensa e aumento escrotal unilateral.`,`Infecção crônica do testículo.`,`Acúmulo de líquido na túnica vaginal.`,`Degeneração testicular progressiva.`,`Hérnia inguinal.`],resposta_correta:`A`,explicacao:`A torção testicular causa: rotação do testículo → obstrução venosa (primeiro) → congestão → edema → obstrução arterial → isquemia → necrose. Sinais: dor aguda, aumento escrotal unilateral, endurecimento. É emergência cirúrgica (orquiectomia se viabilidade comprometida).`},{id:`andro-130`,banca:`UFMG`,ano:2022,prova:`UFMG — Professor Assistente 2022`,tipo:`pos`,topico:`patologia_reprodutiva_masculina`,subtopico:`Hidrocele`,dificuldade:`facil`,enunciado:`A hidrocele em animais é definida como:`,alternativas:[`Acúmulo de líquido seroso entre as túnicas visceral e parietal da vaginal testicular.`,`Infecção do testículo.`,`Tumor do epidídimo.`,`Abscesso escrotal.`,`Herniação do intestino para o escroto.`],resposta_correta:`A`,explicacao:`A hidrocele é o acúmulo de líquido seroso no espaço entre as túnicas visceral e parietal da vaginal (peritônio vaginal). Causas: inflamação, trauma, neoplasia, filariose (verminose). Diagnóstico: transiluminação (positiva), ultrassonografia. Tratamento: drenagem ou cirurgia.`},{id:`andro-131`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Funiculite`,dificuldade:`medio`,enunciado:`A funiculite (inflamação do cordão espermático) pode ocorrer como complicação de:`,alternativas:[`Castração cirúrgica contaminada, orquiepididimite ascendente ou herniorrafia inguinal.`,`Apenas por deficiência de vitamina E.`,`Apenas por trauma direto ao pênis.`,`Apenas por alergia alimentar.`,`Não ocorre em animais domésticos.`],resposta_correta:`A`,explicacao:`A funiculite (inflamação do funículo/cordão espermático) ocorre por: infecção pós-castração, orquiepididimite ascendente, herniorrafia complicada, granuloma de sutura. Causa edema, dor e fistulação do coto do cordão. Tratamento: antibióticos, anti-inflamatórios, revisão cirúrgica.`},{id:`andro-132`,banca:`USP`,ano:2021,prova:`USP — Doutorado Reprodução 2021`,tipo:`pos`,topico:`patologia_reprodutiva_masculina`,subtopico:`Espermatocele`,dificuldade:`dificil`,enunciado:`A espermatocele é:`,alternativas:[`Uma cisto contendo espermatozoides, geralmente localizada na cabeça do epidídimo, resultante de obstrução parcial do ducto epididimário.`,`Uma infecção bacteriana do testículo.`,`Um tumor maligno do testículo.`,`Uma hérnia inguinal.`,`Uma coleção de sangue no escroto.`],resposta_correta:`A`,explicacao:`A espermatocele (spermatocele) é um cisto preenchido por fluido seminal contendo espermatozoides, localizado tipicamente na cabeça do epidídimo. Resulta de obstrução parcial dos ductos eferentes. Diagnóstico: ultrassonografia (cisto anecoico com debris). Pode causar infertilidade se bilateral.`},{id:`andro-133`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Concurso Veterinário 2022`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Varicocele`,dificuldade:`medio`,enunciado:`A varicocele (dilatação das veias do plexo pampiniforme) em cavalos:`,alternativas:[`Pode causar aumento da temperatura testicular, estresse térmico e degeneração dos túbulos seminíferos, resultando em infertilidade.`,`Não tem efeito sobre a fertilidade.`,`Apenas causa dor, sem efeito sobre a espermatogênese.`,`É uma condição exclusiva de cães.`,`Causa aumento da produção de testosterona.`],resposta_correta:`A`,explicacao:`A varicocele equina (varizes do plexo pampiniforme) compromete a termorregulação testicular → aumento da temperatura escrotal → estresse térmico → degeneração do epitélio seminífero → redução da espermatogênese. Mais comum em garanhões idosos. Diagnóstico: palpação, ultrassom Doppler.`},{id:`andro-134`,banca:`MAPA`,ano:2021,prova:`MAPA — Fiscal Federal Agropecuário 2021`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Adenoma prostático`,dificuldade:`medio`,enunciado:`A hiperplasia prostática benigna (HPB) em cães:`,alternativas:[`É a condição prostática mais comum em cães inteiros idosos, causada por estímulo androgênico crônico. Tratamento de escolha: castração ou inibidores de 5-alfa-redutase.`,`É mais comum em cães castrados.`,`Ocorre apenas em cães jovens.`,`Não tem tratamento.`,`É causada por infecção bacteriana.`],resposta_correta:`A`,explicacao:`A HPB é a condição prostática mais comum em cães inteiros >5 anos. Causada por conversão de testosterona em DHT (5-alfa-redutase) → hiperplasia glandular. Sinais: tenesmo, hematúria, disúria. Tratamento: castração (efetivo) ou finasterida (inibidor 5-alfa-redutase).`},{id:`andro-135`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso Veterinário 2023`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Coceira prepucial`,dificuldade:`facil`,enunciado:`A presença de secreção purulenta prepucial em equinos pode indicar:`,alternativas:[`Balanopostite, metrite contagiosa equina (Taylorella equigenitalis) ou contaminação por Pseudomonas/Streptococcus.`,`Apenas higiene inadequada.`,`Normalidade em garanhões.`,`Apenas reação alérgica.`,`Excesso de testosterona.`],resposta_correta:`A`,explicacao:`Secreção purulenta prepucial em equinos: balanopostite (infecciosa ou traumática), metrite contagiosa equina (T. equigenitalis), Pseudomonas aeruginosa, Streptococcus equi zooepidemicus, Klebsiella pneumoniae. É obrigatório o exame andrológico e cultura antes da cobertura/IA.`},{id:`andro-136`,banca:`UFBA`,ano:2021,prova:`UFBA — Concurso Veterinário 2021`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Sêmen com sangue (hemosspermia)`,dificuldade:`medio`,enunciado:`A hemosspermia (presença de sangue no ejaculado) em garanhões pode ser causada por:`,alternativas:[`Lesões uretrais, prostatite, tumor de seio paranasal, cistos prostáticos ou fratura do osso peniano.`,`Apenas deficiência de vitamina K.`,`Normalidade durante a época de cobertura.`,`Apenas excesso de exercício.`,`Apenas contaminação urinária.`],resposta_correta:`A`,explicacao:`Causas de hemosspermia em equinos: lesões uretrais (fossa uretral, divertículo), prostatite, cistos prostáticos, tumor prostático, trauma peniano, fratura do pênis, lesão do seio paranasal, contaminação urinária. Diagnóstico: endoscopia, ultrassom, citologia seminal.`},{id:`andro-137`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Orquiepididimite`,dificuldade:`medio`,enunciado:`A orquiepididimite por Brucella canis em cães:`,alternativas:[`Causa inflamação crônica do testículo e epidídimo, infertilidade, e é transmissível a outros cães por via sexual e vertical.`,`Não afeta a fertilidade.`,`É exclusiva de fêmeas.`,`Causa apenas sintomas respiratórios.`,`Não existe em cães.`],resposta_correta:`A`,explicacao:`Brucella canis causa orquiepididimite crônica em cães (e brucelose humana). Sinais: infertilidade, atrofia testicular, epididimite, linfadenopatia. Transmissão: venérea, vertical, contato com secreções. Diagnóstico: sorologia (RSAT, ELISA, IFA). Notificação obrigatória em alguns estados.`},{id:`andro-138`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Abscesso prostático`,dificuldade:`dificil`,enunciado:`O abscesso prostático em cães é:`,alternativas:[`Uma complicação de prostatite bacteriana crônica, diagnosticado por ultrassonografia (área anecoica com debris), tratado por drenagem cirúrgica e antibióticos prolongados.`,`Uma condição benigna que resolve espontaneamente.`,`Uma condição exclusiva de cães castrados.`,`Uma neoplasia maligna.`,`Uma hérnia inguinal.`],resposta_correta:`A`,explicacao:`O abscesso prostático é complicação de prostatite bacteriana crônica. Diagnóstico: ultrassom (massa hipoecoica/fluido com debris), aspirado (pus), cultura. Tratamento: drenagem cirúrgica (marsupialização ou omentalização) + antibióticos por 4-8 semanas. Castração recomendada.`},{id:`andro-139`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Doença de Peyronie`,dificuldade:`dificil`,enunciado:`A fibrose peniana (doença de Peyronie) em equinos é caracterizada por:`,alternativas:[`Formação de placas fibróticas na túnica albugínea do pênis, causando curvatura peniana durante a ereção e dificuldade de monta.`,`Infecção bacteriana do pênis.`,`Fratura do osso peniano.`,`Tumor do pênis.`,`Parasitismo peniano.`],resposta_correta:`A`,explicacao:`A fibrose peniana (induratio penis plastica) em equinos é a formação de placas fibróticas na túnica albugínea → curvatura durante ereção → dificuldade de coito. Causas: trauma, hematomas organizados. Tratamento: excisão cirúrgica da placa fibrótica, anti-inflamatórios.`},{id:`andro-140`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Parafimose`,dificuldade:`facil`,enunciado:`A parafimose é:`,alternativas:[`Incapacidade de retrair o pênis edemaciado para dentro do prepúcio, constituindo uma emergência andrológica.`,`Inflamação da glande do pênis.`,`Tumor do prepúcio.`,`Incapacidade de ereção.`,`Fratura peniana.`],resposta_correta:`A`,explicacao:`A parafimose é a impossibilidade de retração do pênis (geralmente edemaciado) para o interior do prepúcio. Causas: estenose prepucial, edema pós-ereção, trauma, frioblastia. É emergência: o pênis exposto resseca, edematiza e pode necrosar. Tratamento: lubrificação, drenagem do edema, redução manual.`},{id:`andro-141`,banca:`UFPR`,ano:2020,prova:`UFPR — Concurso Veterinário 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Neoplasia peniana`,dificuldade:`medio`,enunciado:`O tumor de células escamosas do pênis é mais comum em:`,alternativas:[`Equinos, especialmente garanhões com prepúcio pigmentado, causando massa ulcerada no pênis ou prepúcio.`,`Bovinos, apenas.`,`Cães castrados.`,`Suínos machos.`,`Não ocorre em animais domésticos.`],resposta_correta:`A`,explicacao:`O carcinoma de células escamosas (SCC) é o tumor peniano mais comum em equinos, especialmente em garanhões com pele não pigmentada (mas ocorre em pigmentados). Causa massa ulcerada no pênis/prepúcio. Metastatiza para linfonodos inguinais. Tratamento: cirurgia, quimioterapia tópica (5-FU, cisplatina).`},{id:`andro-142`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso Veterinário 2022`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Hipospádia`,dificuldade:`medio`,enunciado:`A hipospádia é uma malformação congênita caracterizada por:`,alternativas:[`Abertura anormal da uretra na face ventral do pênis, devido a falha na fusão dos folhetos uretrais durante o desenvolvimento embrionário.`,`Ausência total do pênis.`,`Duplicação do pênis.`,`Fimose congênita.`,`Ausência do prepúcio.`],resposta_correta:`A`,explicacao:`A hipospádia é uma malformação congênita em que a abertura uretral se localiza na face ventral do pênis (em vez da ponta). Resulta de falha na fusão dos folhetos uretrais durante a diferenciação sexual masculina. Pode ser glandular, peniana, escrotal ou perineal.`},{id:`andro-143`,banca:`UFRPE`,ano:2020,prova:`UFRPE — Concurso Veterinário 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Hérnia inguinal`,dificuldade:`medio`,enunciado:`A hérnia inguinal em equinos é:`,alternativas:[`Passagem de alça intestinal ou outro órgão abdominal pelo canal inguinal, comum em garanhões, podendo causar cólica e comprometimento do fluxo sanguíneo testicular.`,`Uma condição que não afeta a reprodução.`,`Exclusiva de éguas.`,`Uma inflamação do cordão espermático.`,`Uma cisto escrotal.`],resposta_correta:`A`,explicacao:`A hérnia inguinal em equinos ocorre quando intestino (ou outro órgão) passa pelo canal inguinal para o escroto. Causa: anel inguinal dilatado, cólica, esforço. Diagnóstico: palpação, ultrassom. Tratamento: cirurgia (herniorrafia). Risco de comprometer vascularização testicular.`},{id:`andro-144`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Vesiculite`,dificuldade:`medio`,enunciado:`A vesiculite (inflamação das vesículas seminais) em bovinos pode ser causada por:`,alternativas:[`Trichomonas fetus, Campylobacter fetus venerealis ou infecção ascendente por bactérias comuns.`,`Apenas por deficiência nutricional.`,`Apenas por traumas.`,`Não ocorre em bovinos.`,`Apenas por vírus.`],resposta_correta:`A`,explicacao:`A vesiculite em bovinos pode ser causada por: Trichomonas fetus, Campylobacter fetus, Histophilus somni, Trueperella pyogenes, Mycoplasma. Infecções ascendentes ou hematogênas. Diagnóstico: palpação retal, ultrassom, citologia do fluido seminal, cultura.`},{id:`andro-145`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Fimose`,dificuldade:`facil`,enunciado:`A fimose é:`,alternativas:[`Incapacidade de expor a glande do pênis por estreitamento do orifício prepucial, podendo ser congênita ou adquirida.`,`Incapacidade de retrair o pênis.`,`Inflamação do prepúcio.`,`Fratura peniana.`,`Tumor do prepúcio.`],resposta_correta:`A`,explicacao:`A fimose é a impossibilidade de exteriorização da glande por estreitamento do anel prepucial. Congênita (rara) ou adquirida (balanopostite crônica, cicatriz, tumor). Pode causar acúmulo de secreção prepucial, infecção e dificuldade de coito. Tratamento: prepucioplastia.`},{id:`andro-146`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso Veterinário 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Granuloma espermático`,dificuldade:`dificil`,enunciado:`O granuloma espermático é:`,alternativas:[`Uma reação inflamatória granulomatosa causada pelo extravasamento de espermatozoides no tecido, geralmente no epidídimo ou coto do cordão espermático pós-castração.`,`Uma neoplasia testicular.`,`Uma infecção viral do testículo.`,`Uma malformação congênita.`,`Uma cisto ovariano no macho.`],resposta_correta:`A`,explicacao:`O granuloma espermático é uma reação granulomatosa a espermatozoides extravasados (antígenos próprios, mas imunogênicos quando fora do sistema de ductos). Localização: epidídimo, coto do cordão pós-castração, próstata. Diagnóstico: citologia (espermatozoides + células inflamatórias), biópsia.`},{id:`andro-147`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso Veterinário 2022`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Neoplasia de células de Sertoli`,dificuldade:`medio`,enunciado:`O tumor de células de Sertoli em cães pode causar síndrome paraneoplásica caracterizada por:`,alternativas:[`Feminilização (ginecomastia, alopecia bilateral simétrica, atratividade para outros machos) por produção de estrógeno pelo tumor.`,`Masculinização excessiva.`,`Apenas dor testicular.`,`Nenhum efeito sistêmico.`,`Apenas infertilidade sem sinais clínicos.`],resposta_correta:`A`,explicacao:`O tumor de Sertoli pode produzir estrógeno → síndrome paraneoplásica: feminilização (ginecomastia, prepúcio penduloso, atratividade para machos, alopecia bilateral simétrica), supressão medular (pancitopenia por estrógeno), dermatose. Mais comum em cães criptorquidos.`},{id:`andro-148`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário Prefeitura 2020`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Tumor de células de Leydig`,dificuldade:`medio`,enunciado:`O tumor de células de Leydig (intersticial) em cães:`,alternativas:[`É geralmente benigno, pequeno, assintomático e frequentemente achado incidental durante orquiectomia ou ultrassonografia escrotal.`,`É sempre maligno e metastatiza precocemente.`,`Causa feminilização.`,`É mais comum em cães castrados.`,`Causa infertilidade severa sempre.`],resposta_correta:`A`,explicacao:`O tumor de Leydig é geralmente benigno (raramente metastatiza), pequeno, firme, achado incidental no testículo. Pode produzir andrógenos. Não costuma causar síndrome paraneoplásica significativa. Diagnóstico: orquiectomia + histopatologia.`},{id:`andro-149`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`patologia_reprodutiva_masculina`,subtopico:`Colite seminal`,dificuldade:`dificil`,enunciado:`A criptorquidia em cães está associada a:`,alternativas:[`Maior risco de neoplasia testicular (10-13x), especialmente seminoma e tumor de Sertoli, e infertilidade do testículo retido.`,`Maior fertilidade.`,`Menor risco de neoplasia.`,`Apenas defeitos cosméticos.`,`Nenhuma consequência clínica.`],resposta_correta:`A`,explicacao:`A criptorquidia (testículo retido no abdômen ou canal inguinal) aumenta o risco de neoplasia em 10-13x (temperatura intra-abdominal). Os tumores mais associados: seminoma e tumor de Sertoli. O testículo retido é infértil (temperatura impede espermatogênese). Recomenda-se orquiectomia bilateral.`},{id:`andro-150`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Causas de infertilidade`,dificuldade:`medio`,enunciado:`As causas de infertilidade masculina em animais domésticos podem ser classificadas em:`,alternativas:[`Pré-testiculares (hormonais), testiculares (intrínsecos ao testículo) e pós-testiculares (obstrutivas/infecciosas do trato genital).`,`Apenas causas genéticas.`,`Apenas causas infecciosas.`,`Apenas causas nutricionais.`,`Apenas causas ambientais.`],resposta_correta:`A`,explicacao:`Causas de infertilidade masculina: 1) Pré-testiculares (hipogonadismo, deficiência de GnRH/LH/FSH, hiperprolactinemia, hipotireoidismo), 2) Testiculares (criptorquidia, degeneração, orquite, genéticos), 3) Pós-testiculares (epididimite, obstrução, prostatite, defeitos de ejaculação).`},{id:`andro-151`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Oligozoospermia`,dificuldade:`medio`,enunciado:`A oligozoospermia é definida como:`,alternativas:[`Concentração espermática abaixo dos valores de referência para a espécie.`,`Ausência total de espermatozoides no ejaculado.`,`Presença de apenas espermatozoides mortos.`,`Motilidade espermática zero.`,`Morfologia 100% anormal.`],resposta_correta:`A`,explicacao:`A oligozoospermia é a concentração espermática abaixo do valor de referência. Azoospermia é a ausência total de espermatozoides. Necrozoospermia é a presença de apenas espermatozoides mortos. Asthenozoospermia é motilidade reduzida. Teratozoospermia é morfologia anormal.`},{id:`andro-152`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Azoospermia`,dificuldade:`dificil`,enunciado:`A azoospermia obstrutiva difere da azoospermia secretória (não obstrutiva) porque:`,alternativas:[`Na obstrutiva, a espermatogênese é normal, mas há obstrução do trato excretor; na secretória, há falha na produção de espermatozoides pelo testículo.`,`Na secretória, há obstrução do epidídimo.`,`Na obstrutiva, o testículo é atrofiado.`,`Ambas têm a mesma causa.`,`A azoospermia secretória é causada por obstrução prostática.`],resposta_correta:`A`,explicacao:`Azoospermia obstrutiva: espermatogênese normal + obstrução (epididimite, funiculite, estenose ductal). Azoospermia secretória (não obstrutiva): falha na produção espermática (criptorquidia, degeneração testicular, hipogonadismo). Diagnóstico diferencial: citologia testicular por aspiração (FNAC).`},{id:`andro-153`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Degeneração testicular`,dificuldade:`medio`,enunciado:`A degeneração testicular (atrofia testicular) em bovinos pode ser causada por:`,alternativas:[`Estresse térmico crônico (febre, criptorquidia), infecções (Brucella, Leptospira), deficiência de vitamina E/selênio ou toxinas.`,`Apenas por excesso de testosterona.`,`Apenas por idade avançada.`,`Apenas por deficiência de vitamina A.`,`Não ocorre em bovinos.`],resposta_correta:`A`,explicacao:`Causas de degeneração testicular: estresse térmico (febre, febre aftosa, varicocele, criptorquidia), infecções (Brucella, Leptospira, BHV-1), deficiência nutricional (vitamina E, selênio, zinco), toxinas (estrogenio, aflatoxinas), genética, radiação.`},{id:`andro-154`,banca:`AVAMEC`,ano:2021,prova:`AVAMEC — Prova de Título em Reprodução Animal 2021`,tipo:`pos`,topico:`infertilidade_masculina`,subtopico:`Diagnóstico de infertilidade`,dificuldade:`medio`,enunciado:`O exame andrológico completo inclui:`,alternativas:[`Anamnese, exame clínico geral, exame genital externo e interno, avaliação do comportamento sexual, coleta e avaliação do sêmen.`,`Apenas avaliação do sêmen.`,`Apenas exame de sangue.`,`Apenas ultrassonografia prostática.`,`Apenas palpação testicular.`],resposta_correta:`A`,explicacao:`O exame andrológico completo: 1) Anamnese (histórico, alimentação, manejo), 2) Exame clínico geral, 3) Exame genital externo (testículos, epidídimo, pênis, prepúcio), 4) Exame genital interno (próstata, vesículas seminais por palpação retal), 5) Comportamento sexual (libido, monta, ejaculação), 6) Avaliação seminal.`},{id:`andro-155`,banca:`CRMV`,ano:2022,prova:`CRMV-SP — Prova de Suficiência 2022`,tipo:`crmv`,topico:`infertilidade_masculina`,subtopico:`Tratamento de infertilidade`,dificuldade:`medio`,enunciado:`O tratamento da infertilidade masculina de origem infecciosa inclui:`,alternativas:[`Antibioticoterapia baseada em cultura e antibiograma, anti-inflamatórios e melhoria do manejo reprodutivo.`,`Apenas reposição hormonal.`,`Apenas castração.`,`Apenas suplementação vitamínica.`,`Nenhum tratamento é eficaz.`],resposta_correta:`A`,explicacao:`O tratamento de infertilidade infecciosa: 1) Identificação do agente (cultura, PCR, sorologia), 2) Antibioticoterapia dirigida (antibiograma), 3) Anti-inflamatórios, 4) Correção de fatores predisponentes (higiene, manejo), 5) Reavaliação seminal após tratamento.`},{id:`andro-156`,banca:`UFMG`,ano:2020,prova:`UFMG — Professor Assistente 2020`,tipo:`pos`,topico:`infertilidade_masculina`,subtopico:`Hipogonadismo`,dificuldade:`dificil`,enunciado:`O hipogonadismo hipogonadotrópico no macho é causado por:`,alternativas:[`Deficiência na produção de GnRH, LH ou FSH, resultando em baixa testosterona e falha na espermatogênese.`,`Excesso de testosterona.`,`Deficiência de receptores andrógenos.`,`Excesso de FSH.`,`Hiperatividade das células de Leydig.`],resposta_correta:`A`,explicacao:`O hipogonadismo hipogonadotrópico (pré-testicular): deficiência de GnRH (síndrome de Kallmann), LH (hipopituitarismo), FSH → baixa testosterona + falha de espermatogênese. Causas: tumores hipofisários, genéticos, medicamentosos. Diagnóstico: LH/FSH/testosterona baixos. Tratamento: GnRH/hCG/FSH.`},{id:`andro-157`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Efeito da temperatura`,dificuldade:`medio`,enunciado:`O estresse térmico nos testículos pode causar:`,alternativas:[`Degeneração do epitélio seminífero, redução da espermatogênese, aumento de anormalidades espermáticas e infertilidade temporária ou permanente.`,`Aumento da produção de espermatozoides.`,`Melhora da motilidade espermática.`,`Aumento da testosterona.`,`Nenhum efeito sobre a fertilidade.`],resposta_correta:`A`,explicacao:`A elevação da temperatura testicular (febre, criptorquidia, varicocele, febre de transporte) causa degeneração do epitélio seminífero (células germinativas são sensíveis ao calor). A recuperação pode levar 60-90 dias (tempo da espermatogênese). Temperatura escrotal ideal: 34-35°C.`},{id:`andro-158`,banca:`USP`,ano:2023,prova:`USP — Doutorado Reprodução 2023`,tipo:`pos`,topico:`infertilidade_masculina`,subtopico:`Genética e infertilidade`,dificuldade:`dificil`,enunciado:`Anomalias cromossômicas que causam infertilidade masculina incluem:`,alternativas:[`Síndrome de Klinefelter (XXY), inversão do cromossomo Y e microdeleções do cromossomo Y (região AZF).`,`Apenas trissomia do 21.`,`Apenas monossomia X.`,`Apenas translocações robertsonianas.`,`Nenhuma anomalia cromossômica afeta a fertilidade.`],resposta_correta:`A`,explicacao:`Anomalias genéticas associadas à infertilidade: Síndrome de Klinefelter (47,XXY → azoospermia), microdeleções do Y (região AZF → oligo/azoospermia), translocações Robertsonianas (homens com 21;21 → falha meiótica), mutações no gene CFTR (azoospermia obstrutiva por agenesia de ducto deferente).`},{id:`andro-159`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso Veterinário 2023`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Prognóstico de infertilidade`,dificuldade:`medio`,enunciado:`O prognóstico de infertilidade masculina depende de:`,alternativas:[`Causa subjacente (tratável vs. irreversível), grau de degeneração testicular, idade do animal e resposta ao tratamento.`,`Apenas da idade do animal.`,`Apenas da raça.`,`Apenas do peso corporal.`,`Não é possível determinar prognóstico.`],resposta_correta:`A`,explicacao:`Prognóstico: causas tratáveis (infecções, deficiências nutricionais) → bom. Causas irreversíveis (degeneração severa, anomalias genéticas, criptorquidia bilateral) → reservado a ruim. Fatores: idade, grau de degeneração, bilateralidade da lesão, tempo de doença.`},{id:`andro-160`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Federal Agropecuário 2022`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Suplementação mineral`,dificuldade:`facil`,enunciado:`Os minerais essenciais para a fertilidade masculina incluem:`,alternativas:[`Selênio (antioxidante, integridade de membrana), zinco (metabolismo de testosterona), manganês e cobre.`,`Apenas cálcio e fósforo.`,`Apenas ferro.`,`Apenas sódio e potássio.`,`Nenhum mineral afeta a fertilidade.`],resposta_correta:`A`,explicacao:`Minerais importantes: selênio (componente da glutationa peroxidase, protege membranas espermáticas), zinco (metabolismo de testosterona, integridade do DNA), manganês (espermatogênese), cobre (enzimas antioxidantes), iodo (metabolismo tireoidiano). Deficiências causam degeneração testicular.`},{id:`andro-161`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso Veterinário 2022`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Fator imunológico`,dificuldade:`dificil`,enunciado:`Anticorpos anti-espermatozoides (AAS) podem causar infertilidade por:`,alternativas:[`Agglutinação espermática, redução da motilidade, bloqueio da capacitação e impedimento da fecundação.`,`Aumento da motilidade espermática.`,`Melhora da reação acrossômica.`,`Aumento da produção espermática.`,`Nenhum efeito sobre os espermatozoides.`],resposta_correta:`A`,explicacao:`Os AAS (IgG, IgA) se ligam a antígenos da membrana espermática → agglutinação (cabeça-cabeça, cauda-cauda), redução da motilidade, bloqueio da capacitação/reação acrossômica, impedimento da ligação ZP3-espermatozoide. Causas: trauma, infecção, vasectomia, barreira hematotesticular rompida.`},{id:`andro-162`,banca:`UFBA`,ano:2023,prova:`UFBA — Concurso Veterinário 2023`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Diagnóstico por imagem`,dificuldade:`medio`,enunciado:`A ultrassonografia escrotal é útil no diagnóstico de infertilidade masculina porque:`,alternativas:[`Permite avaliar a ecotextura testicular, detectar massas, cistos, abscessos, hidrocele e varicocele.`,`Apenas mede o tamanho testicular.`,`Apenas avalia a próstata.`,`Substitui completamente a avaliação seminal.`,`Apenas é útil em equinos.`],resposta_correta:`A`,explicacao:`A ultrassonografia escrotal com transdutor linear de alta frequência (7,5-12 MHz) avalia: ecotextura testicular (heterogeneidade = degeneração), massas (neoplasia), cistos (espermatocele), abscessos, hidrocele, varicocele (Doppler), tamanho e volume testicular. Essencial no exame andrológico.`},{id:`andro-163`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso Médico Veterinário 2022`,tipo:`concurso`,topico:`infertilidade_masculina`,subtopico:`Teste de fertilidade`,dificuldade:`facil`,enunciado:`O teste de fertilidade mais importante para avaliar o potencial reprodutivo de um macho é:`,alternativas:[`Avaliação seminal (exame andrológico), que inclui motilidade, morfologia, concentração e vitalidade espermática.`,`Apenas exame de sangue.`,`Apenas palpação testicular.`,`Apenas ultrassonografia.`,`Apenas teste de libido.`],resposta_correta:`A`,explicacao:`O exame andrológico com avaliação seminal é o padrão-ouro: motilidade total/progressiva, morfologia (anormalidades primárias/secundárias), concentração, vitalidade, teste HOST, citologia. É o melhor indicador de potencial fértil, embora o teste definitivo seja a taxa de prenhez.`},{id:`andro-164`,banca:`CESPE`,ano:2021,prova:`CESPE — Professor Universitário 2021`,tipo:`pos`,topico:`infertilidade_masculina`,subtopico:`Densidade espermática`,dificuldade:`dificil`,enunciado:`A fragmentação do DNA espermático é:`,alternativas:[`Uma causa oculta de infertilidade masculina, na qual o DNA do espermatozoide apresenta quebras (single ou double strand), detectada por TUNEL, SCSA ou teste comet.`,`Uma anormalidade morfológica visível ao microscópio.`,`Uma causa de aumento de motilidade.`,`Um sinal de fertilidade aumentada.`,`Não detectável por métodos laboratoriais.`],resposta_correta:`A`,explicacao:`A fragmentação de DNA espermático é uma causa oculta de infertilidade (espermograma pode parecer normal). Métodos de detecção: TUNEL (terminal deoxynucleotidyl transferase), SCSA (Sperm Chromatin Structure Assay), teste comet (eletroforese). Alta fragmentação → falha de fertilização, aborto, má qualidade embrionária.`},{id:`andro-165`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Crioprotetores permeáveis`,dificuldade:`medio`,enunciado:`Os crioprotetores permeáveis mais utilizados na criopreservação de sêmen são:`,alternativas:[`Glicerol, dimetilsulfóxido (DMSO), etilenoglicol e propilenoglicol.`,`Gema de ovo e leite desnatado.`,`Sacarose e trealose.`,`Albumina sérica.`,`Heparina e penicilina.`],resposta_correta:`A`,explicacao:`Crioprotetores permeáveis: glicerol (mais usado em bovinos, 4-7%), DMSO (usado em algumas espécies), etilenoglicol e propilenoglicol (penetram mais rapidamente). Atuam substituindo água intracelular, reduzindo formação de cristos de gelo intracelulares. Gema de ovo e leite são não-permeáveis (proteção de membrana).`},{id:`andro-166`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Mecanismo de congelamento`,dificuldade:`dificil`,enunciado:`Julgue o item sobre o mecanismo de congelamento de sêmen.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`Durante o congelamento, a água intracelular forma cristos de gelo que podem danificar organelas e membranas celulares. Os crioprotetores permeáveis reduzem a formação de gelo intracelular, enquanto taxas de congelamento adequadas (-15 a -25°C/min) permitem desidratação controlada.`,explicacao:`O congelamento causa: desidratação celular (formação de gelo extracelular → aumento osmolaridade → saída de água), formação de gelo intracelular (se congelamento muito rápido) ou cristalização extracelular (se muito lento). Taxa ideal: -15 a -25°C/min. Resfriamento muito rápido → gelo intracelular; muito lento → efeito salino.`},{id:`andro-167`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Gema de ovo no diluente`,dificuldade:`medio`,enunciado:`A gema de ovo no diluente de sêmen tem como função:`,alternativas:[`Proteger os espermatozoides contra choque térmico, fornecendo colesterol e lipoproteínas que estabilizam a membrana plasmática.`,`Fornecer substrato energético (glicose).`,`Atuar como antibiótico.`,`Regular o pH do diluente.`,`Atuar como crioprotetor permeável.`],resposta_correta:`A`,explicacao:`A gema de ovo (15-20%) contém lipoproteínas de baixa densidade (LDL) e colesterol que interagem com a membrana plasmática espermática, aumentando sua fluidez e resistência ao choque térmico. Não é crioprotetor permeável (não entra na célula). O glicerol é o crioprotetor permeável.`},{id:`andro-168`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Viabilidade pós-descongelamento`,dificuldade:`medio`,enunciado:`A viabilidade espermática mínima aceitável após descongelamento de sêmen bovino para IA é:`,alternativas:[`Motilidade progressiva ≥30-35% e morfologia normal ≥50%.`,`Motilidade progressiva ≥90% e morfologia normal ≥95%.`,`Motilidade progressiva ≥5% e morfologia normal ≥10%.`,`Motilidade progressiva ≥70% e morfologia normal ≥80%.`,`Não existem parâmetros mínimos.`],resposta_correta:`A`,explicacao:`Parâmetros mínimos para sêmen bovino descongelado: motilidade progressiva ≥30-35%, morfologia normal ≥50%, vitalidade ≥50%, integridade de membrana (HOST) ≥50%. Valores abaixo sugerem redução de fertilidade. Centrais de IA rigorosas exigem >50% motilidade progressiva.`},{id:`andro-169`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`criopreservacao`,subtopico:`Congelamento de sêmen equino`,dificuldade:`dificil`,enunciado:`O congelamento de sêmen equino é mais desafiador que o de sêmen bovino porque:`,alternativas:[`Os espermatozoides equinos são mais sensíveis ao choque térmico e ao dano osmótico, e o plasma seminal equino contém substâncias que prejudicam a viabilidade espermática durante o congelamento.`,`O volume ejaculado é menor.`,`Os espermatozoides equinos são menores.`,`Não há diluentes adequados.`,`O sêmen equino congela espontaneamente.`],resposta_correta:`A`,explicacao:`Sêmen equino é mais sensível: maior susceptibilidade ao choque térmico, sensibilidade osmótica, efeito deletério do plasma seminal (substâncias do epidídimo e glândulas acessórias prejudicam congelabilidade). Protocolos incluem remoção do plasma seminal (centrifugação) antes do congelamento.`},{id:`andro-170`,banca:`CRMV`,ano:2021,prova:`CRMV-RS — Prova de Suficiência 2021`,tipo:`crmv`,topico:`criopreservacao`,subtopico:`Congelamento de sêmen canino`,dificuldade:`medio`,enunciado:`O congelamento de sêmen canino é menos eficiente que o de sêmen bovino porque:`,alternativas:[`Espermatozoides caninos são mais sensíveis ao congelamento, resultando em menor taxa de prenhez com sêmen congelado (~50-70%) comparado a sêmen fresco (~85%).`,`Cães não produzem espermatozoides suficientes.`,`Não existem diluentes para sêmen canino.`,`O congelamento canino é mais eficiente que o bovino.`,`Cães são férteis apenas com sêmen fresco.`],resposta_correta:`A`,explicacao:`Sêmen canino é mais sensível ao congelamento que o bovino: maior dano de membrana, menor viabilidade pós-descongelamento. Taxa de prenhez: sêmen fresco ~85%, refrigerado ~75%, congelado ~50-70%. Depósito intrauterino (transcervical/cirúrgico) melhora resultados com sêmen congelado.`},{id:`andro-171`,banca:`UFMG`,ano:2023,prova:`UFMG — Doutorado Reprodução 2023`,tipo:`pos`,topico:`criopreservacao`,subtopico:`Vitrificação de sêmen`,dificuldade:`dificil`,enunciado:`A vitrificação de sêmen é:`,alternativas:[`Uma técnica de ultracongelamento rápido que evita a formação de cristos de gelo, resultando em estado vítreo, mas com alta toxicidade dos crioprotetores necessários.`,`Sinônimo de congelamento convencional.`,`Uma técnica que não requer crioprotetores.`,`Uma técnica que preserva o sêmen em temperatura ambiente.`,`Uma técnica que só funciona com embriões.`],resposta_correta:`A`,explicacao:`A vitrificação é o resfriamento ultrarrápido (>15.000°C/min) que transforma a solução em vidro (estado amorfo) sem formação de cristos de gelo. Requer altas concentrações de crioprotetores (tóxicos). Tem sido estudada para sêmen bovino e humano com resultados promissores mas variáveis.`},{id:`andro-172`,banca:`UNESP`,ano:2022,prova:`UNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Trealose`,dificuldade:`medio`,enunciado:`A trealose é um dissacarídeo utilizado como crioprotetor não permeável em:`,alternativas:[`Preservação de sêmen de espécies selvagens e domésticas, atuando como substituto da gema de ovo, sem risco de contaminação patogênica.`,`Substituir o glicerol como crioprotetor permeável.`,`Apenaz na preservação de ovócitos.`,`Apenaz na preservação de bactérias.`,`Não é utilizada em reprodução animal.`],resposta_correta:`A`,explicacao:`A trealose é um dissacarídeo não tóxico que atua como crioprotetor não permeável, estabilizando membranas por substituição de água (hidratação de cabeça lipídica). Usada em diluentes sintéticos sem gema de ovo (para exportação de sêmen), reduzindo risco de contaminação patogênica.`},{id:`andro-173`,banca:`USP`,ano:2020,prova:`USP — Doutorado em Reprodução 2020`,tipo:`pos`,topico:`criopreservacao`,subtopico:`Armazenamento em N₂`,dificuldade:`facil`,enunciado:`O armazenamento de sêmen congelado em nitrogênio líquido (-196°C) deve ser:`,alternativas:[`Monitorado regularmente, com manutenção do nível de N₂, organização das palhetas em canisters e registro de cada amostra.`,`Realizado em geladeira doméstica.`,`Em temperatura ambiente.`,`Em freezer convencional (-20°C).`,`Em banho-maria.`],resposta_correta:`A`,explicacao:`O armazenamento em N₂ líquido (-196°C): manter nível de N₂ (monitorar semanalmente), canisters etiquetados, registro de cada palheta (macho, data, qualidade), manuseio com luvas/capacete (prevenção de queimaduras por N₂), backup em tanque secundário.`},{id:`andro-174`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso Veterinário 2021`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Recristalização`,dificuldade:`medio`,enunciado:`A recristalização durante o descongelamento de sêmen é:`,alternativas:[`A fusão e recrescimento de cristos de gelo pequenos em cristos maiores, causando dano celular, e ocorre quando o descongelamento é muito lento.`,`A formação inicial de cristos de gelo durante o congelamento.`,`Um processo benéfico que melhora a viabilidade espermática.`,`A desidratação celular durante o congelamento.`,`A penetra do crioprotetor na célula.`],resposta_correta:`A`,explicacao:`A recristalização ocorre quando o descongelamento é lento: cristos de gelo pequenos fundem e recrescem em cristos maiores, causando dano mecânico às membranas e organelas. Por isso o descongelamento deve ser rápido (35-37°C, 20-30 segundos) para minimizar a recristalização.`},{id:`andro-175`,banca:`MAPA`,ano:2020,prova:`MAPA — Fiscal Federal Agropecuário 2020`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Equilíbrio com glicerol`,dificuldade:`medio`,enunciado:`O período de equilíbrio com glicerol durante o processamento de sêmen bovino é:`,alternativas:[`4 horas a 5°C, para permitir a penetração gradual do glicerol na célula sem causar choque osmótico.`,`30 segundos à temperatura ambiente.`,`24 horas a 37°C.`,`5 minutos a -20°C.`,`Não é necessário período de equilíbrio.`],resposta_correta:`A`,explicacao:`Após resfriamento até 5°C, o sêmen é equilibrado com glicerol (4-7%) por ~4 horas. Esse período permite a penetração gradual do glicerol nas células, minimizando o choque osmótico. O glicerol é adicionado ao diluente em duas etapas (50% antes do resfriamento, 50% a 5°C).`},{id:`andro-176`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso Veterinário 2021`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Liofilização de sêmen`,dificuldade:`dificil`,enunciado:`A liofilização (freeze-drying) de sêmen é uma técnica:`,alternativas:[`Que preserva espermatozoides em temperatura ambiente por desidratação a frio, mas resulta em perda de motilidade e viabilidade, sendo usada apenas para preservação de material genético (DNA) e não para IA convencional.`,`Idêntica ao congelamento convencional.`,`Que mantém a motilidade espermática.`,`Usada rotineiramente em centrais de IA.`,`Que não é possível com sêmen animal.`],resposta_correta:`A`,explicacao:`A liofilização remove a água por sublimação (vácuo + frio). Espermatozoides liofilizados perdem motilidade e membrana, mas o DNA é preservado. Usado para preservar genoma (ICSI com espermatozoides liofilizados). Armazenamento em temperatura ambiente. Não serve para IA convencional.`},{id:`andro-177`,banca:`UFBA`,ano:2020,prova:`UFBA — Concurso Veterinário 2020`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Efeito do glicerol`,dificuldade:`medio`,enunciado:`O glicerol é mais eficaz que outros crioprotetores para sêmen bovino porque:`,alternativas:[`Possui taxa de permeabilidade ideal, permite desidratação controlada e proteção contra cristalização intracelular com menor toxicidade.`,`É o mais barato disponível.`,`Não é mais eficaz que outros crioprotetores.`,`Não penetra na célula.`,`É o único crioprotetor disponível.`],resposta_correta:`A`,explicacao:`O glicerol tem permeabilidade intermediária (penetra em minutos), é efetivo em concentrações moderadas (4-7%), reduz o ponto de congelamento e previne cristalização intracelular. Outros (DMSO, etilenoglicol) podem ser tóxicos em altas concentrações ou ter permeabilidade inadequada.`},{id:`andro-178`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Taxa de resfriamento`,dificuldade:`medio`,enunciado:`A taxa de congelamento recomendada para sêmen bovino em palhetas é:`,alternativas:[`-15 a -25°C por minuto, de 5°C até -100°C, seguido de transferência para N₂ líquido (-196°C).`,`-1°C por minuto até -196°C.`,`-100°C por minuto.`,`Congelamento instantâneo.`,`Não existe taxa recomendada.`],resposta_correta:`A`,explicacao:`Taxa de congelamento: -15 a -25°C/min de 5°C até -100/-120°C (banho de etanol ou equipamento programável). Após -100°C, as palhetas são transferidas para N₂ líquido (-196°C). Taxas muito lentas causam efeito salino; muito rápidas causam gelo intracelular.`},{id:`andro-179`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Congelamento de sêmen suíno`,dificuldade:`dificil`,enunciado:`O congelamento de sêmen suíno é menos eficiente que o bovino porque:`,alternativas:[`Espermatozoides suínos são mais sensíveis ao choque térmico e osmótico, e o sêmen suíno contém alta concentração de substâncias deletérias no plasma seminal.`,`Suínos não produzem espermatozoides.`,`Não existem diluentes para sêmen suíno.`,`O sêmen suíno congela espontaneamente.`,`A temperatura corporal dos suínos é muito diferente.`],resposta_correta:`A`,explicacao:`Sêmen suíno é sensível ao congelamento: alta sensibilidade ao choque térmico e osmótico, dano pelo plasma seminal (substâncias do epidídimo, vesículas seminais). Resultado: menor viabilidade pós-descongelamento, menor taxa de prenhez que sêmen fresco/refrigerado. Protocolos otimizados melhoram resultados.`},{id:`andro-180`,banca:`UFRGS`,ano:2023,prova:`UFRGS — Professor Reprodução 2023`,tipo:`pos`,topico:`criopreservacao`,subtopico:`Resfriamento vs congelamento`,dificuldade:`facil`,enunciado:`A diferença entre resfriamento e congelamento de sêmen é:`,alternativas:[`Resfriamento: armazenamento a 5°C (refrigerado) por dias; Congelamento: armazenamento a -196°C (N₂ líquido) por tempo indeterminado.`,`São sinônimos.`,`Resfriamento é mais profundo que congelamento.`,`Congelamento é feito apenas em embriões.`,`Resfriamento é mais eficiente que congelamento.`],resposta_correta:`A`,explicacao:`Resfriamento: sêmen diluído armazenado a 5°C (geladeira) por 3-5 dias (suínos, equinos). Congelamento: sêmen congelado a -196°C em palhetas, armazenado em N₂ líquido indefinidamente. O congelamento permite armazenamento ilimitado e transporte internacional.`},{id:`andro-181`,banca:`UFRPE`,ano:2022,prova:`UFRPE — Concurso Veterinário 2022`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Controle de qualidade`,dificuldade:`medio`,enunciado:`O controle de qualidade em centrais de inseminação inclui:`,alternativas:[`Avaliação seminal pré e pós-congelamento, monitoramento de equipamentos, treinamento de pessoal e registro de dados.`,`Apenas avaliação de motilidade.`,`Apenas verificação do nível de N₂.`,`Apenas treinamento de pessoal.`,`Não existe controle de qualidade em centrais.`],resposta_correta:`A`,explicacao:`CQA (Controle de Qualidade): avaliação pré-congelamento (motilidade, morfologia, concentração), pós-descongelamento (motilidade, vitalidade, HOST), monitoramento de tanques (nível N₂, temperatura), calibração de equipamentos, registro de cada lote, treinamento contínuo.`},{id:`andro-182`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário IBAMA 2023`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Sêmen suíno refrigerado`,dificuldade:`medio`,enunciado:`O sêmen suíno refrigerado a 15-20°C pode ser armazenado por:`,alternativas:[`3-5 dias, mantendo viabilidade adequada para IA.`,`Apenas 2 horas.`,`30 dias.`,`Apenas 5 minutos.`,`Não pode ser refrigerado.`],resposta_correta:`A`,explicacao:`O sêmen suíno é refrigerado a 15-20°C (não 5°C, pois é mais sensível ao frio que o bovino) e pode ser armazenado por 3-5 dias. Diluentes como BTS, Androhep ou X-Cell são usados. Temperaturas mais baixas causam choque térmico.`},{id:`andro-183`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`DMSO`,dificuldade:`medio`,enunciado:`O dimetilsulfóxido (DMSO) como crioprotetor:`,alternativas:[`É um crioprotetor permeável alternativo ao glicerol, utilizado em algumas espécies e para preservação de tecido testicular, com ação antibacteriana adicional.`,`É exclusivamente não-permeável.`,`É mais tóxico que o glicerol em todas as concentrações.`,`Não é utilizado em reprodução animal.`,`É um crioprotetor exclusivo para embriões.`],resposta_correta:`A`,explicacao:`O DMSO é crioprotetor permeável alternativo, utilizado em preservação de tecido testicular, ovócitos e algumas espécies. Possui propriedades antibacterianas e penetra mais rapidamente que o glicerol. Pode ser tóxico em altas concentrações (>10%) ou longa exposição.`},{id:`andro-184`,banca:`UFPR`,ano:2022,prova:`UFPR — Concurso Veterinário 2022`,tipo:`concurso`,topico:`criopreservacao`,subtopico:`Congelamento de sêmen ovino`,dificuldade:`medio`,enunciado:`O congelamento de sêmen ovino para IA laparoscópica é:`,alternativas:[`Viável e utilizado comercialmente, com taxas de prenhez de 50-70% quando o sêmen é depositado diretamente no útero.`,`Impossível de realizar.`,`Apenas experimental.`,`Menos eficiente que o congelamento de sêmen suíno.`,`Apenas para preservação de genoma, sem fertilidade.`],resposta_correta:`A`,explicacao:`O sêmen ovino pode ser congelado com sucesso em diluente Tris-gema-glicerol. Para IA laparoscópica (depósito intrauterino), as taxas de prenhez são de 50-70%. A IA cervical com sêmen congelado tem taxas muito baixas (~20%) devido à tortuosidade da cérvix ovina.`},{id:`andro-185`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Exame andrológico em bovinos`,dificuldade:`medio`,enunciado:`O exame andrológico em touros inclui:`,alternativas:[`Avaliação do comportamento sexual (libido e habilidade de monta), exame genital externo, avaliação do períneo (prepúcio, pênis), exame genital interno e avaliação do sêmen.`,`Apenas avaliação do sêmen.`,`Apenas exame de sangue.`,`Apenas palpação retal.`,`Apenas ultrassonografia.`],resposta_correta:`A`,explicacao:`Exame andrológico bovino completo: 1) Comportamento sexual (libido, habilidade de monta), 2) Exame genital externo (testículos, epidídimo, escroto), 3) Períneo (prepúcio, pênis por tração), 4) Exame genital interno (próstata, vesículas seminais por palpação retal), 5) Avaliação seminal.`},{id:`andro-186`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Coleta em bovinos`,dificuldade:`medio`,enunciado:`A coleta de sêmen em touros é realizada por:`,alternativas:[`Vagina artificial acoplada a manequim/fêmea em estro, com o touro realizando monta.`,`Eletroejaculação retal.`,`Aspiração do epidídimo.`,`Massagem prostática.`,`Punção testicular.`],resposta_correta:`A`,explicacao:`A coleta em bovinos usa vagina artificial (pressão 40-50 cmH₂O, temperatura 40-42°C) posicionada em manequim (fêmea em estro à frente). O touro monta a fêmea/manequim, o pênis é desviado para a vagina artificial e a ejaculação ocorre normalmente.`},{id:`andro-187`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Avaliação de touros`,dificuldade:`medio`,enunciado:`A avaliação de touros reprodutores antes da estação de monta inclui:`,alternativas:[`Exame andrológico completo, exame clínico geral, exames laboratoriais (brucelose, tricomonose, campilobacterose) e avaliação de escore corporal.`,`Apenas exame clínico geral.`,`Apenas exame de sêmen.`,`Apenas vacinação.`,`Apenas avaliação de escore corporal.`],resposta_correta:`A`,explicacao:`Avaliação pré-estação de monta: exame clínico geral (vacinas, vermifugos, escore corporal 3-3,5), exame andrológico completo (libido, genital, sêmen), sorologias (Brucella, IBR/BHV-1, BVD, leptospirose), exames de prepúcio/pênis (Trichomonas, Campylobacter).`},{id:`andro-188`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Circunferência escrotal`,dificuldade:`facil`,enunciado:`A medida da circunferência escrotal em touros é importante porque:`,alternativas:[`Correlaciona-se positivamente com a produção espermática e é um indicador indireto de massa testicular.`,`Determina a idade do animal.`,`Indica o peso corporal.`,`Não tem relevância andrológica.`,`Mede apenas gordura escrotal.`],resposta_correta:`A`,explicacao:`A circunferência escrotal (CE) é medida com fita flexível no maior diâmetro dos testículos. Correlaciona-se com a massa testicular e produção espermática. Valores mínimos: touros Nelore >30 cm, taurinos >32 cm (adultos). CE baixa → menor produção espermática e possível degeneração.`},{id:`andro-189`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Prova de Título em Reprodução Animal 2020`,tipo:`pos`,topico:`andrologia_bovina`,subtopico:`BHV-1 e fertilidade`,dificuldade:`medio`,enunciado:`O herpesvírus bovino tipo 1 (BHV-1/IBR) pode causar:`,alternativas:[`Balanopostite pustular infecciosa, vulvovaginite e infertilidade transitória em bovinos.`,`Apenas doença respiratória.`,`Apenas diarreia.`,`Apenas mastite.`,`Não afeta o sistema reprodutivo.`],resposta_correta:`A`,explicacao:`BHV-1 causa: balanopostite pustular infecciosa (pústulas no pênis/prepúcio), vulvovaginite pustular infecciosa, aborto, rinotraqueíte infecciosa. Pode causar infertilidade transitória. Vacinação é recomendada para touros reprodutores.`},{id:`andro-190`,banca:`CRMV`,ano:2023,prova:`CRMV-SP — Prova de Suficiência 2023`,tipo:`crmv`,topico:`andrologia_bovina`,subtopico:`Vigor sexual`,dificuldade:`facil`,enunciado:`O vigor sexual (libido) em touros é avaliado:`,alternativas:[`Pelo tempo de reação (intervalo entre primeira exposição à fêmea e primeira monta) e frequência de montas em período determinado.`,`Pela quantidade de sêmen produzido.`,`Pelo tamanho dos testículos.`,`Pela idade do animal.`,`Pela concentração de testosterona no sangue.`],resposta_correta:`A`,explicacao:`O vigor sexual é avaliado pelo: tempo de reação (latência), número de montas por período, interesse pela fêmea (sniffing, flehmen), capacidade de ereção e ejaculação. Touros com libido baixa podem ter baixa fertilidade apesar de sêmen normal.`},{id:`andro-191`,banca:`UFMG`,ano:2021,prova:`UFMG — Professor Assistente 2021`,tipo:`pos`,topico:`andrologia_bovina`,subtopico:`Touros de monta natural`,dificuldade:`medio`,enunciado:`A relação touro:vaca recomendada para monta natural em bovinos é:`,alternativas:[`1:20 a 1:30 para touros adultos, dependendo do terreno, manejo e condição corporal.`,`1:1 (um touro por vaca).`,`1:100 para todos os casos.`,`Não existe relação recomendada.`,`1:10 para touros adultos.`],resposta_correta:`A`,explicacao:`Relação touro:vaca para monta natural: touros adultos experientes 1:25-30, touros jovens (primeira cobertura) 1:15-20. Fatores que influenciam: terreno (mata→menos, campo→mais), condição corporal, idade, período de cobertura, fertilidade do touro.`},{id:`andro-192`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Técnicas de preparação de sêmen`,dificuldade:`medio`,enunciado:`A técnica de Percoll ou gradiente descontínuo de densidade é usada em andrologia para:`,alternativas:[`Separar espermatozoides vivos e com morfologia normal de mortos, debris celulares e células redondas, melhorando a qualidade do sêmen para FIV e ICSI.`,`Aumentar o volume do ejaculado.`,`Determinar a concentração espermática.`,`Avaliar a motilidade espermática.`,`Congelar o sêmen.`],resposta_correta:`A`,explicacao:`O gradiente descontínuo de densidade (Percoll, PureSperm, Silane) separa espermatozoides por densidade: espermatozoides vivos/morfologicamente normais migram para o fundo (maior densidade), enquanto mortos/anormais/debris ficam no topo. Usado para preparação de sêmen para FIV e ICSI.`},{id:`andro-193`,banca:`USP`,ano:2022,prova:`USP — Mestrado em Reprodução 2022`,tipo:`pos`,topico:`andrologia_bovina`,subtopico:`Swim-up`,dificuldade:`medio`,enunciado:`A técnica de swim-up para preparação de sêmen consiste em:`,alternativas:[`Depositar o sêmen sob uma camada de meio de cultura; espermatozoides com boa motilidade nadam para cima (swim-up) e são coletados da camada superior.`,`Centrifugar o sêmen a alta velocidade.`,`Adicionar crioprotetor ao sêmen.`,`Avaliar a morfologia espermática.`,`Congelar o sêmen em palhetas.`],resposta_correta:`A`,explicacao:`Swim-up: sêmen depositado no fundo de tubo, coberto com meio de cultura (sem sêmen). Incubado 30-60 min a 37°C. Espermatozoides com motilidade progressiva migram (swim up) para a camada superior, de onde são coletados. Seleciona motilidade, mas tem baixo rendimento.`},{id:`andro-194`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Trichomonas fetus`,dificuldade:`medio`,enunciado:`A tricomonose bovina é:`,alternativas:[`Doença sexualmente transmissível causada por Tritrichomonas fetus, que causa infertilidade, repetição de cio e morte embrionária em fêmeas. O macho é portador assintomático.`,`Doença respiratória contagiosa.`,`Doença que afeta apenas o sistema nervoso.`,`Doença que causa diarreia em bezerros.`,`Doença que não afeta a reprodução.`],resposta_correta:`A`,explicacao:`A tricomonose (Tritrichomonas fetus) é DST que causa: em fêmeas — vaginite, cervicite, endometrite, morte embrionária, repetição de cio, piometra. O macho é portador assintomático (o parasita se aloja no prepúcio). Diagnóstico: cultura de swab prepucial. Não há tratamento eficaz para machos.`},{id:`andro-195`,banca:`MAPA`,ano:2021,prova:`MAPA — Fiscal Federal Agropecuário 2021`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Campylobacter fetus`,dificuldade:`medio`,enunciado:`A campilobacterose genital bovina é causada por:`,alternativas:[`Campylobacter fetus venerealis, transmitida por coito, causando infertilidade e aborto em fêmeas. O touro é portador no prepúcio.`,`Campylobacter jejuni, que causa diarreia.`,`Campylobacter coli, que causa enterite.`,`Não existe campilobacterose genital.`,`Campylobacter fetus, que causa doença respiratória.`],resposta_correta:`A`,explicacao:`Campylobacter fetus venerealis é DST: causa vaginite, endometrite, morte embrionária, aborto precoce em fêmeas. O touro é portador prepucial assintomático (especialmente touros velhos). Diagnóstico: cultura microaerófila de swab prepucial. Vacinação é a principal medida de controle.`},{id:`andro-196`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Escore corporal e fertilidade`,dificuldade:`facil`,enunciado:`O escore corporal ideal para touros antes da estação de monta é:`,alternativas:[`3,0 a 3,5 (escala 1-5), garantindo boa condição nutricional sem excesso de gordura que comprometa a termorregulação testicular.`,`1,0 a 1,5 (muito magro).`,`5,0 (obeso).`,`Não existe escore corporal para touros.`,`2,0 a 2,5.`],resposta_correta:`A`,explicacao:`Touros com escore 3,0-3,5 (escala 1-5) têm melhor desempenho reprodutivo. Touros magros (<2,5) têm libido reduzida e degeneração testicular. Obesos (>4,0) podem ter comprometimento da termorregulação escrotal (gordura escrotal → aumento da temperatura).`},{id:`andro-197`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso Veterinário 2022`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Perímetro escrotal mínimo`,dificuldade:`facil`,enunciado:`O perímetro escrotal mínimo para aprovação de um touro reprodutor adulto (taurino) no exame andrológico é:`,alternativas:[`32 cm.`,`20 cm.`,`40 cm.`,`50 cm.`,`15 cm.`],resposta_correta:`A`,explicacao:`Valores mínimos de perímetro escrotal (CE) para touros adultos: taurinos ≥32 cm, Nelore ≥30 cm. Para jovens (18-24 meses): taurinos ≥28 cm, Nelore ≥26 cm. CE abaixo do mínimo indica massa testicular insuficiente e produção espermática reduzida.`},{id:`andro-198`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Prepúcio e pênis bovino`,dificuldade:`facil`,enunciado:`O exame do pênis e prepúcio em touros é realizado:`,alternativas:[`Por tração do pênis (pênis fibroelástico com flexura sigmoide permite exteriorização sem sedação) e exame visual da glande, corpo do pênis e prepúcio.`,`Apenas por ultrassonografia.`,`Apenas por endoscopia.`,`Apenas sob anestesia geral.`,`Não é possível examinar o pênis em touros.`],resposta_correta:`A`,explicacao:`O pênis bovino (fibroelástico) pode ser exteriorizado por tração manual (pressão na ponta do pênis dentro do prepúcio → pênis sai pela flexura sigmoide). Exame visual: glande, fossa glandis, processo uretral, corpo do pênis, prepúcio. Avalia lesões, aderências, anomalias.`},{id:`andro-199`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Garanhões de provas de monta`,dificuldade:`medio`,enunciado:`As provas de monta para avaliação de touros reprodutores consistem em:`,alternativas:[`Permitir que o touro monte fêmeas em estro, avaliando libido, capacidade de ereção, penetração, ejaculação e desmonta.`,`Apenas medir os testículos.`,`Apenas coletar sêmen.`,`Apenas avaliar o sangue.`,`Apenas ultrassonografia escrotal.`],resposta_correta:`A`,explicacao:`Prova de monta: touro é exposto a fêmeas em estro. Avalia-se: tempo de reação (latência), interesse sexual, ereção, monta, penetração (pênis no prepúcio da fêmea), ejaculação (espasmo de cópula), desmonta. Identifica problemas de libido, defeitos de monta, incapacidade de ejaculação.`},{id:`andro-200`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário Prefeitura 2020`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Classificação andrológica`,dificuldade:`medio`,enunciado:`No exame andrológico de touros, a classificação "aprovado" significa que:`,alternativas:[`O touro atende a todos os parâmetros mínimos (comportamento sexual, genital, sêmen) para uso como reprodutor.`,`O touro tem sêmen congelável.`,`O touro está apto apenas para monta natural.`,`O touro tem apenas libido adequada.`,`O touro não precisa de acompanhamento.`],resposta_correta:`A`,explicacao:`Classificação andrológica: Aprovado (todos os parâmetros adequados), Reprovado (parâmetros inadequados, sem possibilidade de uso), Suspeito (alterações que necessitam reavaliação). Critérios: libido, habilidade de monta, perímetro escrotal, motilidade, morfologia, concentração.`},{id:`andro-201`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Prova de comportamento sexual`,dificuldade:`medio`,enunciado:`Na avaliação do comportamento sexual de touros, a libido é classificada como:`,alternativas:[`Escores de 0 (ausente) a 5 (muito alta), baseados no tempo de reação e intensidade de interesse pela fêmea.`,`Apenas presente ou ausente.`,`Por dosagem de testosterona.`,`Pela análise do sêmen.`,`Não existe classificação de libido.`],resposta_correta:`A`,explicacao:`Escala de libido: 0 = sem interesse, 1 = interesse fraco (>3 min), 2 = interesse moderado (2-3 min), 3 = bom (1-2 min), 4 = muito bom (30s-1min), 5 = excelente (<30s). Baseada no tempo de reação à primeira monta. Libido baixa → redução de fertilidade.`},{id:`andro-202`,banca:`UFRGS`,ano:2020,prova:`UFRGS — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Puberdade em touros`,dificuldade:`facil`,enunciado:`A puberdade em touros da raça Nelore ocorre, em média, aos:`,alternativas:[`18-24 meses, mais tardiamente que em taurinos (12-15 meses).`,`6-8 meses.`,`36-48 meses.`,`4-6 meses.`,`A puberdade não depende da raça.`],resposta_correta:`A`,explicacao:`A puberdade em bovinos: taurinos 12-15 meses, zebuínos (Nelore) 18-24 meses. A maturidade sexual completa (capacidade máxima de produção espermática) ocorre mais tardiamente. Fatores: nutrição, genética, ambiente, fotoperíodo.`},{id:`andro-203`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Infertilidade infecciosa`,dificuldade:`medio`,enunciado:`As principais DSTs que acometem touros reprodutores são:`,alternativas:[`Tricomonose (Tritrichomonas fetus), campilobacterose (Campylobacter fetus venerealis) e balanopostite pustular infecciosa (BHV-1).`,`Raiva e febre aftosa.`,`Brucelose e tuberculose.`,`Leptospirose e salmonelose.`,`Apenas mastite.`],resposta_correta:`A`,explicacao:`DSTs de touros: 1) Tricomonose (T. fetus) — portador prepucial, sem tratamento eficaz, confirmação por cultura. 2) Campilobacterose (C. fetus venerealis) — portador prepucial, vacinação. 3) BHV-1 (balanopostite pustular) — pústulas no pênis, vacinação.`},{id:`andro-204`,banca:`UFPR`,ano:2020,prova:`UFPR — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_bovina`,subtopico:`Desempenho reprodutivo de touros`,dificuldade:`medio`,enunciado:`O desempenho reprodutivo de um touro em monta natural pode ser avaliado por:`,alternativas:[`Taxa de prenhez das fêmeas cobertas, exame andrológico periódico e acompanhamento das gestações.`,`Apenas pela quantidade de sêmen produzido.`,`Apenas pelo peso do animal.`,`Apenas pela idade.`,`Apenas pelo pedigree.`],resposta_correta:`A`,explicacao:`O desempenho reprodutivo é avaliado por: taxa de prenhez (>90% em cobertura de 60-90 dias), exames andrológicos periódicos (pré e pós-estação), acompanhamento de gestações (ultrassom), ecografia fetal, nascimento de bezerros. Fatores: fertilidade individual, relação touro:vaca.`},{id:`andro-205`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Exame andrológico em equinos`,dificuldade:`medio`,enunciado:`O exame andrológico em garanhões inclui:`,alternativas:[`Avaliação de libido, exame genital externo e interno, coleta com vagina artificial, avaliação seminal e exames complementares (ultrassom, cultura).`,`Apenas exame clínico geral.`,`Apenas palpação retal.`,`Apenas avaliação do sêmen.`,`Apenas ultrassonografia prostática.`],resposta_correta:`A`,explicacao:`Exame andrológico equino: 1) Anamnese, 2) Exame clínico, 3) Libido (tempo de reação, monta), 4) Genital externo (testículos, epidídimo, escroto), 5) Genital interno (palpação retal: vesículas seminais, próstata), 6) Pênis e prepúcio, 7) Coleta (vagina artificial), 8) Avaliação seminal.`},{id:`andro-206`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Coleta em equinos`,dificuldade:`medio`,enunciado:`A coleta de sêmen em garanhões é realizada:`,alternativas:[`Com vagina artificial posicionada sobre a égua ou manequim, após monta do garanhão, seguida de avaliação imediata.`,`Por eletroejaculação retal.`,`Por aspiração do epidídimo.`,`Por punção testicular.`,`Apenas por coleta à mão (hand collection).`],resposta_correta:`A`,explicacao:`A coleta equina usa vagina artificial (tipo Missouri, Colorado, ou similar) posicionada sobre a égua em estro ou manequim. O garanhão monta, ejacula na vagina artificial (pressão 40-60 mmHg, temperatura 45-50°C). O sêmen é avaliado imediatamente.`},{id:`andro-207`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Libido em garanhões`,dificuldade:`facil`,enunciado:`A libido em garanhões é influenciada por:`,alternativas:[`Idade, experiência, estação reprodutiva, fotoperíodo, condição nutricional e fatores ambientais (temperatura, presença de éguas).`,`Apenas pela idade.`,`Apenas pela raça.`,`Apenas pela alimentação.`,`Não é influenciada por fatores externos.`],resposta_correta:`A`,explicacao:`Libido equina: maior na primavera/verão (fotoperíodo longo), diminui no inverno. Influências: idade (jovens=maior, velhos=menor), experiência, condição nutricional, temperatura, presença de éguas em estro, fatores psicológicos (estresse, medo).`},{id:`andro-208`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Sêmen equino`,dificuldade:`medio`,enunciado:`O sêmen equino difere do bovino principalmente por:`,alternativas:[`Maior volume (50-150 mL), maior concentração espermática e ejaculado em frações (pre-espermática, espermática, post-espermática).`,`Menor volume e menor concentração.`,`Volume idêntico, mas menor concentração.`,`Ausência de frações no ejaculado.`,`Coloração escura.`],resposta_correta:`A`,explicacao:`Sêmen equino: volume 50-150 mL, concentração 100-350 milhões/mL, total 5-15 bilhões. Ejaculado em frações: pre-espermática (glândulas bulbouretrais, clara), espermática (testículo/epidídimo, leitosa), gel (vesículas seminais, coágulo), post-espermática (vesículas seminais, clara).`},{id:`andro-209`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`andrologia_equina`,subtopico:`Fossa uretral equina`,dificuldade:`dificil`,enunciado:`A fossa uretral (divertículo suburetral) em garanhões:`,alternativas:[`É uma depressão na parede ventral da uretra pélvica, que pode acumular secreção e bactérias (Taylorella, Pseudomonas, Klebsiella), sendo um foco de infecção genital.`,`É uma estrutura exclusiva de éguas.`,`Não tem relevância clínica.`,`É uma glândula acessória do sistema reprodutor.`,`Está localizada no pênis.`],resposta_correta:`A`,explicacao:`A fossa uretral é uma depressão na parede ventral da uretra pélvica, logo caudal à próstata. Pode acumular secreção e bactérias (T. equigenitalis, Pseudomonas, Klebsiella), sendo foco de infecção para éguas durante o coito. Lavagem/antissepsia é recomendada antes da cobertura.`},{id:`andro-210`,banca:`CRMV`,ano:2021,prova:`CRMV-RS — Prova de Suficiência 2021`,tipo:`crmv`,topico:`andrologia_equina`,subtopico:`Coleta de sêmen equino`,dificuldade:`medio`,enunciado:`A vagina artificial para coleta em equinos difere da bovina por:`,alternativas:[`Ser maior, ter temperatura mais alta (45-50°C), pressão mais baixa (40-60 mmHg) e incluir recipiente coletor para separar frações.`,`Ser idêntica à vagina artificial bovina.`,`Ser menor e mais simples.`,`Não possuir aquecimento.`,`Ser de uso único.`],resposta_correta:`A`,explicacao:`A vagina artificial equina é maior (50-60 cm), com camisa de látex/silicone, temperatura 45-50°C (maior que bovina), pressão 40-60 mmHg, recipiente coletor (filtrante) para separar frações e remover gel. Modelos: Missouri, Colorado, Hannover.`},{id:`andro-211`,banca:`UFMG`,ano:2022,prova:`UFMG — Professor Assistente 2022`,tipo:`pos`,topico:`andrologia_equina`,subtopico:`Comportamento sexual equino`,dificuldade:`medio`,enunciado:`O comportamento sexual do garanhão inclui:`,alternativas:[`Flehmen (reflexo de elevação do lábio superior), vocalização, monta, ereção, ejaculação e desmonta.`,`Apenas monta e ejaculação.`,`Apenas vocalização.`,`Apenas ereção.`,`Não existe comportamento sexual característico.`],resposta_correta:`A`,explicacao:`Comportamento sexual equino: 1) Flehmen (elevação do lábio superior, exposição de feromônios ao órgão vomeronasal), 2) Vocalização (relinchos), 3) Sniffing genital, 4) Monta, 5) Ereção (estímulos visuais, olfativos), 6) Ejaculação (espasmo de cópula), 7) Desmonta.`},{id:`andro-212`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Puberdade em equinos`,dificuldade:`facil`,enunciado:`A puberdade em garanhões ocorre, em média, aos:`,alternativas:[`12-24 meses, variando com a raça, nutrição e fotoperíodo.`,`6 meses.`,`48-60 meses.`,`3-4 meses.`,`Não existe puberdade em equinos.`],resposta_correta:`A`,explicacao:`A puberdade em garanhões: 12-24 meses (raças leves ~12-15 meses, pesadas ~18-24 meses). A maturidade sexual completa ocorre por volta dos 3-4 anos. O uso para cobertura antes da maturidade completa não é recomendado.`},{id:`andro-213`,banca:`USP`,ano:2023,prova:`USP — Doutorado em Reprodução 2023`,tipo:`pos`,topico:`andrologia_equina`,subtopico:`Frações ejaculatórias`,dificuldade:`dificil`,enunciado:`O ejaculado equino é composto por três frações principais:`,alternativas:[`Pre-espermática (clara, glândulas bulbouretrais), espermática (leitosa, rica em espermatozoides, epidídimo + próstata) e post-espermática/gel (vesículas seminais).`,`Apenas uma fração homogênea.`,`Duas frações: espermática e urinária.`,`Quatro frações iguais.`,`Cinco frações com volumes idênticos.`],resposta_correta:`A`,explicacao:`Frações ejaculatórias equinas: 1) Pre-espermática (5-60 mL, clara, das glândulas bulbouretrais — lubrifica uretra), 2) Espermática (30-60 mL, leitosa, do epidídimo + próstata — contém espermatozoides), 3) Post-espermática/gel (20-100 mL, das vesículas seminais — forma coágulo/gel).`},{id:`andro-214`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Perímetro escrotal equino`,dificuldade:`facil`,enunciado:`O perímetro escrotal mínimo para aprovação de garanhões adultos no exame andrológico é:`,alternativas:[`30 cm (raças leves) a 35 cm (raças pesadas).`,`20 cm.`,`50 cm.`,`60 cm.`,`Não existe parâmetro mínimo.`],resposta_correta:`A`,explicacao:`Perímetro escrotal equino: raças leves ≥30 cm, raças pesadas ≥35 cm, pôneis ≥25 cm. Valores abaixo sugerem hipoplasia testicular ou degeneração. O volume testicular é proporcional à produção espermática.`},{id:`andro-215`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Federal Agropecuário 2022`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Metrite contagiosa equina`,dificuldade:`medio`,enunciado:`A metrite contagiosa equina (MCE) é causada por:`,alternativas:[`Taylorella equigenitalis, uma DST que causa endometrite, cervicite e infertilidade em éguas. O garanhão é portador assintomático no pênis e prepúcio.`,`Vírus da influenza equina.`,`Bactéria Streptococcus equi.`,`Fungo Aspergillus.`,`Não é causada por microrganismos.`],resposta_correta:`A`,explicacao:`MCE (Taylorella equigenitalis): DST que causa endometrite aguda, cervicite, descarga vulvar, infertilidade em éguas. Garanhões são portadores assintomáticos (pênis, prepúcio, fossa uretral). Diagnóstico: cultura (meio EMJH). Tratamento: antissépticos tópicos (lavagem pós-cobertura).`},{id:`andro-216`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Habilidade de monta`,dificuldade:`facil`,enunciado:`A avaliação da habilidade de monta em garanhões inclui:`,alternativas:[`Capacidade de realizar ereção adequada, monta, penetração vaginal e ejaculação completa, sem defeitos de posicionamento.`,`Apenas ereção.`,`Apenas ejaculação.`,`Apenas motilidade espermática.`,`Apenas libido.`],resposta_correta:`A`,explicacao:`Habilidade de monta: ereção (tumescência adequada), monta (elevação anterior, posicionamento), penetração (introdução na vagina artificial/égua), ejaculação (espasmo de cópula, flagelação caudal), desmonta. Defeitos: falha de ereção, monta inadequada, ejaculação retrógrada.`},{id:`andro-217`,banca:`UFBA`,ano:2020,prova:`UFBA — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Sêmen equino — gel`,dificuldade:`medio`,enunciado:`O gel (coágulo) no ejaculado equino é:`,alternativas:[`Produzido pelas vesículas seminais, forma um coágulo branco-acinzentado que é normalmente retido pelo filtro da vagina artificial.`,`Produzido pelo testículo.`,`Produzido pela próstata.`,`Um sinal de infecção.`,`Produzido pelas glândulas bulbouretrais.`],resposta_correta:`A`,explicacao:`O gel equino é produzido pelas vesículas seminais (contribuições de proteínas coagulantes). É normal e compõe ~30-50% do volume ejaculado. O gel é retido pelo filtro da vagina artificial e geralmente descartado (pode causar contaminação bacteriana e reduzir viabilidade espermática).`},{id:`andro-218`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Ejaculação retrógrada`,dificuldade:`dificil`,enunciado:`A ejaculação retrógrada em garanhões é:`,alternativas:[`Passagem do sêmen para a bexiga urinária em vez da uretra peniana, resultando em ausência de espermatozoides no ejaculado anterógrado.`,`Ejaculação para dentro do prepúcio.`,`Ausência de ejaculação.`,`Ejaculação dolorosa.`,`Ejaculação com sangue.`],resposta_correta:`A`,explicacao:`A ejaculação retrógrada ocorre quando o esfíncter uretral interno não relaxa adequadamente, e o sêmen é direcionado para a bexiga. Causas: neuropatia, medicamentos (alfabloqueadores), defeitos anatômicos. Diagnóstico: cistocentese pós-ejaculação (espermatozoides na urina).`},{id:`andro-219`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Desempenho reprodutivo de garanhões`,dificuldade:`medio`,enunciado:`O número de éguas que um garanhão pode cobrir em uma estação reprodutiva depende de:`,alternativas:[`Idade, condição física, método de cobertura (monta natural vs. IA), qualidade do sêmen e manejo.`,`Apenas da idade do garanhão.`,`Apenas da quantidade de sêmen produzido.`,`Do peso corporal.`,`Não existe limite.`],resposta_correta:`A`,explicacao:`Coberturas por estação: monta natural 40-60 éguas, IA com sêmen fresco/refrigerado 100-200 éguas, IA com sêmen congelado 200-300+. Fatores: idade (jovens menos, adultos mais), frequência de coleta (máx 2-3 coletas/dia), condição física, sazonalidade.`},{id:`andro-220`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário Prefeitura 2022`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Lavagem pós-cobertura`,dificuldade:`medio`,enunciado:`A lavagem genital pós-cobertura (post-breeding lavage) em éguas é:`,alternativas:[`Uma prática que reduz a contaminação bacteriana do útero após o coito, usando solução salina morna ou lactato de Ringer.`,`Uma técnica de inseminação artificial.`,`Uma avaliação da fertilidade da égua.`,`Uma técnica de coleta de sêmen.`,`Não é uma prática recomendada.`],resposta_correta:`A`,explicacao:`A lavagem uterina pós-cobertura (2-4h após) remove excesso de sêmen, bactérias e debris do útero, reduzindo o risco de endometrite. Solução: salina morna ou lactato de Ringer (1-2L). Especialmente útil em éguas com histórico de endometrite.`},{id:`andro-221`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Klebsiella pneumoniae`,dificuldade:`medio`,enunciado:`Klebsiella pneumoniae em garanhões:`,alternativas:[`Pode colonizar o pênis e prepúcio, sendo transmitida durante o coito e causando endometrite em éguas.`,`Causa pneumonia em garanhões.`,`Não tem relevância reprodutiva.`,`Causa apenas infecção urinária.`,`É transmitida apenas por fômites.`],resposta_correta:`A`,explicacao:`Klebsiella pneumoniae (capsulada) coloniza pênis/prepúcio de garanhões (portadores assintomáticos). Transmissão venérea → endometrite em éguas. Diagnóstico: cultura de swab genital. Alguns garanhões são portadores crônicos e devem ser tratados (lavagens antissépticas).`},{id:`andro-222`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso Veterinário 2022`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Pseudomonas aeruginosa`,dificuldade:`medio`,enunciado:`Pseudomonas aeruginosa em garanhões:`,alternativas:[`Pode colonizar o trato genital, causar endometrite em éguas e resistir a múltiplos antibióticos, sendo um problema em rebanhos equinos.`,`Causa apenas infecção de pele.`,`Não tem relevância reprodutiva.`,`É transmitida apenas por aerossóis.`,`Causa infecção apenas em éguas castradas.`],resposta_correta:`A`,explicacao:`Pseudomonas aeruginosa é resistente a múltiplos antibióticos e coloniza o trato genital de garanhões e éguas. Causa endometrite, cervicite, infertilidade. Tratamento: antissépticos (clorhexidina, iodopovidona) para lavagem genital. Cultura/antibiograma é essencial.`},{id:`andro-223`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_equina`,subtopico:`Sêmen equino — parâmetros`,dificuldade:`facil`,enunciado:`Os parâmetros de referência do sêmen equino fresco são:`,alternativas:[`Motilidade ≥60%, concentração ≥100 milhões/mL, volume 50-150 mL e morfologia normal ≥60%.`,`Motilidade ≥30%, concentração ≥10 milhões/mL.`,`Motilidade ≥90%, concentração ≥1 bilhão/mL.`,`Motilidade ≥10%, concentração ≥1 milhão/mL.`,`Não existem parâmetros de referência.`],resposta_correta:`A`,explicacao:`Sêmen equino fresco: motilidade total ≥60-70%, progressiva ≥40%, concentração ≥100-350 milhões/mL, volume 50-150 mL, morfologia normal ≥60%, vitalidade ≥60%. Valores abaixo sugerem disfunção reprodutiva.`},{id:`andro-224`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Exame andrológico em cães`,dificuldade:`medio`,enunciado:`O exame andrológico em cães inclui:`,alternativas:[`Anamnese, exame clínico, avaliação genital externa (testículos, epidídimo, pênis, prepúcio), exame genital interno (próstata por palpação retal) e avaliação seminal.`,`Apenas avaliação do sêmen.`,`Apenas palpação testicular.`,`Apenas exame de sangue.`,`Apenas ultrassonografia prostática.`],resposta_correta:`A`,explicacao:`Exame andrológico canino: anamnese (idade, raça, histórico), exame clínico geral, genital externo (testículos, epidídimo, escroto, pênis, prepúcio), genital interno (próstata por palpação retal), avaliação seminal (coleta por massagem peniana ou artificial), ultrassonografia.`},{id:`andro-225`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Coleta de sêmen em cães`,dificuldade:`medio`,enunciado:`A coleta de sêmen em cães é realizada por:`,alternativas:[`Massagem digital do pênis (pressão no bulbo do pênis), com coleta da fração espermática em tubo ou recipiente estéril.`,`Vagina artificial.`,`Eletroejaculação retal.`,`Aspiração do epidídimo.`,`Punção testicular.`],resposta_correta:`A`,explicacao:`Coleta canina: massagem digital do pênis (cão em estação ou decúbito lateral). Pressão rítmica no bulbo do pênis (massagem uretral) → ejaculação. O ejaculado canino tem 3 frações: pre-espermática (clara, descartada), espermática (leitosa, coletada), prostática (clara, descartada).`},{id:`andro-226`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Puberdade em cães`,dificuldade:`facil`,enunciado:`A puberdade em cães machos ocorre, em média, aos:`,alternativas:[`6-12 meses, variando com a raça (raças pequenas mais precoces, raças gigantes mais tardias).`,`3 meses.`,`24-36 meses.`,`Apenas aos 2 anos.`,`Não depende da raça.`],resposta_correta:`A`,explicacao:`Puberdade canina: 6-12 meses (raças pequenas 6-8 meses, médias 8-10, grandes 10-12, gigantes 12-18). A maturidade sexual completa ocorre aos 12-24 meses. A fertilidade é atingida antes da maturidade esquelética.`},{id:`andro-227`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Castração em cães`,dificuldade:`facil`,enunciado:`A castração (orquiectomia) em cães é indicada para:`,alternativas:[`Controle reprodutivo, prevenção de neoplasia testicular, redução de hiperplasia prostática, controle comportamental e tratamento de criptorquidia.`,`Apenas controle de natalidade.`,`Apenas para tratar infecções.`,`Apenas para melhorar o pelo.`,`Não é recomendada.`],resposta_correta:`A`,explicacao:`Indicações de castração: controle reprodutivo, prevenção de neoplasia testicular (criptorquidia), redução de HPB e prostatite, controle de comportamento sexual indesejado, redução de marcação territorial, prevenção de hérnia perineal.`},{id:`andro-228`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`andrologia_canina`,subtopico:`Sêmen canino`,dificuldade:`medio`,enunciado:`O sêmen canino fresco apresenta os seguintes parâmetros de referência:`,alternativas:[`Volume 2-30 mL, concentração 200-600 milhões/mL, motilidade ≥70%, morfologia normal ≥80%.`,`Volume 50-100 mL, concentração 10 milhões/mL.`,`Volume 100-200 mL, concentração 1 bilhão/mL.`,`Volume 0,1-0,5 mL, concentração 100 milhões/mL.`,`Não existem parâmetros de referência.`],resposta_correta:`A`,explicacao:`Sêmen canino: volume 2-30 mL (raças grandes > pequenas), concentração 200-600 milhões/mL, motilidade ≥70%, morfologia normal ≥80%, vitalidade ≥70%. O ejaculado tem 3 frações: pre-espermática (~0,5-2 mL), espermática (~1-5 mL), prostática (~5-25 mL).`},{id:`andro-229`,banca:`CRMV`,ano:2023,prova:`CRMV-SP — Prova de Suficiência 2023`,tipo:`crmv`,topico:`andrologia_canina`,subtopico:`Osso peniano (baculum)`,dificuldade:`facil`,enunciado:`O osso peniano (baculum) em cães:`,alternativas:[`É uma estrutura óssea presente no pênis canino que auxilia na ereção e penetração, não sendo encontrada em bovinos ou equinos.`,`É uma estrutura exclusiva de felinos.`,`Não tem função reprodutiva.`,`É encontrado em todas as espécies domésticas.`,`É uma anomalia congênita.`],resposta_correta:`A`,explicacao:`O baculum (osso peniano) é uma estrutura óssea presente no pênis de cães, gatos, ursos, mustelídeos e outros carnívoros. Auxilia na ereção e penetração (especialmente em ereção incompleta). Não está presente em bovinos, equinos, suínos ou pequenos ruminantes.`},{id:`andro-230`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso Professor 2021`,tipo:`pos`,topico:`andrologia_canina`,subtopico:`Tie (vínculo copulatório)`,dificuldade:`medio`,enunciado:`O tie (vínculo copulatório) em cães é:`,alternativas:[`A permanência dos cães acasalados por 5-45 minutos, devido à tumescência do bulbo do pênis e contração do esfíncter vaginal da fêmea.`,`Um sinal de infertilidade.`,`A ejaculação retrógrada.`,`Uma patologia genital.`,`O período de gestação.`],resposta_correta:`A`,explicacao:`O tie (lock) ocorre após a ejaculação: o bulbo do pênis (glans) se tumesce (ereção completa), e o esfíncter vaginal da fêmea contrai, mantendo os cães unidos por 5-45 minutos. Duração média 15-20 min. O tie não é obrigatório para fertilidade, mas é considerado normal.`},{id:`andro-231`,banca:`UNESP`,ano:2022,prova:`UNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Hiperplasia prostática benigna canina`,dificuldade:`medio`,enunciado:`A hiperplasia prostática benigna (HPB) em cães:`,alternativas:[`Ocorre em quase 100% dos cães inteiros com >5 anos de idade, é causada por estímulo androgênico e o tratamento de escolha é a castração.`,`Ocorre apenas em cães castrados.`,`Não tem tratamento.`,`É causada por infecção bacteriana.`,`Ocorre apenas em cães jovens.`],resposta_correta:`A`,explicacao:`A HPB é a condição prostática mais comum em cães inteiros >5 anos (quase 100% de incidência). Causa: conversão de testesterona em DHT (5-alfa-redutase) → hiperplasia glandular. Sinais: tenesmo, constipação, hematúria, disúria. Tratamento: castração (efetivo) ou finasterida.`},{id:`andro-232`,banca:`USP`,ano:2020,prova:`USP — Mestrado em Reprodução 2020`,tipo:`pos`,topico:`andrologia_canina`,subtopico:`Frações ejaculatórias caninas`,dificuldade:`medio`,enunciado:`O ejaculado canino é composto por três frações:`,alternativas:[`Pre-espermática (uretrais/bulbouretrais, clara), espermática (epididimária/prostática, leitosa) e prostática (clara, volumosa).`,`Apenas uma fração.`,`Duas frações: espermática e urinária.`,`Quatro frações iguais.`,`Cinco frações.`],resposta_correta:`A`,explicacao:`Frações ejaculatórias caninas: 1) Pre-espermática (~0,5-2 mL, clara, uretral/bulbouretral), 2) Espermática (~1-5 mL, leitosa, epididimária + prostática — contém espermatozoides), 3) Prostática (~5-25 mL, clara, volumosa, da próstata).`},{id:`andro-233`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Brucella canis`,dificuldade:`medio`,enunciado:`A Brucella canis em cães:`,alternativas:[`Causa orquiepididimite, infertilidade, aborto e é uma zoonota. A transmissão ocorre por contato com secreções genitais, urina e sangue.`,`Causa apenas doença respiratória.`,`Não é uma zoonota.`,`Causa apenas diarreia.`,`Não afeta o sistema reprodutivo.`],resposta_correta:`A`,explicacao:`Brucella canis causa: machos — orquiepididimite, prostatite, infertilidade. Fêmeas — aborto (45-55 dias), infertilidade. É zoonota (rara em humanos). Transmissão: venérea, contato com secreções, vertical. Diagnóstico: RSAT, ELISA, IFA. Não há tratamento eficaz; eutanásia é recomendada.`},{id:`andro-234`,banca:`MAPA`,ano:2020,prova:`MAPA — Fiscal Federal Agropecuário 2020`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Criptorquidia canina`,dificuldade:`medio`,enunciado:`A criptorquidia em cães:`,alternativas:[`É uma anomalia hereditária (autossômica recessiva) em que um ou ambos os testículos não descem ao escroto, aumentando o risco de neoplasia.`,`É uma condição adquirida por trauma.`,`Não tem componente genético.`,`É tratável com hormônios.`,`Não afeta a fertilidade.`],resposta_correta:`A`,explicacao:`A criptorquidia canina é hereditária (autossômica recessiva, poligênica). O testículo retido (abdominal/inguinal) tem temperatura corporal → degeneração → infertilidade e risco 10-13x de neoplasia (seminoma, tumor de Sertoli). Tratamento: orquiectomia bilateral. Não deve ser usado para reprodução.`},{id:`andro-235`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Período de maturação espermática canina`,dificuldade:`medio`,enunciado:`A maturação dos espermatozoides no epidídimo canino dura aproximadamente:`,alternativas:[`8-12 dias, durante os quais os espermatozoides adquirem motilidade e capacidade fertilizante.`,`1-2 dias.`,`30-60 dias.`,`Não há maturação epididimária.`,`A maturação ocorre apenas na ejaculação.`],resposta_correta:`A`,explicacao:`A maturação epididimária em cães dura ~8-12 dias. Os espermatozoides adquirem: motilidade progressiva, capacidade de ligação à zona pelúcida, estabilidade de membrana e capacidade fertilizante. O trânsito é contínuo, com armazenamento na cauda do epidídimo.`},{id:`andro-236`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso Veterinário 2022`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Massagem peniana para coleta`,dificuldade:`facil`,enunciado:`A técnica de coleta de sêmen canino por massagem peniana envolve:`,alternativas:[`Retração do prepúcio, massagem digital do pênis (pressão no bulbo) e coleta da fração espermática em tubo estéril.`,`Eletroejaculação retal.`,`Punção testicular.`,`Aspiração do epidídimo.`,`Vagina artificial.`],resposta_correta:`A`,explicacao:`Técnica: 1) Cão em estação ou decúbito lateral, 2) Retração do prepúcio, 3) Exposição da glande, 4) Massagem digital do pênis (pressão rítmica no bulbo), 5) Coleta da fração espermática (leitosa) em tubo estéril, descartando as frações prostática e pré-espermática.`},{id:`andro-237`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Exame prostático canino`,dificuldade:`medio`,enunciado:`A avaliação da próstata canina inclui:`,alternativas:[`Palpação retal (tamanho, simetria, dor), ultrassonografia (tamanho, ecotextura, cistos, abscessos) e citologia prostática.`,`Apenas exame de sangue.`,`Apenas radiografia.`,`Apenas palpação abdominal.`,`Não é possível avaliar a próstata em cães.`],resposta_correta:`A`,explicacao:`Avaliação prostática: 1) Palpação retal (tamanho, simetria, dor, consistência), 2) Ultrassom (tamanho normal 1-3 cm, ecotextura, cistos, massas, abscessos), 3) Citologia (aspirado/agulha fina ou ejaculado), 4) Cultura, 5) Dosagem de PSA (em cães).`},{id:`andro-238`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Fator de crescimento epididimário`,dificuldade:`dificil`,enunciado:`A proteína fertilina (ADAM) na membrana espermática canina:`,alternativas:[`É uma proteína de membrana que participa da ligação espermatozoide-zona pelúcida e é adquirida durante a maturação epididimária.`,`É produzida pela próstata.`,`É um hormônio produzido pelo hipotálamo.`,`É uma enzima do acrossomo.`,`É um componente do plasma seminal.`],resposta_correta:`A`,explicacao:`A fertilina (ADAM 1/ADAM 2) é uma proteína de membrana espermática que medeia a ligação à zona pelúcida. É adquirida/modificada durante a maturação epididimária. Outras proteínas epididimárias: DE (defensive epididymal), CE (clusterin epididymal).`},{id:`andro-239`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário IBAMA 2023`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Cistos prostáticos caninos`,dificuldade:`medio`,enunciado:`Os cistos prostáticos (cistos de retenção) em cães são:`,alternativas:[`Comuns em cães com HPB, diagnosticados por ultrassonografia (áreas anecoicas), podendo causar disúria e tenesmo.`,`Sempre malignos.`,`Exclusivos de cães castrados.`,`Não causam sintomas.`,`Tratados apenas com antibióticos.`],resposta_correta:`A`,explicacao:`Cistos prostáticos (intra ou paraprostáticos) são comuns em cães com HPB. Diagnóstico: ultrassom (áreas anecoicas). Sinais: tenesmo, disúria, hematúria. Tratamento: drenagem guiada por ultrassom, marsupialização, omentalização, castração.`},{id:`andro-240`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Volume testicular canino`,dificuldade:`facil`,enunciado:`A avaliação do volume testicular em cães é feita por:`,alternativas:[`Orquidômetro (comparação com esferas de volumes conhecidos) ou ultrassonografia (fórmula elipsoidal).`,`Apenas palpação.`,`Radiografia.`,`TC (tomografia computadorizada).`,`Não é possível medir o volume testicular.`],resposta_correta:`A`,explicacao:`O volume testicular em cães é avaliado por: orquidômetro de Prader (esferas de diferentes volumes para comparação), ultrassonografia (fórmula: L × A × P × 0,523), ou deslocamento de água. Volume normal varia com a raça (10-30 mL por testículo em raças médias).`},{id:`andro-241`,banca:`UFPR`,ano:2021,prova:`UFPR — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Tempo de maturidade sexual canina`,dificuldade:`facil`,enunciado:`A maturidade sexual completa em cães machos (produção espermática máxima) ocorre aos:`,alternativas:[`12-24 meses, dependendo da raça.`,`3 meses.`,`6 meses.`,`48 meses.`,`A maturidade sexual não depende da idade.`],resposta_correta:`A`,explicacao:`A maturidade sexual completa (produção espermática máxima, libido adulta) ocorre aos 12-24 meses. A puberdade (primeira ejaculação com espermatozoides) ocorre mais cedo (6-12 meses). Raças pequenas amadurecem mais cedo que gigantes.`},{id:`andro-242`,banca:`UFRGS`,ano:2021,prova:`UFRGS — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_canina`,subtopico:`Tumor venéreo transmissível canino`,dificuldade:`medio`,enunciado:`O tumor venéreo transmissível (TVT) em cães:`,alternativas:[`É uma neoplasia transmitida por contato sexual, que acomete genitália (pênis, prepúcio, vagina), tratada com vimblastina.`,`É uma infecção bacteriana.`,`Não é transmissível.`,`Apenas acomete fêmeas.`,`Não tem tratamento.`],resposta_correta:`A`,explicacao:`O TVT (tumor de Sticker) é uma neoplasia transmissível por transferência de células neoplásicas durante o coito. Acomete genitália (pênis, prepúcio, vagina, vulva). Massas friáveis, hemorrágicas. Tratamento: vimblastina (quimioterápico) com >90% de cura.`},{id:`andro-243`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Exame andrológico em suínos`,dificuldade:`medio`,enunciado:`O exame andrológico em suínos reprodutores inclui:`,alternativas:[`Avaliação de libido, exame genital externo (testículos, prepúcio, pênis), coleta e avaliação do sêmen, e exames complementares.`,`Apenas avaliação do sêmen.`,`Apenas exame de sangue.`,`Apenas palpação retal.`,`Não é possível realizar exame andrológico em suínos.`],resposta_correta:`A`,explicacao:`Exame andrológico suíno: 1) Comportamento sexual (libido, monta), 2) Genital externo (testículos, prepúcio, pênis), 3) Genital interno (palpação retal: vesículas seminais, próstata), 4) Avaliação seminal (coleta por mão engatada), 5) Ultrassonografia escrotal.`},{id:`andro-244`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Coleta em suínos`,dificuldade:`medio`,enunciado:`A coleta de sêmen em suínos reprodutores é realizada:`,alternativas:[`Pela técnica de mão engatada (gloved hand), com pressão sobre o espiral do pênis, simulando a contração do cérvix da fêmea.`,`Por vagina artificial.`,`Por eletroejaculação.`,`Por aspiração testicular.`,`Por massagem retal.`],resposta_correta:`A`,explicacao:`A coleta suína usa a técnica de mão engatada: o operador (com luva) segura o pênis (espiralado) à medida que o javali monta a fêmea/fantasma, aplicando pressão rítmica no espiral → ejaculação. O sêmen é coletado em frasco com filtro para reter o gel.`},{id:`andro-245`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Sêmen suíno`,dificuldade:`medio`,enunciado:`O sêmen suíno apresenta as seguintes características:`,alternativas:[`Volume 150-300 mL, concentração 200-400 milhões/mL, motilidade ≥70%, gel (coágulo) produzido pelas vesículas seminais.`,`Volume 5-10 mL, concentração 1 bilhão/mL.`,`Volume 50 mL, sem gel.`,`Volume 1-5 mL, concentração 100 milhões/mL.`,`Não produz gel.`],resposta_correta:`A`,explicacao:`Sêmen suíno: volume 150-300 mL (um dos maiores), concentração 200-400 milhões/mL, total 20-60 bilhões, motilidade ≥70%, morfologia normal ≥70%. O gel (coágulo) é produzido pelas vesículas seminais e retido pelo filtro da coleta.`},{id:`andro-246`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`IA em suínos`,dificuldade:`medio`,enunciado:`A inseminação artificial em suínos é realizada:`,alternativas:[`Com cateter intracervical, depositando 2-3 bilhões de espermatozoides em 80-100 mL de diluente, durante o estro.`,`Com cateter intrauterino, depositando 1 milhão de espermatozoides.`,`Por via laparoscópica.`,`Apenas com sêmen congelado.`,`Por via vaginal simples.`],resposta_correta:`A`,explicacao:`IA em suínos: cateter intracervical (a cérvix suína é espiralada, o cateter se ancla nos divertículos cervicais). Dose: 2-3 bilhões de espermatozoides em 80-100 mL. Sêmen refrigerado a 15-20°C. Duas inseminações por estro (intervalo 12-24h).`},{id:`andro-247`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Prova de Título em Reprodução Animal 2020`,tipo:`pos`,topico:`andrologia_suina`,subtopico:`Puberdade em suínos`,dificuldade:`facil`,enunciado:`A puberdade em suínos machos ocorre, em média, aos:`,alternativas:[`5-7 meses, variando com a genética, nutrição e ambiente.`,`2-3 meses.`,`12-18 meses.`,`Apenas aos 2 anos.`,`Não depende de fatores ambientais.`],resposta_correta:`A`,explicacao:`A puberdade em suínos machos: 5-7 meses. A maturidade sexual completa ocorre por volta dos 8-10 meses. Fatores: genética (linhagens melhoradas mais precoces), nutrição (adequada), ambiente (espaço, socialização).`},{id:`andro-248`,banca:`CRMV`,ano:2022,prova:`CRMV-PR — Prova de Suficiência 2022`,tipo:`crmv`,topico:`andrologia_suina`,subtopico:`Pênis suíno`,dificuldade:`facil`,enunciado:`O pênis do suino é classificado como:`,alternativas:[`Fibroelástico com flexura sigmoide, semelhante ao bovino.`,`Musculocavernoso, semelhante ao equino.`,`Com osso peniano (baculum).`,`Sem flexura sigmoide.`,`Retrátil permanentemente.`],resposta_correta:`A`,explicacao:`O pênis suíno é fibroelástico com flexura sigmoide (semelhante ao bovino, ovino e caprino). A ereção envolve deslocamento da flexura sigmoide. O pênis suíno termina em espiral (processo espiralado).`},{id:`andro-249`,banca:`UFMG`,ano:2020,prova:`UFMG — Professor Assistente 2020`,tipo:`pos`,topico:`andrologia_suina`,subtopico:`Diluentes para sêmen suíno`,dificuldade:`medio`,enunciado:`Os diluentes para sêmen suíno refrigerado (15-20°C) incluem:`,alternativas:[`BTS (Beltsville Thawing Solution), Androhep, X-Cell, Merck III, que contêm glicose, EDTA, citrato de sódio e antibióticos.`,`Apenas soro fisiológico.`,`Apenas leite desnatado.`,`Apenas Tris-gema-glicerol.`,`Não existe diluente para sêmen suíno.`],resposta_correta:`A`,explicacao:`Diluentes suínos para refrigeração (15-20°C): BTS (até 3 dias), Androhep (até 5 dias), X-Cell (até 5 dias), Merck III (até 5 dias). Contêm: glicose, EDTA (quelante), citrato de sódio (tampão), bicarbonato, antibióticos. Não contêm glicerol (usado apenas em congelamento).`},{id:`andro-250`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Volume ejaculado suíno`,dificuldade:`facil`,enunciado:`O volume ejaculado dos suínos é o maior entre os domésticos, sendo:`,alternativas:[`150-300 mL, com contribuição volumosa das vesículas seminais.`,`5-10 mL.`,`50-100 mL.`,`1-2 mL.`,`500-1000 mL.`],resposta_correta:`A`,explicacao:`O ejaculado suíno é volumoso (150-300 mL) devido à contribuição das vesículas seminais (que são grandes em suínos). O gel contribui ~15-30% do volume. O volume total sem gel é ~100-200 mL. A ejaculação dura 5-20 minutos (longa).`},{id:`andro-251`,banca:`USP`,ano:2022,prova:`USP — Mestrado em Reprodução 2022`,tipo:`pos`,topico:`andrologia_suina`,subtopico:`Espirais do pênis suíno`,dificuldade:`medio`,enunciado:`O processo espiralado do pênis suíno:`,alternativas:[`Encaixa-se nos divertículos cervicais durante a cópula, facilitando a deposição seminal no cérvix.`,`Produz testosterona.`,`Armazena espermatozoides.`,`Secreta líquido seminal.`,`É uma anomalia congênita.`],resposta_correta:`A`,explicacao:`O pênis suíno termina em processo espiralado (filum) que se encaixa nos divertículos cervicais durante a cópula, criando um selo que facilita a deposição de sêmen no cérvix. A ejaculação suína é longa (5-20 min), o que é normal.`},{id:`andro-252`,banca:`UFRRJ`,ano:2020,prova:`UFRRJ — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Frequência de coleta em suínos`,dificuldade:`medio`,enunciado:`A frequência de coleta de sêmen recomendada para javais reprodutores é:`,alternativas:[`2-3 vezes por semana, com intervalo mínimo de 48 horas entre coletas para manter a qualidade seminal.`,`Diariamente.`,`Uma vez por mês.`,`Uma vez por ano.`,`Não existe frequência recomendada.`],resposta_correta:`A`,explicacao:`Frequência de coleta em javais: 2-3x/semana (intervalo mínimo de 48h). Coletas muito frequentes reduzem concentração e volume. Coletas muito raras podem causar acúmulo de espermatozoides degenerados no epidídimo. Jovens: 1-2x/semana.`},{id:`andro-253`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Federal Agropecuário 2023`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Leptospirose suína`,dificuldade:`medio`,enunciado:`A leptospirose em suínos:`,alternativas:[`Pode causar infertilidade, aborto e morte neonatal, com Leptospira pomona e L. bratislava como sorovares mais comuns em suínos.`,`Não afeta o sistema reprodutivo.`,`Causa apenas doença respiratória.`,`Causa apenas diarreia.`,`Não é zoonota.`],resposta_correta:`A`,explicacao:`A leptospirose suína (L. pomona, L. bratislava, L. icterohaemorrhagiae) causa: aborto, natimortalidade, nascimento de leitões fracos, infertilidade, febre, icterícia. Zoonose. Diagnóstico: MAT (sorologia). Tratamento: estreptomicina. Prevenção: vacinação + manejo sanitário.`},{id:`andro-254`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso Veterinário 2022`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Perímetro escrotal suíno`,dificuldade:`facil`,enunciado:`O perímetro escrotal mínimo para aprovação de javais adultos no exame andrológico é:`,alternativas:[`28 cm.`,`15 cm.`,`40 cm.`,`50 cm.`,`20 cm.`],resposta_correta:`A`,explicacao:`Perímetro escrotal mínimo para javais adultos: ≥28 cm. Para javais jovens (8-10 meses): ≥24 cm. O perímetro escrotal é proporcional à massa testicular e produção espermática. Valores abaixo sugerem hipoplasia ou degeneração testicular.`},{id:`andro-255`,banca:`UFBA`,ano:2021,prova:`UFBA — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Relação macho:fêmea em suínos`,dificuldade:`facil`,enunciado:`A relação javal:porca para monta natural em suínos é:`,alternativas:[`1:8 a 1:12.`,`1:1.`,`1:50.`,`1:100.`,`Não existe relação recomendada.`],resposta_correta:`A`,explicacao:`Para monta natural em suínos: 1 javal para 8-12 porcas. Para IA, um javal pode atender 50-100+ porcas (dependendo da frequência de coleta). A relação é menor que em bovinos devido à ejaculação mais longa e maior demanda de monta.`},{id:`andro-256`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Sêmen suíno — refrigeração`,dificuldade:`medio`,enunciado:`O sêmen suíno para IA é preferencialmente armazenado:`,alternativas:[`Refrigerado a 15-20°C por 3-5 dias, sem congelamento, devido à maior sensibilidade dos espermatozoides suínos ao congelamento.`,`Congelado a -196°C.`,`Em temperatura ambiente.`,`A 37°C.`,`Não pode ser armazenado.`],resposta_correta:`A`,explicacao:`O sêmen suíno é mais sensível ao congelamento que o bovino. Por isso, a maioria das IAs em suínos usa sêmen refrigerado a 15-20°C (não 5°C, que causa choque térmico). Armazenamento por 3-5 dias. O congelamento é possível mas com menor taxa de prenhez.`},{id:`andro-257`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Vesículas seminais suínas`,dificuldade:`medio`,enunciado:`As vesículas seminais em suínos são:`,alternativas:[`Grandes e lobuladas, responsáveis pela produção do gel e pela maior parte do volume ejaculado.`,`Ausentes em suínos.`,`Pequenas e rudimentares.`,`Responsáveis pela produção de testosterona.`,`Localizadas no interior do testículo.`],resposta_correta:`A`,explicacao:`As vesículas seminais suínas são grandes, lobuladas e muito desenvolvidas. Produzem a maior parte do plasma seminal (volume ejaculado elevado, 150-300 mL) e o gel (proteínas coagulantes). São sensíveis à testosterona e sua função é comprometida por hipogonadismo.`},{id:`andro-258`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário Prefeitura 2020`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Ejaculação suína`,dificuldade:`medio`,enunciado:`A ejaculação em suínos é caracterizada por:`,alternativas:[`Duração longa (5-20 minutos), com emissão de frações em sequência, incluindo gel no início e fim.`,`Duração muito curta (menos de 1 minuto).`,`Ausência de gel.`,`Ejaculação retrógrada.`,`Não ocorre ejaculação em suínos.`],resposta_correta:`A`,explicacao:`A ejaculação suína é longa (5-20 min). O ejaculado é emitido em frações: gel inicial (vesículas seminais), fração espermática (epidídimo + próstata + vesículas), gel final. A longa duração é normal e reflete a anatomia do pênis espiralado e o encaixe cervical.`},{id:`andro-259`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Controle de DSTs em suínos`,dificuldade:`medio`,enunciado:`As principais doenças reprodutivas em javais reprodutores incluem:`,alternativas:[`Leptospirose, PRRS (síndrome reprodutiva e respiratória suína), parvovirose suína e brucelose suína.`,`Apenas influenza suína.`,`Apenas pneumonia.`,`Apenas diarreia.`,`Apenas erisipela.`],resposta_correta:`A`,explicacao:`Doenças reprodutivas suínas: PRRS (vírus), parvovirose suína (PPV), leptospirose (Leptospira), brucelose (Brucella suis), Aujeszky (PRV), influenza suína. Controle: vacinação, quarentena, biossegurança, exames periódicos.`},{id:`andro-260`,banca:`UFRGS`,ano:2020,prova:`UFRGS — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_suina`,subtopico:`Mão engatada`,dificuldade:`facil`,enunciado:`A técnica de mão engatada (gloved hand) para coleta de sêmen suíno utiliza:`,alternativas:[`Luva de plástico descartável no braço do operador, que segura o pênis espiralado do javali durante a monta.`,`Vagina artificial.`,`Eletrodo retal.`,`Cateter uretral.`,`Seringa de aspiração.`],resposta_correta:`A`,explicacao:`A técnica de mão engatada: operador veste luva de plástico no braço, posiciona-se ao lado do javali durante a monta do fantasma, segura o pênis espiralado com a mão, aplicando pressão rítmica que simula o cérvix. O sêmen é coletado em frasco com filtro.`},{id:`andro-261`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Exame andrológico em ovinos`,dificuldade:`medio`,enunciado:`O exame andrológico em carneiros inclui:`,alternativas:[`Avaliação de libido, exame genital externo (testículos, epidídimo, escroto), coleta e avaliação do sêmen e exames complementares.`,`Apenas avaliação do sêmen.`,`Apenas exame de sangue.`,`Apenas palpação retal.`,`Não é possível realizar exame andrológico em ovinos.`],resposta_correta:`A`,explicacao:`Exame andrológico ovino: 1) Libido (tempo de reação, monta), 2) Genital externo (testículos, epidídimo, escroto, prepúcio), 3) Genital interno (palpação retal: vesículas seminais, próstata), 4) Avaliação seminal (coleta por vagina artificial ou eletroejaculação), 5) Sorologias.`},{id:`andro-262`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Coleta em ovinos`,dificuldade:`medio`,enunciado:`A coleta de sêmen em carneiros pode ser realizada por:`,alternativas:[`Vagina artificial com fêmea em estro ou eletroejaculação retal.`,`Apenas por vagina artificial.`,`Apenas por eletroejaculação.`,`Por punção testicular.`,`Por aspiração epididimária.`],resposta_correta:`A`,explicacao:`Coleta ovina: vagina artificial (carneiro monta fêmea/ovelha fantasma) ou eletroejaculação retal (quando não há cooperação para monta). A vagina artificial é preferida por produzir ejaculado mais natural e com melhor qualidade.`},{id:`andro-263`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Sêmen ovino`,dificuldade:`medio`,enunciado:`O sêmen ovino apresenta os seguintes parâmetros de referência:`,alternativas:[`Volume 0,8-2 mL, concentração 2-4 bilhões/mL, motilidade ≥70%, morfologia normal ≥80%.`,`Volume 50-100 mL, concentração 100 milhões/mL.`,`Volume 10-20 mL, concentração 500 milhões/mL.`,`Volume 0,1-0,5 mL, concentração 50 milhões/mL.`,`Não existem parâmetros de referência.`],resposta_correta:`A`,explicacao:`Sêmen ovino: volume 0,8-2 mL (pequeno), concentração 2-4 bilhões/mL (muito alta), motilidade ≥70%, morfologia normal ≥80%, vitalidade ≥70%. O sêmen ovino é concentrado e volumoso pequeno.`},{id:`andro-264`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Efeito fotoperíodo em ovinos`,dificuldade:`medio`,enunciado:`O efeito do fotoperíodo sobre a reprodução dos carneiros é:`,alternativas:[`Carneiros são animais de dias curtos (short-day breeders), com aumento da libido e da espermatogênese no outono/inverno (fotoperíodo curto).`,`O fotoperíodo não afeta a reprodução ovina.`,`Carneiros são animais de dias longos.`,`O efeito é apenas sobre as fêmeas.`,`O fotoperíodo afeta apenas caprinos.`],resposta_correta:`A`,explicacao:`Carneiros são reprodutores de dias curtos: a melatonina (noite longa) estimula a secreção de GnRH → aumento de LH/FSH/testosterona → maior libido e espermatogênese no outono/inverno. Na primavera/verão (dias longos), há redução da atividade sexual (anestro sazonal).`},{id:`andro-265`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`andrologia_ovina_caprina`,subtopico:`Brucella ovis`,dificuldade:`medio`,enunciado:`A Brucella ovis em carneiros causa:`,alternativas:[`Epididimite crônica, orquite, infertilidade e é a principal causa de epididimite infecciosa em ovinos.`,`Apenas doença respiratória.`,`Apenas diarreia.`,`Apenas aborto em fêmeas.`,`Não causa doença reprodutiva.`],resposta_correta:`A`,explicacao:`B. ovis causa epididimite crônica granulomatosa em carneiros → obstrução do ducto epididimário → azoospermia obstrutiva → infertilidade. Pode causar orquite. O carneiro é portador crônico. Diagnóstico: sorologia (ELISA, fixação de complemento), cultura seminal.`},{id:`andro-266`,banca:`CRMV`,ano:2021,prova:`CRMV-SP — Prova de Suficiência 2021`,tipo:`crmv`,topico:`andrologia_ovina_caprina`,subtopico:`Exame andrológico em caprinos`,dificuldade:`medio`,enunciado:`O exame andrológico em bodes inclui:`,alternativas:[`Avaliação de libido, exame genital externo (testículos, epidídimo, pênis), coleta por vagina artificial ou eletroejaculação, e avaliação seminal.`,`Apenas palpação retal.`,`Apenas exame de sangue.`,`Apenas ultrassonografia.`,`Não é possível avaliar bodes.`],resposta_correta:`A`,explicacao:`Exame andrológico caprino: 1) Libido, 2) Genital externo (testículos, epidídimo, pênis prepucial), 3) Genital interno (palpação retal), 4) Coleta (vagina artificial ou eletroejaculação), 5) Avaliação seminal, 6) Sorologias (B. ovis, CAE).`},{id:`andro-267`,banca:`UFMG`,ano:2023,prova:`UFMG — Doutorado Reprodução 2023`,tipo:`pos`,topico:`andrologia_ovina_caprina`,subtopico:`Efeito macho (efeito male)`,dificuldade:`medio`,enunciado:`O efeito macho (male effect) em ovinos e caprinos:`,alternativas:[`É a introdução de um macho no rebanho que desencadeia a puberdade e sincroniza o cio em fêmeas anêstricas, por estímulo olfativo (feromônios).`,`Não tem efeito sobre as fêmeas.`,`Causa estresse e infertilidade nas fêmeas.`,`É um método de castração.`,`Não ocorre em caprinos.`],resposta_correta:`A`,explicacao:`O efeito macho: a introdução de machos (especialmente os que estiveram isolados) em rebanhos de fêmeas anêstricas estimula a atividade ovariana por estímulo olfativo (feromônios do pelo, sudorese prepucial) → pico de LH → ovulação. Eficaz em ovinos e caprinos de dias curtos.`},{id:`andro-268`,banca:`UNESP`,ano:2020,prova:`UNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Puberdade em ovinos`,dificuldade:`facil`,enunciado:`A puberdade em cordeiros machos ocorre, em média, aos:`,alternativas:[`4-8 meses, variando com a raça, nutrição e fotoperíodo.`,`2 meses.`,`12-18 meses.`,`Apenas aos 2 anos.`,`Não depende de fatores ambientais.`],resposta_correta:`A`,explicacao:`A puberdade em cordeiros: 4-8 meses (raças de dias curtos mais precoces). A maturidade sexual completa ocorre aos 12-18 meses. Fatores: fotoperíodo (dias curtos favorecem), nutrição (boa nutrição antecipa), raça, peso corporal.`},{id:`andro-269`,banca:`USP`,ano:2021,prova:`USP — Doutorado em Reprodução 2021`,tipo:`pos`,topico:`andrologia_ovina_caprina`,subtopico:`Melatonina e reprodução ovina`,dificuldade:`dificil`,enunciado:`A melatonina em ovinos:`,alternativas:[`É produzida pela glândula pineal durante a noite e atua no hipotálamo estimulando a secreção de GnRH, sendo o mediador do efeito do fotoperíodo sobre a reprodução.`,`É produzida pelo testículo.`,`Inibe a secreção de GnRH.`,`É um hormônio produzido pela hipófise.`,`Não tem efeito sobre a reprodução ovina.`],resposta_correta:`A`,explicacao:`A melatonina (produzida pela pineal durante o escuro) é o mediador do fotoperíodo. Noites longas → mais melatonina → estimulação do GnRH → aumento de LH/FSH/testosterona → ativação reprodutiva. Em dias curtos (inverno), a melatonina é alta e a reprodução é ativa.`},{id:`andro-270`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Concurso Veterinário 2022`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Caprinos — efeito fotoperíodo`,dificuldade:`medio`,enunciado:`Os caprinos (bodes) são animais:`,alternativas:[`De dias curtos (short-day breeders), com aumento da atividade sexual no outono/inverno, semelhante aos ovinos.`,`De dias longos (long-day breeders).`,`Que não são influenciados pelo fotoperíodo.`,`Reprodutores o ano todo sem variação.`,`De dias curtos, mas com anestro no inverno.`],resposta_correta:`A`,explicacao:`Caprinos (bodes) são reprodutores de dias curtos, semelhante aos carneiros. No outono/inverno (dias curtos), há aumento da libido, espermatogênese e concentração de testosterona. Na primavera/verão, redução da atividade sexual.`},{id:`andro-271`,banca:`MAPA`,ano:2020,prova:`MAPA — Fiscal Federal Agropecuário 2020`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Circunferência escrotal ovina`,dificuldade:`facil`,enunciado:`O perímetro escrotal mínimo para aprovação de carneiros adultos no exame andrológico é:`,alternativas:[`30 cm.`,`15 cm.`,`40 cm.`,`50 cm.`,`20 cm.`],resposta_correta:`A`,explicacao:`Perímetro escrotal mínimo para carneiros adultos: ≥30 cm. Para borregos (8-12 meses): ≥26 cm. O perímetro escrotal é proporcional à massa testicular e produção espermática.`},{id:`andro-272`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Caprinos — sêmen`,dificuldade:`medio`,enunciado:`O sêmen caprino apresenta características:`,alternativas:[`Volume 0,5-2 mL, concentração 2-5 bilhões/mL, motilidade ≥70%, odor forte característico (produzido pelas glândulas bulbouretrais).`,`Volume 50-100 mL, sem odor.`,`Volume 10-20 mL, concentração 100 milhões/mL.`,`Volume 0,1 mL, sem espermatozoides.`,`Não existem parâmetros de referência.`],resposta_correta:`A`,explicacao:`Sêmen caprino: volume 0,5-2 mL, concentração 2-5 bilhões/mL (muito alta), motilidade ≥70%, morfologia normal ≥80%. O odor forte (bode) é produzido pelas glândulas bulbouretrais (4-metilpentanoato de colesterila e ácido 4-metilpentanoico).`},{id:`andro-273`,banca:`UFBA`,ano:2023,prova:`UFBA — Concurso Veterinário 2023`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`CAE em caprinos`,dificuldade:`medio`,enunciado:`A artrite encefalite caprina (CAE) é:`,alternativas:[`Doença viral (lentivírus) que causa artrite crônica, mastite, encefalite e pode afetar a reprodução, sendo transmitida por colostro/leite contaminado.`,`Doença bacteriana que causa apenas artrite.`,`Doença que afeta apenas o sistema nervoso.`,`Não tem efeito sobre a reprodução.`,`É transmitida apenas por via sexual.`],resposta_correta:`A`,explicacao:`A CAE (Caprine Arthritis Encephalitis) é causada por um lentivírus. Causa: artrite crônica (articular), mastite indurativa, encefalite (em cabritos), pneumonite intersticial. Transmissão: vertical (colostro/leite), horizontal (sangue). Diagnóstico: ELISA, AGID.`},{id:`andro-274`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Pênis ovino/caprino`,dificuldade:`facil`,enunciado:`O pênis de ovinos e caprinos é classificado como:`,alternativas:[`Fibroelástico com flexura sigmoide, semelhante ao bovino.`,`Musculocavernoso, semelhante ao equino.`,`Com osso peniano (baculum).`,`Sem flexura sigmoide.`,`Retrátil permanentemente.`],resposta_correta:`A`,explicacao:`O pênis ovino e caprino é fibroelástico com flexura sigmoide (semelhante ao bovino). A ereção envolve deslocamento da flexura sigmoide e tumescência do bulbo. O processo uretral é longo e fino em ovinos.`},{id:`andro-275`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Relação macho:fêmea em ovinos`,dificuldade:`facil`,enunciado:`A relação carneiro:ovelha para monta natural em ovinos é:`,alternativas:[`1:20 a 1:40, dependendo da idade e condição do carneiro.`,`1:1.`,`1:100.`,`1:10.`,`Não existe relação recomendada.`],resposta_correta:`A`,explicacao:`Relação carneiro:ovelha para monta natural: 1:20-30 (carneiros adultos experientes), 1:15-20 (borregos). Carneiros podem realizar 5-8 coberturas por dia. Na monta controlada, 1:10-15 é mais seguro.`},{id:`andro-276`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBAMA 2022`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Eletroejaculação em ovinos`,dificuldade:`medio`,enunciado:`A eletroejaculação em ovinos e caprinos:`,alternativas:[`É uma técnica de coleta alternativa quando a vagina artificial não pode ser utilizada, usando sonda retal com estímulos elétricos intermitentes.`,`É a técnica de primeira escolha.`,`Causa infertilidade permanente.`,`Não é possível em ovinos.`,`Só funciona em anestesia geral.`],resposta_correta:`A`,explicacao:`A eletroejaculação é usada quando a monta não é possível (animais mansos, selvagens, com defeitos de monta). Sonda retal com eletrodos → estímulos elétricos intermitentes → emissão e ejaculação. O sêmen coletado pode ter qualidade inferior ao de vagina artificial.`},{id:`andro-277`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Congelamento de sêmen ovino`,dificuldade:`medio`,enunciado:`O congelamento de sêmen ovino para IA laparoscópica é:`,alternativas:[`Viável e utilizado comercialmente, com taxas de prenhez de 50-70%.`,`Impossível.`,`Apenas experimental.`,`Menos eficiente que sêmen fresco, mas viável.`,`A e D estão corretas.`],resposta_correta:`E`,explicacao:`O congelamento de sêmen ovino é viável (A é correta) e as taxas de prenhez com IA laparoscópica (depósito intrauterino) são de 50-70% (D também é correto). A IA cervical com sêmen congelado tem taxas muito baixas (~20%).`},{id:`andro-278`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso Veterinário 2022`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Borregos — puberdade`,dificuldade:`facil`,enunciado:`A puberdade em borregos machos ocorre mais cedo que em cordeiros de raças de dias longos porque:`,alternativas:[`Raças de dias curtos (merino, Santa Inês) são mais precoces que raças de dias longos (Suffolk, Hampshire) em termos de maturidade sexual.`,`Não há diferença entre raças.`,`Raças de dias longos são mais precoces.`,`A puberdade depende apenas do peso.`,`O fotoperíodo não afeta a puberdade.`],resposta_correta:`A`,explicacao:`Raças de dias curtos (merino, Santa Inês, Dorper) têm puberdade mais precoce (4-6 meses) que raças de dias longos (Suffolk, Hampshire, Ile de France, 6-8 meses). O fotoperíodo é o principal modulador da maturidade sexual em ovinos.`},{id:`andro-279`,banca:`UFPR`,ano:2020,prova:`UFPR — Concurso Veterinário 2020`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Prepúcio ovino`,dificuldade:`facil`,enunciado:`O prepúcio em ovinos e caprinos:`,alternativas:[`É uma dobra de pele que recobre o pênis flácido, acumulando secreção (smegma) que deve ser limpa antes da coleta de sêmen.`,`É ausente em ovinos.`,`Não acumula secreção.`,`É uma glândula acessória.`,`Produz espermatozoides.`],resposta_correta:`A`,explicacao:`O prepúcio em ovinos/caprinos recobre o pênis flácido e acumula smegma (secreção sebácea + detritos). A limpeza do prepúcio antes da coleta é importante para evitar contaminação do sêmen com bactérias e debris.`},{id:`andro-280`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso Veterinário 2021`,tipo:`concurso`,topico:`andrologia_ovina_caprina`,subtopico:`Doenças reprodutivas em caprinos`,dificuldade:`medio`,enunciado:`As principais doenças reprodutivas em bodes reprodutores incluem:`,alternativas:[`Brucella ovis (epididimite), CAE (artrite encefalite caprina) e artrite contagiosa caprina (Mycoplasma).`,`Apenas brucelose.`,`Apenas leptospirose.`,`Apenas tuberculose.`,`Não existem doenças reprodutivas em bodes.`],resposta_correta:`A`,explicacao:`Doenças reprodutivas em bodes: B. ovis (epididimite, infertilidade), CAE (lentivírus, artrite crônica, mastite), artrite contagiosa (Mycoplasma agalactiae, M. mycoides), caprine herpesvirus (balanopostite). Controle: sorologias, quarentena, biossegurança.`},{id:`andro-281`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`CRMV e andrologia`,dificuldade:`medio`,enunciado:`O CRMV (Conselho Regional de Medicina Veterinária) é responsável por:`,alternativas:[`Fiscalizar o exercício da Medicina Veterinária, inclusive a andrologia, registro de profissionais e aplicação de penalidades éticas.`,`Regular a importação de sêmen.`,`Fiscalizar a produção de alimentos.`,`Registrar medicamentos veterinários.`,`Emitir licenças ambientais.`],resposta_correta:`A`,explicacao:`O CRMV fiscaliza o exercício profissional do médico veterinário (Lei 5.517/1968), incluindo a andrologia clínica e laboratorial. Registra profissionais, aplica penalidades éticas e disciplinares, e regulamenta a responsabilidade técnica.`},{id:`andro-282`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Registro de sêmen`,dificuldade:`dificil`,enunciado:`Julgue o item sobre o registro de sêmen para IA no Brasil.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O sêmen para inseminação artificial deve ser registrado no MAPA (Ministério da Agricultura, Pecuária e Abastecimento), com rastreabilidade do animal doador, resultado do exame andrológico, exames sanitários e controle de qualidade, conforme a Instrução Normativa nº 33/2004.`,explicacao:`A IN MAPA nº 33/2004 regulamenta a produção, comercialização e utilização de sêmen e embriões. O sêmen para IA deve ser registrado, com rastreabilidade do doador, exames sanitários (brucelose, IBR, BVD, leucose), exame andrológico aprovado e controle de qualidade.`},{id:`andro-283`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Importação/exportação de sêmen`,dificuldade:`medio`,enunciado:`A importação e exportação de sêmen animal no Brasil é regulamentada por:`,alternativas:[`MAPA (Ministério da Agricultura, Pecuária e Abastecimento), que exige certificação sanitária, registro do doador e quarentena.`,`IBAMA.`,`ANVISA.`,`Ministério da Saúde.`,`Ministério do Meio Ambiente.`],resposta_correta:`A`,explicacao:`A importação/exportação de sêmen animal é regulamentada pelo MAPA (área de defesa sanitária animal). Exigências: certificação sanitária do país exportador, registro do doador no MAPA, exames sanitários (BSE, brucelose, IBR, BVD, TSE), quarentena e rastreabilidade.`},{id:`andro-284`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Biossegurança em centrais de IA`,dificuldade:`medio`,enunciado:`A biossegurança em centrais de inseminação artificial inclui:`,alternativas:[`Quarentena de touros novos, exames sanitários periódicos, controle de acesso, desinfecção de equipamentos e rastreabilidade do sêmen.`,`Apenas vacinação dos touros.`,`Apenas controle de pragas.`,`Apenas higiene pessoal.`,`Não existe biossegurança em centrais.`],resposta_correta:`A`,explicacao:`Biossegurança em centrais: quarentena (30-60 dias para touros novos), exames sorológicos (Brucella, IBR, BVD, leptospirose, leucose), controle de acesso (vestimenta, desinfecção), desinfecção de vaginas artificiais e equipamentos, rastreabilidade, controle de insetos/roedores.`},{id:`andro-285`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Reprodução Animal 2022`,tipo:`pos`,topico:`legislacao_andrologia`,subtopico:`Responsabilidade técnica`,dificuldade:`medio`,enunciado:`A responsabilidade técnica (RT) de uma central de inseminação é:`,alternativas:[`Exercida por um médico veterinário registrado no CRMV, responsável pela qualidade do sêmen, saúde dos animais e cumprimento das normas.`,`Exercida por qualquer profissional.`,`Exercida pelo proprietário da central.`,`Não é obrigatória.`,`Exercida pelo MAPA.`],resposta_correta:`A`,explicacao:`A RT de uma central de IA deve ser exercida por médico veterinário com registro no CRMV (Lei 5.517/1968). É responsável pela qualidade do sêmen, saúde dos reprodutores, cumprimento das normas sanitárias e técnicas. O profissional responde ética e civilmente.`},{id:`andro-286`,banca:`CRMV`,ano:2020,prova:`CRMV-SP — Prova de Suficiência 2020`,tipo:`crmv`,topico:`legislacao_andrologia`,subtopico:`Normas para centrais de IA`,dificuldade:`medio`,enunciado:`As normas para funcionamento de centrais de inseminação artificial no Brasil são estabelecidas:`,alternativas:[`Pela Instrução Normativa MAPA nº 33/2004 e suas atualizações, que regulamentam a produção, comercialização e utilização de sêmen e embriões.`,`Pela Constituição Federal.`,`Pelo código de defesa do consumidor.`,`Pela legislação trabalhista.`,`Não existem normas específicas.`],resposta_correta:`A`,explicacao:`A IN MAPA nº 33/2004 (e atualizações) regulamenta: registro de estabelecimentos, requisitos para touros doadores, controle de qualidade do sêmen, exames sanitários, rastreabilidade, comercialização e transporte de sêmen e embriões.`},{id:`andro-287`,banca:`UFMG`,ano:2022,prova:`UFMG — Professor Assistente 2022`,tipo:`pos`,topico:`legislacao_andrologia`,subtopico:`Exames sanitários obrigatórios`,dificuldade:`medio`,enunciado:`Os exames sanitários obrigatórios para touros doadores de sêmen no Brasil incluem:`,alternativas:[`Brucelose (B. abortus), IBR/BHV-1, BVD, leucose bovina, tuberculose e, para exportação, encefalopatia espongiforme bovina (BSE).`,`Apenas brucelose.`,`Apenas tuberculose.`,`Apenas IBR.`,`Não existem exames obrigatórios.`],resposta_correta:`A`,explicacao:`Exames obrigatórios (IN MAPA 33/2004): brucelose (soroaglutinação), IBR/BHV-1 (sorologia), BVD (sorologia), leucose bovina (ELISA/AGID), tuberculose (tuberculinização). Para exportação: exames adicionais conforme país importador (BSE, febre aftosa, etc.).`},{id:`andro-288`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Transporte de sêmen`,dificuldade:`medio`,enunciado:`O transporte de sêmen congelado no Brasil:`,alternativas:[`Deve ser realizado em recipientes de N₂ líquido (dry shipper ou tanque portátil), com documentação sanitária e rastreabilidade.`,`Pode ser feito em caixa de isopor com gelo.`,`Não é regulamentado.`,`É proibido entre estados.`,`Pode ser feito em temperatura ambiente.`],resposta_correta:`A`,explicacao:`O transporte de sêmen congelado: em recipientes de N₂ líquido (dry shipper ou tanque portátil com absorvente), com documentação (nota fiscal, certificado sanitário, registro do doador), rastreabilidade e temperatura controlada (-196°C).`},{id:`andro-289`,banca:`USP`,ano:2020,prova:`USP — Doutorado em Reprodução 2020`,tipo:`pos`,topico:`legislacao_andrologia`,subtopico:`Legislação de biotecnologias`,dificuldade:`dificil`,enunciado:`A legislação brasileira sobre organismos geneticamente modificados (OGMs) em reprodução animal é regulamentada por:`,alternativas:[`Lei de Biossegurança (Lei 11.105/2005) e CTNBio, que regulamentam a pesquisa e uso de OGMs, incluindo animais transgênicos.`,`Apenas pelo MAPA.`,`Apenas pelo IBAMA.`,`Apenas pelo Ministério da Saúde.`,`Não existe regulamentação para OGMs no Brasil.`],resposta_correta:`A`,explicacao:`A Lei 11.105/2005 (Lei de Biossegurança) e a CTNBio (Comissão Técnica Nacional de Biossegurança) regulamentam: pesquisa com OGMs, liberação comercial, uso de técnicas como transgenia, CRISPR, clonagem em animais. Exige aprovação prévia da CTNBio.`},{id:`andro-290`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Propriedade intelectual`,dificuldade:`dificil`,enunciado:`A propriedade intelectual em biotecnologias reprodutivas é regulamentada no Brasil por:`,alternativas:[`Lei de Propriedade Industrial (Lei 9.279/1996), que protege invenções biotecnológicas, excluindo a possibilidade de patenteamento de animais.`,`Apenas pelo MAPA.`,`Apenas pela Constituição Federal.`,`Não existe proteção de propriedade intelectual para biotecnologia animal.`,`Apenas pelo código civil.`],resposta_correta:`A`,explicacao:`A Lei 9.279/1996 protege invenções biotecnológicas (processos, produtos). No Brasil, é possível patentear processos biotecnológicos (sexagem, clonagem, transgenia), mas não animais per se. O direito de cultivar/vári protege variedades melhoradas (Lei 9.456/1997).`},{id:`andro-291`,banca:`MAPA`,ano:2021,prova:`MAPA — Fiscal Federal Agropecuário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Defesa sanitária animal`,dificuldade:`medio`,enunciado:`O PNDSA (Plano Nacional de Defesa Sanitária Animal) inclui:`,alternativas:[`Vigilância epidemiológica de doenças reprodutivas (brucelose, tricomonose, campilobacterose), com programa de certificação de rebanhos.`,`Apenas controle de febre aftosa.`,`Apenas controle de aftosa e raiva.`,`Apenas inspeção de carnes.`,`Não contempla doenças reprodutivas.`],resposta_correta:`A`,explicacao:`O PNDSA contempla vigilância e controle de doenças de notificação compulsória, incluindo doenças reprodutivas: brucelose (programa nacional de controle), tricomonose, campilobacterose, metrite contagiosa equina, IBR/BHV-1, BVD. Inclui certificação de rebanhos livres.`},{id:`andro-292`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Notificação compulsória`,dificuldade:`facil`,enunciado:`As doenças reprodutivas de notificação compulsória ao MAPA incluem:`,alternativas:[`Brucelose bovina, campilobacterose genital bovina, tricomonose genital bovina e metrite contagiosa equina.`,`Apenas brucelose.`,`Apenas febre aftosa.`,`Apenas tuberculose.`,`Não existem doenças reprodutivas de notificação compulsória.`],resposta_correta:`A`,explicacao:`Doenças reprodutivas de notificação compulsória: brucelose bovina/ bubalina (B. abortus), campilobacterose genital bovina (C. fetus venerealis), tricomonose genital bovina (T. fetus), metrite contagiosa equina (T. equigenitalis). Devem ser notificadas ao serviço veterinário oficial.`},{id:`andro-293`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Controle de qualidade de sêmen`,dificuldade:`medio`,enunciado:`O controle de qualidade de sêmen para IA é regulamentado:`,alternativas:[`Pela IN MAPA nº 33/2004, que estabelece parâmetros mínimos de motilidade, concentração, morfologia e volume por dose inseminante.`,`Apenas pela OMS.`,`Pela legislação municipal.`,`Não existe regulamentação para controle de qualidade.`,`Apenas pela legislação estadual.`],resposta_correta:`A`,explicacao:`A IN MAPA nº 33/2004 estabelece: parâmetros mínimos de qualidade (motilidade, concentração, morfologia), volume por dose, rastreabilidade, exames sanitários, registro do doador e do lote de sêmen. Centrais devem manter registros e laudos.`},{id:`andro-294`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Responsabilidade civil`,dificuldade:`medio`,enunciado:`O médico veterinário responsável por uma central de IA pode ser responsabilizado civilmente por:`,alternativas:[`Danos causados por sêmen contaminado, transmissão de doenças ou falha no controle de qualidade, decorrentes de negligência, imprudência ou imperícia.`,`Apenas por erros de diagnóstico.`,`Apenas por erros cirúrgicos.`,`Não existe responsabilidade civil em andrologia.`,`Apenas penalidades éticas.`],resposta_correta:`A`,explicacao:`A responsabilidade civil do médico veterinário em andrologia: danos por sêmen contaminado (DST), falha no controle de qualidade, negligência em exames sanitários, imperícia em técnicas de IA. Responde por danos materiais e morais (Código Civil, CDC).`},{id:`andro-295`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Bem-estar animal`,dificuldade:`medio`,enunciado:`A legislação de bem-estar animal no Brasil (Lei 14.064/2020) em relação a animais de produção:`,alternativas:[`Proíbe maus-tratos e prevê penalidades para crueldade, incluindo práticas de manejo reprodutivo que causem sofrimento desnecessário.`,`Não se aplica a animais de produção.`,`Proíbe a inseminação artificial.`,`Não contempla reprodução animal.`,`Permite qualquer prática sem restrição.`],resposta_correta:`A`,explicacao:`A Lei 14.064/2020 (Lei Sansão) protege animais contra maus-tratos. Inclui animais de produção. Práticas de manejo reprodutivo devem respeitar o bem-estar: contenção adequada, analgesia/anestesia quando necessário, evitar sofrimento desnecessário em exames andrológicos e IA.`},{id:`andro-296`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBAMA 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Lei de Biossegurança`,dificuldade:`medio`,enunciado:`A Lei de Biossegurança (Lei 11.105/2005) regulamenta:`,alternativas:[`Pesquisa e uso de OGMs, incluindo animais transgênicos e clonados, com exigência de aprovação prévia da CTNBio.`,`Apenas plantas transgênicas.`,`Apenas medicamentos.`,`Apenas agrotóxicos.`,`Não regulamenta animais.`],resposta_correta:`A`,explicacao:`A Lei 11.105/2005 regulamenta: OGMs (incluindo animais), clonagem, transgenia, terapia gênica. A CTNBio avalia riscos e aprova projetos. Animais transgênicos e clonados requerem aprovação da CTNBio para pesquisa e liberação comercial.`},{id:`andro-297`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Código de Ética Veterinária`,dificuldade:`medio`,enunciado:`O Código de Ética Profissional do Médico Veterinário (Resolução CFMV nº 1.127/2019) estabelece que:`,alternativas:[`O profissional deve exercer suas atividades com competência, responsabilidade e respeito ao bem-estar animal, incluindo a andrologia.`,`A andrologia não é regulamentada pelo código de ética.`,`Apenas cirurgiões-dentistas podem atuar em andrologia.`,`O código não contempla reprodução animal.`,`Apenas regulamenta a clínica de pequenos animais.`],resposta_correta:`A`,explicacao:`O Código de Ética CFMV (Resolução 1.127/2019) regulamenta o exercício profissional, incluindo responsabilidade técnica, competência, sigilo profissional, bem-estar animal, e relações com clientes e colegas. A andrologia é parte da atividade médica veterinária.`},{id:`andro-298`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Prova de Título em Reprodução Animal 2020`,tipo:`pos`,topico:`legislacao_andrologia`,subtopico:`Rastreabilidade`,dificuldade:`medio`,enunciado:`A rastreabilidade do sêmen para IA no Brasil:`,alternativas:[`É obrigatória, permitindo identificar o doador, data de coleta, lote, qualidade e destinação de cada dose inseminante.`,`Não é obrigatória.`,`É obrigatória apenas para exportação.`,`É opcional para centrais privadas.`,`Apenas para sêmen congelado.`],resposta_correta:`A`,explicacao:`A rastreabilidade é obrigatória (IN MAPA 33/2004): cada palheta/dose deve identificar: doador (registro), lote, data de coleta/congelamento, central de origem, qualidade, validade. Permite rastrear focos de contaminação, falhas de qualidade e surtos de doenças.`},{id:`andro-299`,banca:`UFPR`,ano:2022,prova:`UFPR — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Animais de raça pura`,dificuldade:`medio`,enunciado:`O registro genealógico de animais de raça pura (RG) no Brasil é mantido:`,alternativas:[`Pelos registros genealógicos (associações de raça) sob supervisão do MAPA, que certifica a pureza racial e o pedigree.`,`Pelo CRMV.`,`Pelo IBGE.`,`Pela ABRAVES.`,`Não existe registro genealógico no Brasil.`],resposta_correta:`A`,explicacao:`O registro genealógico (RG) é mantido por associações de raça (ex.: ABCZ para Nelore, ABQM para Quarto de Milha), supervisionadas pelo MAPA. O RG certifica pureza racial, ascendência (pedigree) e é exigido para touros doadores em centrais de IA.`},{id:`andro-300`,banca:`UFRGS`,ano:2021,prova:`UFRGS — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Propriedade de sêmen`,dificuldade:`medio`,enunciado:`A propriedade intelectual sobre linhagens genéticas melhoradas (semen, embriões) é protegida:`,alternativas:[`Pela Lei de Cultivares (Lei 9.456/1997), que protege variedades melhoradas de animais e plantas.`,`Pela Lei de Biossegurança.`,`Pelo código de defesa do consumidor.`,`Não existe proteção para linhagens animais.`,`Apenas pela legislação internacional.`],resposta_correta:`A`,explicacao:`A Lei 9.456/1997 (Lei de Cultivares) protege variedades melhoradas de plantas e animais. Proprietários de linhagens genéticas (semen, embriões) podem registrar e proteger suas variedades, controlando a reprodução e comercialização.`},{id:`andro-301`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Exportação de sêmen`,dificuldade:`medio`,enunciado:`A exportação de sêmen bovino do Brasil requer:`,alternativas:[`Certificação sanitária do MAPA, exames adicionais conforme país importador (BSE, IBR, BVD), registro no sistema informatizado e quarentena.`,`Apenas exame de brucelose.`,`Apenas registro no CRMV.`,`Apenas aprovação do IBAMA.`,`Não é permitida a exportação de sêmen.`],resposta_correta:`A`,explicacao:`Exportação de sêmen: certificação sanitária pelo MAPA, exames conforme país importador (brucelose, IBR, BVD, BSE, leucose, tuberculose, leucose enzoótica), quarentena, rastreabilidade, registro no sistema SISBOV/AGRODEFESA, e atendimento a acordos bilaterais.`},{id:`andro-302`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Aborto de notificação compulsória`,dificuldade:`facil`,enunciado:`O aborto em fêmeas bovinas por Brucella abortus é:`,alternativas:[`Doença de notificação compulsória ao serviço veterinário oficial, com investigação epidemiológica e medidas de controle.`,`Não é de notificação compulsória.`,`É tratável com antibióticos.`,`Não tem relevância para saúde pública.`,`Apenas ocorre em fêmeas primíparas.`],resposta_correta:`A`,explicacao:`A brucelose bovina (B. abortus) é doença de notificação compulsória (Lista A do MAPA). O aborto é o principal sinal clínico. Notificação obrigatória → investigação epidemiológica → medidas de controle (vacinação B19/CE, testagem, abate de reagentes). Zoonose.`},{id:`andro-303`,banca:`CESPE`,ano:2021,prova:`CESPE — Professor Universitário 2021`,tipo:`pos`,topico:`legislacao_andrologia`,subtopico:`CTNBio e animais transgênicos`,dificuldade:`dificil`,enunciado:`A CTNBio (Comissão Técnica Nacional de Biossegurança) é:`,alternativas:[`Órgão colegiado multidisciplinar que avalia riscos de OGMs, incluindo animais transgênicos, e emite pareceres técnicos sobre biossegurança.`,`Um órgão do MAPA apenas.`,`Uma comissão do CRMV.`,`Uma comissão do IBAMA.`,`Não existe mais no Brasil.`],resposta_correta:`A`,explicacao:`A CTNBio (Lei 11.105/2005) é órgão colegiado do MCTI, com representantes de diversas áreas. Avalia: riscos de OGMs, projetos de pesquisa, liberação comercial de transgênicos, clonagem. Emite pareceres técnicos vinculantes. Inclui animais transgênicos e biotecnologia reprodutiva.`},{id:`andro-304`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário Prefeitura 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Certificação de centrais`,dificuldade:`medio`,enunciado:`O certificado de aptidão sanitária de uma central de IA é emitido:`,alternativas:[`Pela autoridade veterinária estadual ou federal, após inspeção in loco e cumprimento dos requisitos técnicos e sanitários.`,`Pelo CRMV.`,`Pela ABRAVES.`,`Pela associação de raça.`,`Não é obrigatório.`],resposta_correta:`A`,explicacao:`O certificado de aptidão sanitária é emitido pelo serviço veterinário oficial (estadual ou federal) após inspeção in loco, verificando: instalações, equipamentos, biossegurança, saúde dos animais, controle de qualidade, responsabilidade técnica e documentação.`},{id:`andro-305`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Responsabilidade do médico veterinário`,dificuldade:`medio`,enunciado:`O médico veterinário que atua em andrologia:`,alternativas:[`Deve estar registrado no CRMV, possuir responsabilidade técnica sobre o serviço e seguir as normas éticas e técnicas vigentes.`,`Não precisa de registro no CRMV.`,`Pode atuar sem responsabilidade técnica.`,`Não é regulamentado.`,`Apenas precisa de diploma.`],resposta_correta:`A`,explicacao:`O médico veterinário em andrologia: registro ativo no CRMV, inscrição no cadastro de RT, cumprimento do Código de Ética CFMV, seguir normas MAPA (IN 33/2004), manter capacitação técnica, responsabilidade civil e penal por seus atos profissionais.`},{id:`andro-306`,banca:`UFRRJ`,ano:2020,prova:`UFRRJ — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Comercialização de sêmen`,dificuldade:`medio`,enunciado:`A comercialização de sêmen para IA no Brasil:`,alternativas:[`Deve seguir a IN MAPA 33/2004, com registro do estabelecimento, rastreabilidade, nota fiscal e certificação sanitária.`,`Não é regulamentada.`,`Pode ser feita livremente por qualquer pessoa.`,`É proibida para exportação.`,`Apenas para uso próprio.`],resposta_correta:`A`,explicacao:`A comercialização de sêmen: estabelecimento registrado no MAPA, responsável técnico, rastreabilidade (identificação do doador, lote, data), nota fiscal, certificado sanitário, parâmetros de qualidade atendidos, transporte adequado.`},{id:`andro-307`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Vacinação contra brucelose`,dificuldade:`facil`,enunciado:`A vacinação contra brucelose bovina no Brasil:`,alternativas:[`É obrigatória para fêmeas de 3-8 meses com vacina B19, e voluntária com vacina RB51. Touros não devem ser vacinados.`,`É obrigatória para machos e fêmeas.`,`Não é obrigatória.`,`Apenas para animais de leite.`,`É proibida por lei.`],resposta_correta:`A`,explicacao:`Vacinação contra brucelose (IN MAPA 2/2014): B19 (obrigatória para fêmeas 3-8 meses), RB51 (voluntária, sem exigência de idade). Touros não devem ser vacinados (risco de interferência nos testes sorológicos). A vacinação é uma das estratégias do Programa Nacional de Controle.`},{id:`andro-308`,banca:`UFBA`,ano:2021,prova:`UFBA — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Legislação estadual`,dificuldade:`medio`,enunciado:`A legislação estadual sobre reprodução animal:`,alternativas:[`Pode complementar a legislação federal (MAPA), com normas adicionais para centrais de IA e controle sanitário estadual.`,`Não existe legislação estadual sobre reprodução.`,`Contradiz a legislação federal.`,`É mais permissiva que a federal.`,`Não é válida em conjunto com a federal.`],resposta_correta:`A`,explicacao:`A legislação estadual complementa a federal: normas estaduais de defesa sanitária, regulamentação de centrais de IA no estado, inspeções estaduais, controle de DSTs regionais. Exemplo: legislações estaduais sobre brucelose e tuberculose complementam o PNDSA.`},{id:`andro-309`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso Médico Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`SISBOV`,dificuldade:`medio`,enunciado:`O SISBOV (Sistema Brasileiro de Identificação e Certificação Bovina e Bubalina) é:`,alternativas:[`Sistema de rastreabilidade animal do Brasil, que permite identificar e rastrear bovinos e bubalinos desde o nascimento até o abate.`,`Um sistema de registro de sêmen.`,`Um sistema de controle de pragas.`,`Um sistema de registro de profissionais.`,`Não existe mais no Brasil.`],resposta_correta:`A`,explicacao:`O SISBOV é o sistema de rastreabilidade do MAPA para bovinos e bubalinos. Identifica animais com brinco/concha, rastreia movimentações e propriedades. Relaciona-se com andrologia na rastreabilidade de touros doadores e sêmen comercializado.`},{id:`andro-310`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Defesa sanitária`,dificuldade:`medio`,enunciado:`A defesa sanitária animal no Brasil é coordenada:`,alternativas:[`Pelo MAPA (Ministério da Agricultura, Pecuária e Abastecimento) através da SDV (Secretaria de Defesa Agropecuária), com atuação federal, estadual e municipal.`,`Pelo Ministério da Saúde.`,`Pelo IBAMA.`,`Pelo CRMV.`,`Pela OMS.`],resposta_correta:`A`,explicacao:`A defesa sanitária animal é coordenada pelo MAPA/SDV: coordenação federal (programas nacionais), execução estadual (veterinários estaduais) e municipal. Abrange: vigilância epidemiológica, controle de DSTs, certificação sanitária, quarentena, defesa sanitária vegetal e animal.`},{id:`andro-311`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário IBAMA 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Animais de laboratório`,dificuldade:`medio`,enunciado:`A legislação sobre uso de animais em pesquisa (Lei 11.794/2008) estabelece que:`,alternativas:[`Pesquisas com animais devem ser aprovadas por CEUA (Comissão de Ética no Uso de Animais), com respeito ao bem-estar e princípio dos 3Rs (substituir, reduzir, refinar).`,`A pesquisa com animais é proibida no Brasil.`,`Não existe regulamentação para uso de animais em pesquisa.`,`Apenas pesquisas médicas são permitidas.`,`A andrologia é isenta de regulamentação.`],resposta_correta:`A`,explicacao:`A Lei 11.794/2008 regulamenta uso de animais em pesquisa: aprovação por CEUA, princípio dos 3Rs (substituir, reduzir, refinar), bem-estar animal, eutanásia humanitária. Pesquisas em andrologia (novas técnicas de IA, criopreservação) devem seguir essa legislação.`},{id:`andro-312`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Controle de leucose`,dificuldade:`medio`,enunciado:`A leucose enzoótica bovina (LEB) é:`,alternativas:[`Doença viral (retrovírus) que causa linfossarcoma e é de controle obrigatório no Brasil, com testagem de touros doadores para comércio de sêmen.`,`Doença bacteriana.`,`Doença que não afeta bovinos.`,`Doença de notificação compulsória exclusiva.`,`Não tem controle no Brasil.`],resposta_correta:`A`,explicacao:`A LEB (vírus da leucose bovina — BLV) é um retrovírus que causa linfossarcoma. É de controle obrigatório no Brasil para touros doadores de sêmen (exame sorológico). Causa linfossarcomatose, redução de produção. Não é zoonota comprovada. Diagnóstico: ELISA, AGID.`},{id:`andro-313`,banca:`UFPR`,ano:2021,prova:`UFPR — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Certificação sanitária`,dificuldade:`medio`,enunciado:`O certificado sanitário para sêmen de exportação:`,alternativas:[`É emitido pela autoridade veterinária oficial do Brasil (MAPA), atestando que o sêmen atende aos requisitos sanitários do país importador.`,`É emitido pelo CRMV.`,`É emitido pela associação de raça.`,`Não é necessário para exportação.`,`É emitido pelo exportador.`],resposta_correta:`A`,explicacao:`O certificado sanitário internacional é emitido pelo MAPA (serviço veterinário oficial), atendendo aos requisitos do país importador (acordos bilaterais, protocolos sanitários). Inclui: identificação do doador, exames realizados, quarentena, central de origem.`},{id:`andro-314`,banca:`UFRGS`,ano:2023,prova:`UFRGS — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`ABRAVES`,dificuldade:`facil`,enunciado:`A ABRAVES (Associação Brasileira de Centrais de Inseminação Artificial e Reprodução Animal) é:`,alternativas:[`Entidade de classe que representa as centrais de IA e reprodutivas do Brasil, atuando em defesa do setor e na interlocução com o MAPA.`,`Um órgão do governo.`,`Um conselho profissional.`,`Uma universidade.`,`Não existe ABRAVES.`],resposta_correta:`A`,explicacao:`A ABRAVES é associação de classe que representa centrais de IA e empresas de reprodução animal. Atua em: interlocução com MAPA, defesa de interesses do setor, organização de eventos, difusão de tecnologias, padronização de normas técnicas.`},{id:`andro-315`,banca:`UFRPE`,ano:2020,prova:`UFRPE — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Incentivos fiscais`,dificuldade:`dificil`,enunciado:`A legislação tributária brasileira para o setor de reprodução animal:`,alternativas:[`Pode incluir incentivos fiscais (ICMS, IPI) para insumos de reprodução (sêmen, embriões, diluentes), variando por estado.`,`Não contempla o setor de reprodução animal.`,`Tributa sêmen como produto de luxo.`,`Não existe legislação tributária para reprodução.`,`Tributa apenas exportação.`],resposta_correta:`A`,explicacao:`Incentivos fiscais para reprodução animal: isenção/redução de ICMS em alguns estados para sêmen e embriões, incentivos federais para exportação de material genético, financiamento rural (BNDES) para aquisição de reprodutores e equipamentos de IA. Variável por estado e políticas vigentes.`},{id:`andro-316`,banca:`MAPA`,ano:2022,prova:`MAPA — Fiscal Federal Agropecuário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Programa Nacional de Controle`,dificuldade:`medio`,enunciado:`O Programa Nacional de Controle e Erradicação de Brucelose e Tuberculose (PNCEBT) inclui:`,alternativas:[`Vacinação obrigatória contra brucelose (B19), testagem de rebanhos, certificação de propriedades livres e controle de movimentação animal.`,`Apenas vacinação contra aftosa.`,`Apenas controle de tuberculose.`,`Apenas inspeção de carnes.`,`Não contempla brucelose.`],resposta_correta:`A`,explicacao:`O PNCEBT (IN MAPA 2/2014): vacinação obrigatória B19 (fêmeas 3-8 meses), testagem sorológica, certificação de propriedades livres/monitores, controle de movimentação, abate de reagentes. Objetivo: erradicação progressiva de brucelose e tuberculose.`},{id:`andro-317`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Importação de sêmen`,dificuldade:`medio`,enunciado:`A importação de sêmen para o Brasil:`,alternativas:[`Requer licença prévia do MAPA, certificação sanitária do país de origem, exames sanitários e quarentena.`,`É proibida.`,`Não é regulamentada.`,`Pode ser feita sem documentação.`,`Apenas para sêmen de gado leiteiro.`],resposta_correta:`A`,explicacao:`Importação de sêmen: licença prévia (LIA) do MAPA, certificação sanitária do país exportador, exames conforme lista brasileira (brucelose, IBR, BVD, BSE, tuberculose, leucose), quarentena no Brasil, registro do doador e rastreabilidade.`},{id:`andro-318`,banca:`UFBA`,ano:2023,prova:`UFBA — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Código de Ética`,dificuldade:`medio`,enunciado:`O Código de Ética do Médico Veterinário proíbe:`,alternativas:[`Publicidade enganosa, concorrência desleal, exercício ilegal da profissão e abandono de paciente, incluindo na área de andrologia.`,`Apenas a prática de eutanásia.`,`Apenas a cobrança de honorários.`,`Apenas o uso de medicamentos.`,`Não existe proibição no código de ética.`],resposta_correta:`A`,explicacao:`O Código de Ética CFMV proíbe: publicidade enganosa, concorrência desleal, exercício irregular, abandono de paciente, assédio, desrespeito ao bem-estar animal. Na andrologia: prometer resultados de fertilidade sem base técnica, negligenciar exames obrigatórios.`},{id:`andro-319`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso Médico Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Lei Sansão`,dificuldade:`medio`,enunciado:`A Lei Sansão (Lei 14.064/2020) alterou:`,alternativas:[`A Lei de Crimes Ambientais (Lei 9.605/1998), aumentando as penalidades para maus-tratos a animais, incluindo cães, gatos e animais de produção.`,`O código civil.`,`A lei de biossegurança.`,`A lei do CRMV.`,`Não alterou nenhuma lei.`],resposta_correta:`A`,explicacao:`A Lei 14.064/2020 (Lei Sansão) alterou a Lei 9.605/1998 (Crimes Ambientais): aumentou pena para maus-tratos a animais (cães, gatos e todos os animais), incluindo detenção de 2-5 anos, multa e proibição de guarda. Aplica-se a animais de produção.`},{id:`andro-320`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Fiscalização MAPA`,dificuldade:`medio`,enunciado:`A fiscalização de centrais de IA pelo MAPA inclui:`,alternativas:[`Inspeção in loco, verificação de documentação, exames sanitários, controle de qualidade, rastreabilidade e aplicação de penalidades.`,`Apenas verificação de documentação.`,`Apenas inspeção visual.`,`Não existe fiscalização do MAPA.`,`Apenas para exportação.`],resposta_correta:`A`,explicacao:`A fiscalização do MAPA: inspeções programadas e extraordinárias, verificação de documentação (registros, laudos, certificados), exames sanitários, controle de qualidade (motilidade, morfologia), rastreabilidade, aplicação de penalidades (multas, interdição, embargo).`},{id:`andro-321`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`SISPAV`,dificuldade:`medio`,enunciado:`O SISPAV (Sistema de Vigilância Agropecuária Internacional) é:`,alternativas:[`Sistema do MAPA que controla a importação e exportação de produtos de origem animal, incluindo sêmen, com inspeção em portos, aeroportos e fronteiras.`,`Sistema do IBAMA.`,`Sistema do Ministério da Saúde.`,`Sistema da ANVISA.`,`Não existe SISPAV.`],resposta_correta:`A`,explicacao:`O SISPAV integra o sistema de defesa sanitária do MAPA para vigilância em pontos de entrada (portos, aeroportos, fronteiras). Controla importação/exportação de produtos de origem animal (sêmen, embriões, animais, carnes), com inspeção sanitária e documentação.`},{id:`andro-322`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Propriedade industrial`,dificuldade:`dificil`,enunciado:`A Lei de Propriedade Industrial (Lei 9.279/1996) em relação a biotecnologia animal:`,alternativas:[`Permite o patenteamento de processos biotecnológicos (sexagem, clonagem), mas não de animais per se.`,`Proíbe qualquer patenteamento em biotecnologia animal.`,`Permite patenteamento de animais inteiros.`,`Não contempla biotecnologia.`,`Não existe proteção para biotecnologia animal.`],resposta_correta:`A`,explicacao:`A Lei 9.279/1996 permite: patenteamento de processos (sexagem seminal, ICSI, clonagem, transgenia) e produtos biotecnológicos, mas não de animais per se (excluídos como descobertas). A proteção de cultivares/vári (Lei 9.456/1997) protege linhagens genéticas animais.`},{id:`andro-323`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Prova de Título em Reprodução Animal 2023`,tipo:`pos`,topico:`legislacao_andrologia`,subtopico:`OEA e sêmen`,dificuldade:`medio`,enunciado:`A Organização Mundial de Saúde Animal (WOAH, ex-OIE):`,alternativas:[`Estabelece normas sanitárias internacionais para comércio de animais e produtos de origem animal, incluindo sêmen, com códigos sanitários para DSTs.`,`Não regulamenta sêmen.`,`Apenas regulamenta carnes.`,`Não existe mais.`,`Apenas regulamenta vacinas.`],resposta_correta:`A`,explicacao:`A WOAH (World Organisation for Animal Health) estabelece: códigos sanitários para comércio internacional de sêmen (Capítulo 4.6), normas para doenças de notificação (brucelose, campilobacterose, tricomonose), e diretrizes para biossegurança.`},{id:`andro-324`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Certificação de rebanhos`,dificuldade:`medio`,enunciado:`A certificação de rebanhos livres de brucelose e tuberculose no Brasil:`,alternativas:[`É parte do PNCEBT, com categorias de certificação (livre, monitor, erradicado), exigindo testagem periódica e manejo sanitário adequado.`,`Não existe no Brasil.`,`É voluntária para todos.`,`Apenas para rebanhos de exportação.`,`É obrigatória para todos os rebanhos.`],resposta_correta:`A`,explicacao:`O PNCEBT prevê certificação de propriedades: categorias (monitor, livre de brucelose e tuberculose, erradicado). Requisitos: testagem periódica (sorologia), vacinação, biossegurança, controle de movimentação. O MAPA e estados concedem certificação.`},{id:`andro-325`,banca:`UFRGS`,ano:2020,prova:`UFRGS — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Doenças de notificação`,dificuldade:`medio`,enunciado:`A lista de doenças de notificação compulsória no Brasil é mantida:`,alternativas:[`Pelo MAPA, com atualizações periódicas (INs), incluindo doenças reprodutivas como brucelose, campilobacterose e tricomonose.`,`Pelo Ministério da Saúde apenas.`,`Pelo IBAMA.`,`Pela OMS.`,`Não existe lista oficial.`],resposta_correta:`A`,explicacao:`A lista de doenças de notificação compulsória é mantida pelo MAPA (INs atualizadas). Doenças reprodutivas na lista: brucelose (B. abortus), campilobacterose genital (C. fetus), tricomonose (T. fetus), metrite contagiosa equina (T. equigenitalis), IBR/BHV-1.`},{id:`andro-326`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Legislação de IA`,dificuldade:`medio`,enunciado:`A principal norma que regulamenta a inseminação artificial no Brasil é:`,alternativas:[`Instrução Normativa MAPA nº 33/2004 e suas atualizações.`,`A Constituição Federal.`,`O Código Civil.`,`A Lei de Biossegurança.`,`Não existe norma específica.`],resposta_correta:`A`,explicacao:`A IN MAPA nº 33/2004 (e atualizações) é a principal norma: regulamenta produção, comercialização e utilização de sêmen e embriões. Estabelece: requisitos para estabelecimentos, touros doadores, controle de qualidade, registro, rastreabilidade, transporte.`},{id:`andro-327`,banca:`UFBA`,ano:2020,prova:`UFBA — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Competência profissional`,dificuldade:`medio`,enunciado:`A competência profissional do médico veterinário em andrologia inclui:`,alternativas:[`Exame andrológico, coleta e avaliação de sêmen, inseminação artificial, diagnóstico de infertilidade, orientação sanitária e prescrição de tratamentos.`,`Apenas inseminação artificial.`,`Apenas avaliação de sêmen.`,`Apenas exame clínico geral.`,`Não existe competência específica em andrologia.`],resposta_correta:`A`,explicacao:`A competência do MV em andrologia (Lei 5.517/1968, Resolução CFMV): exame andrológico completo, coleta/avaliação de sêmen, IA, diagnóstico de infertilidade masculina, prescrição de tratamentos, orientação sanitária, biossegurança e responsabilidade técnica.`},{id:`andro-328`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Penalidades éticas`,dificuldade:`medio`,enunciado:`As penalidades éticas para o médico veterinário que comete infrações em andrologia incluem:`,alternativas:[`Advertência, censura, multa, suspensão e cassação do exercício profissional, conforme o Código de Ética CFMV.`,`Apenas multa.`,`Apenas advertência.`,`Não existem penalidades.`,`Apenas penalidades civis.`],resposta_correta:`A`,explicacao:`As penalidades éticas (Resolução CFMV 1.127/2019): advertência confidencial, censura confidencial, censura pública, suspensão do exercício profissional (até 2 anos), cassação do exercício profissional. São aplicadas pelo CRMV após processo disciplinar.`},{id:`andro-329`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Regulamentação de clonagem`,dificuldade:`dificil`,enunciado:`A clonagem animal no Brasil:`,alternativas:[`É regulamentada pela Lei de Biossegurança (Lei 11.105/2005), com exigência de aprovação da CTNBio para pesquisa e liberação comercial.`,`É proibida.`,`Não é regulamentada.`,`É permitida sem restrições.`,`Apenas para uso científico.`],resposta_correta:`A`,explicacao:`A clonagem animal (transferência nuclear de célula somática) é regulamentada pela Lei 11.105/2005 e CTNBio. Projetos de pesquisa devem ser aprovados pela CTNBio. A liberação comercial requer avaliação de riscos. O Brasil tem centros de clonagem (embrapa, universidades).`},{id:`andro-330`,banca:`FCC`,ano:2022,prova:`FCC — Veterinário IBAMA 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Responsabilidade técnica`,dificuldade:`medio`,enunciado:`O profissional que assume a responsabilidade técnica (RT) de uma central de IA:`,alternativas:[`Deve ser médico veterinário com registro ativo no CRMV, responder civil e éticamente pela qualidade do sêmen e saúde dos animais.`,`Pode ser qualquer profissional da saúde.`,`Não precisa de registro no CRMV.`,`Não responde por eventuais danos.`,`Apenas responde administrativamente.`],resposta_correta:`A`,explicacao:`A RT: médico veterinário (CRMV ativo), responde civilmente (danos materiais/morais), eticamente (Código de Ética CFMV), administrativamente (MAPA, multas). Escopo: qualidade do sêmen, saúde dos reprodutores, biossegurança, cumprimento de normas.`},{id:`andro-331`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Vacinação B19`,dificuldade:`facil`,enunciado:`A vacina B19 contra brucelose bovina:`,alternativas:[`É aplicada em fêmeas de 3-8 meses de idade, por via subcutânea, com dose de 2-5 mL (dependendo do fabricante).`,`É aplicada em machos adultos.`,`É aplicada em fêmeas de qualquer idade.`,`É via oral.`,`Não é obrigatória.`],resposta_correta:`A`,explicacao:`A vacina B19 (Brucella abortus cepa B19): aplicação em fêmeas bovinas e bubalinas de 3-8 meses, dose subcutânea (3 mL na maioria dos fabricantes). Registre a vacinação (nota fiscal, aplicador, animal). Touros não devem ser vacinados.`},{id:`andro-332`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Certificação para exportação`,dificuldade:`medio`,enunciado:`A certificação sanitária para exportação de sêmen bovino do Brasil requer:`,alternativas:[`Negociação bilateral entre Brasil e país importador, com protocolo sanitário específico, e cumprimento de todos os requisitos do país de destino.`,`Apenas certificado do CRMV.`,`Apenas registro no MAPA.`,`Não existe certificação para exportação.`,`Apenas para sêmen de raças europeias.`],resposta_correta:`A`,explicacao:`Exportação de sêmen: protocolo sanitário bilateral (negociado entre MAPA e autoridade do país importador), exames específicos (variáveis por país), quarentena, rastreabilidade, certificação da central e do doador. Países como EUA, UE, Austrália têm requisitos rigorosos.`},{id:`andro-333`,banca:`UFMT`,ano:2023,prova:`UFMT — Concurso Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Obrigações da central`,dificuldade:`medio`,enunciado:`As obrigações de uma central de IA registrada no MAPA incluem:`,alternativas:[`Manter registros atualizados, controle de qualidade, exames sanitários, responsabilidade técnica e permitir fiscalização.`,`Apenas manter registros.`,`Apenas exames sanitários.`,`Apenas fiscalização.`,`Não existem obrigações específicas.`],resposta_correta:`A`,explicacao:`Obrigações (IN 33/2004): manter registros (doador, lote, qualidade, destino), controle de qualidade (parâmetros mínimos), exames sanitários periódicos, RT com CRMV ativo, permitir inspeção do MAPA, rastreabilidade, certificado de aptidão sanitária.`},{id:`andro-334`,banca:`UFBA`,ano:2022,prova:`UFBA — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Sistema de defesa sanitária`,dificuldade:`medio`,enunciado:`O sistema de defesa sanitária animal no Brasil:`,alternativas:[`É tripartite (federal, estadual, municipal), com coordenação do MAPA e execução compartilhada com estados e municípios.`,`É apenas federal.`,`É apenas estadual.`,`Não existe sistema integrado.`,`É apenas municipal.`],resposta_correta:`A`,explicacao:`O sistema de defesa sanitária: coordenação federal (MAPA/SDV), execução estadual (agências estaduais de defesa agropecuária) e municipal (vigilância local). Integração via acordos de cooperação, compartilhamento de informações e programas conjuntos.`},{id:`andro-335`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso Médico Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Incentivos à pecuária`,dificuldade:`medio`,enunciado:`Os programas de incentivo à pecuária no Brasil incluem:`,alternativas:[`Programas como o Plano Safra, Pronaf, financiamento rural (BNDES, Banco do Brasil) para aquisição de reprodutores, equipamentos de IA e melhoramento genético.`,`Apenas subsídios para exportação.`,`Apenas para pequenos produtores.`,`Não existem programas de incentivo.`,`Apenas para gado leiteiro.`],resposta_correta:`A`,explicacao:`Programas de incentivo: Plano Safra (crédito rural), Pronaf (agricultura familiar), BNDES (investimento em infraestrutura), linha de crédito para melhoramento genético (aquisição de reprodutores, IA, FIV). Incentivam a modernização da pecuária.`},{id:`andro-336`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Comércio interestadual`,dificuldade:`medio`,enunciado:`A movimentação interestadual de sêmen congelado no Brasil:`,alternativas:[`Deve seguir as normas do MAPA (IN 33/2004), com documentação sanitária, rastreabilidade e atendimento às exigências do estado de destino.`,`Não é regulamentada.`,`É proibida.`,`Pode ser feita sem documentação.`,`Apenas para sêmen fresco.`],resposta_correta:`A`,explicacao:`Movimentação interestadual: documentação sanitária (nota fiscal, certificado do doador, laudo de qualidade), rastreabilidade, atendimento a eventuais exigências estaduais adicionais, transporte adequado (N₂ líquido).`},{id:`andro-337`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário Prefeitura 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Atribuições do fiscal MAPA`,dificuldade:`medio`,enunciado:`O fiscal federal agropecuário do MAPA:`,alternativas:[`É responsável pela inspeção sanitária de centrais de IA, verificação de documentos, aplicação de multas e interdição em caso de irregularidades.`,`Apenas inspeciona carnes.`,`Não fiscaliza centrais de IA.`,`Apenas emite certificados.`,`Não tem poder de polícia.`],resposta_correta:`A`,explicacao:`O fiscal do MAPA (cargo de Analista/Médico Veterinário MAPA): inspeciona centrais de IA, verifica documentação, coleta amostras, aplica penalidades (multas, interdição, embargo), emite autos de infração, acompanha quarentenas e investigações epidemiológicas.`},{id:`andro-338`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Controle de BVD`,dificuldade:`medio`,enunciado:`O vírus da diarreia viral bovina (BVDV):`,alternativas:[`Pode causar doença reprodutiva (aborto, malformações congênitas, infertilidade) e é exigido exame sorológico para touros doadores de sêmen.`,`Causa apenas diarreia em bezerros.`,`Não afeta o sistema reprodutivo.`,`Não tem controle no Brasil.`,`Causa apenas doença respiratória.`],resposta_correta:`A`,explicacao:`BVDV causa: infecção persistente (animais PI), doença reprodutiva (aborto, malformações congênitas, morte embrionária, infertilidade), doença respiratória. Exigido sorologia para touros doadores (IN 33/2004). Vacinação disponível.`},{id:`andro-339`,banca:`UFPR`,ano:2022,prova:`UFPR — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Quarentena para touros`,dificuldade:`medio`,enunciado:`A quarentena para touros que ingressam em centrais de IA:`,alternativas:[`É obrigatória (30-60 dias), com exames sorológicos (Brucella, IBR, BVD, leucose), isolamento e avaliação andrológica antes da entrada no plantel.`,`Não é obrigatória.`,`Apenas para touros importados.`,`Apenas de 7 dias.`,`Apenas para touros jovens.`],resposta_correta:`A`,explicacao:`Quarentena obrigatória: 30-60 dias, isolamento em área separada, exames sorológicos (Brucella, IBR/BHV-1, BVD, leucose, tuberculose), exame andrológico, avaliação clínica. Após quarentena, liberação para o plantel de doadores.`},{id:`andro-340`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Animais transgênicos`,dificuldade:`dificil`,enunciado:`A produção de animais transgênicos no Brasil:`,alternativas:[`Requer aprovação da CTNBio, cumprimento da Lei 11.105/2005 e, para liberação comercial, avaliação de impacto ambiental (IBAMA).`,`É proibida.`,`Não é regulamentada.`,`Pode ser feita sem aprovação.`,`Apenas para uso militar.`],resposta_correta:`A`,explicacao:`Animais transgênicos: aprovação da CTNBio (avaliação de risco), cumprimento da Lei 11.105/2005, EIA/RIMA (IBAMA) para liberação comercial, rastreabilidade e rotulagem. O Brasil produz peixes transgênicos (tilápia) e pesquisa em bovinos.`},{id:`andro-341`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Exames para touros doadores`,dificuldade:`medio`,enunciado:`Os exames obrigatórios para touros doadores de sêmen no Brasil incluem:`,alternativas:[`Brucelose (soroaglutinação), IBR (sorologia), BVD (sorologia), leucose (ELISA/AGID), tuberculose (tuberculinização).`,`Apenas brucelose.`,`Apenas tuberculose.`,`Apenas exame andrológico.`,`Não existem exames obrigatórios.`],resposta_correta:`A`,explicacao:`Exames obrigatórios (IN 33/2004): brucelose (prova de soroaglutinação), IBR/BHV-1 (virologia/sorologia), BVD (sorologia), leucose (ELISA ou AGID), tuberculose (tuberculinização dupla intradermica). Periodicidade: anual ou conforme norma.`},{id:`andro-342`,banca:`UFBA`,ano:2021,prova:`UFBA — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Interdição de central`,dificuldade:`medio`,enunciado:`Uma central de IA pode ser interditada pelo MAPA quando:`,alternativas:[`Houver descumprimento das normas sanitárias, irregularidades na documentação, surto de doenças ou falta de responsabilidade técnica.`,`Apenas por falta de pagamento de impostos.`,`Apenas por problemas trabalhistas.`,`Não pode ser interditada.`,`Apenas se houver denúncia formal.`],resposta_correta:`A`,explicacao:`Motivos de interdição: irregularidades sanitárias (doenças não controladas), documentação inadequada (registros, laudos), falta de RT, descumprimento de normas, surtos de DSTs, falhas de biossegurança. A interdição é aplicada pelo fiscal do MAPA.`},{id:`andro-343`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso Médico Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Acordos internacionais`,dificuldade:`dificil`,enunciado:`Os acordos sanitários internacionais para comércio de sêmen:`,alternativas:[`São negociados bilateralmente entre países, estabelecendo requisitos sanitários específicos para cada par comercial.`,`São padronizados pela OMS.`,`Não existem acordos para sêmen.`,`São apenas para animais vivos.`,`São determinados unilateralmente pelo exportador.`],resposta_correta:`A`,explicacao:`Acordos sanitários: negociação bilateral (MAPA ↔ autoridade do país importador), protocolos específicos (exames, quarentena, certificação). Ex.: Brasil-EUA, Brasil-UE, Brasil-Austrália. A WOAH fornece diretrizes, mas os acordos são bilaterais.`},{id:`andro-344`,banca:`CESPE`,ano:2020,prova:`CESPE — Professor Universitário 2020`,tipo:`pos`,topico:`legislacao_andrologia`,subtopico:`Propriedade intelectual`,dificuldade:`dificil`,enunciado:`A proteção de cultivares no Brasil (Lei 9.456/1997):`,alternativas:[`Permite o registro e proteção de variedades melhoradas de animais, concedendo ao obtentor direitos exclusivos sobre a reprodução e comercialização.`,`Apenas protege plantas.`,`Não existe proteção para animais.`,`Proíbe a reprodução de raças melhoradas.`,`Apenas para uso científico.`],resposta_correta:`A`,explicacao:`A Lei 9.456/1997 protege variedades melhoradas (cultivares): animais e plantas. O obtentor registra a variedade no MAPA e tem direitos exclusivos (produção, comercialização). Terceiros precisam de autorização para reproduzir/comercializar. Protege investimentos em melhoramento genético.`},{id:`andro-345`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário IBAMA 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Responsabilidade civil do veterinário`,dificuldade:`medio`,enunciado:`A responsabilidade civil do médico veterinário em andrologia:`,alternativas:[`É subjetiva (baseada em culpa: negligência, imprudência, imperícia) e objetiva (baseada no risco da atividade), conforme o CDC e o Código Civil.`,`É apenas objetiva.`,`É apenas subjetiva.`,`Não existe responsabilidade civil.`,`Apenas penal.`],resposta_correta:`A`,explicacao:`Responsabilidade civil: subjetiva (Código Civil: culpa = negligência, imprudência, imperícia) e objetiva (CDC: risco da atividade, relação de consumo). Em andrologia: danos por sêmen contaminado, falha em diagnóstico, erro em IA, transmissão de DST.`},{id:`andro-346`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Controle de insetos e roedores`,dificuldade:`medio`,enunciado:`O controle de insetos e roedores em centrais de IA é importante porque:`,alternativas:[`Vetores mecânicos podem transmitir agentes patogênicos (vírus, bactérias) ao sêmen, contaminando doses inseminantes.`,`Apenas por estética.`,`Não tem relevância sanitária.`,`Apenas para proteger equipamentos.`,`Apenas para evitar incêndios.`],resposta_correta:`A`,explicacao:`Insetos (moscas, mosquitos) e roedores podem ser vetores mecânicos de patógenos (vírus, bactérias) que contaminam o sêmen, diluentes e equipamentos. Programa de controle integrado de pragas é obrigatório em centrais de IA para biossegurança.`},{id:`andro-347`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Vigilância epidemiológica`,dificuldade:`medio`,enunciado:`A vigilância epidemiológica de doenças reprodutivas em bovinos:`,alternativas:[`Inclui notificação compulsória, investigação de surtos, monitoramento de rebanhos e medidas de controle, coordenada pelo MAPA.`,`Não é realizada no Brasil.`,`Apenas para aftosa.`,`Apenas em rebanhos de leite.`,`Apenas para tuberculose.`],resposta_correta:`A`,explicacao:`Vigilância epidemiológica: notificação compulsória (brucelose, campilobacterose, tricomonose), investigação de surtos, monitoramento sorológico, rastreabilidade, medidas de controle (quarentena, vacinação, abate). Coordenada pelo MAPA/SDV.`},{id:`andro-348`,banca:`UFMT`,ano:2021,prova:`UFMT — Concurso Veterinário 2021`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Aproveitamento de touros`,dificuldade:`medio`,enunciado:`O reaproveitamento de touros reprodutores após tratamento de infertilidade:`,alternativas:[`Depende da causa da infertilidade, resposta ao tratamento e reavaliação andrológica com parâmetros seminais dentro dos limites de referência.`,`Não é permitido.`,`É sempre permitido.`,`Apenas após 10 anos.`,`Apenas com autorização do CRMV.`],resposta_correta:`A`,explicacao:`O reaproveitamento: avaliar causa (tratável vs irreversível), resposta ao tratamento, reavaliação andrológica completa (libido, genital, sêmen). Se parâmetros dentro da normalidade, pode ser liberado para uso. Infecções crônicas (Brucella, Trichomonas) → descarte.`},{id:`andro-349`,banca:`UFBA`,ano:2020,prova:`UFBA — Concurso Veterinário 2020`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Inseminação artificial e legislação`,dificuldade:`medio`,enunciado:`A inseminação artificial no Brasil:`,alternativas:[`É regulamentada pelo MAPA, com normas para produção, comercialização e uso de sêmen, e deve ser realizada por médico veterinário ou sob sua supervisão.`,`Pode ser realizada por qualquer pessoa.`,`Não é regulamentada.`,`É proibida por lei.`,`Apenas para uso experimental.`],resposta_correta:`A`,explicacao:`A IA é regulamentada pelo MAPA (IN 33/2004). A inseminação deve ser realizada por médico veterinário ou profissional treinado sob supervisão direta do RT. O uso de sêmen não registrado ou sem documentação é irregularidade sanitária.`},{id:`andro-350`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`legislacao_andrologia`,subtopico:`Desafios da andrologia`,dificuldade:`medio`,enunciado:`Os principais desafios da andrologia veterinária no Brasil incluem:`,alternativas:[`Controle de DSTs, melhoramento genético sustentável, biotecnologias reprodutivas, legislação atualizada e formação profissional especializada.`,`Apenas controle de DSTs.`,`Apenas formação profissional.`,`Apenas legislação.`,`Não existem desafios.`],resposta_correta:`A`,explicacao:`Desafios: controle de DSTs (brucelose, tricomonose, campilobacterose), melhoramento genético com sustentabilidade, avanço de biotecnologias (sexagem, FIV, clonagem), atualização legislativa, formação de profissionais especializados, bem-estar animal, rastreabilidade.`}],i={total_questoes:350,por_topico:{anatomia_reprodutiva_masculina:23,espermatogenese:19,endocrinologia_reprodutiva_masculina:18,semen:22,inseminacao_artificial:21,biotecnologias_reprodutivas:20,patologia_reprodutiva_masculina:26,infertilidade_masculina:15,criopreservacao:20,andrologia_bovina:20,andrologia_equina:19,andrologia_canina:19,andrologia_suina:18,andrologia_ovina_caprina:20,legislacao_andrologia:70},por_banca:{ENAV:40,CESPE:39,FCC:35,VUNESP:35,AVAMEC:17,CRMV:15,UFMG:15,UNESP:15,USP:15,UFRRJ:18,MAPA:16,UFMT:23,UFBA:22,UFPE:5,UFPR:13,UFRGS:17,UFRPE:10},por_dificuldade:{facil:69,medio:214,dificil:67},por_tipo:{concurso:272,residencia:0,enav:0,crmv:15,pos:63}};export{e as BANCAS,i as ESTATISTICAS_BANCO,r as QUESTOES_ANDROLOGIA,t as TIPOS_PROVA,n as TOPICOS_ANDROLOGIA};